    WITHOUT FUNCTION
    AS IMPLICIT;

--
-- Cette fonction retourne pour une spécialité si c'est un BIO_SIMILAIRE  Oui ou non
-- Exemple : select is_biosim('6 794 502 3');
--
CREATE
OR REPLACE FUNCTION thesorimed.is_biosim(varchar(13)) RETURNS character varying AS
'
    DECLARE
        cis ALIAS FOR $1; BIO INTEGER := 0; REP character varying;
BEGIN SELECT count(*)
      INTO BIO
      FROM SP_BIOSIMILAIRE
      WHERE SPB_CODE_CIS = cis
    ; IF (BIO = 0)
         THEN
      REP := ''NON''; ELSE
      REP := ''OUI''; END IF; RETURN REP; END;

' LANGUAGE 'plpgsql';

--
-- Cette fonction retourne pour une spécialité si c'est un NMVS (sérialisable) Oui ou non
--
CREATE
OR REPLACE FUNCTION thesorimed.is_nmvs(VARCHAR(13)) RETURNS character varying AS
'
    DECLARE
        idpre ALIAS FOR $1; NMVS INTEGER := 0; REP character varying;
BEGIN SELECT count(*)
      INTO NMVS
      FROM prestr_statut_rembourst
      where prestr_pre_code_fk_pk = idpre
        and prestr_cdf_str_code_fk_pk = ''R9920''; IF (NMVS = 0)
                                                      THEN
            REP = ''N''; ELSE
            REP = ''O''; END IF; RETURN REP; END;

' LANGUAGE 'plpgsql';

--
-- Cette fonction retourne une liste de CIP (exemple : pour IDSPE = 156
--
CREATE
OR REPLACE FUNCTION thesorimed.get_cip(NUMERIC(6)) RETURNS character varying AS
'
    DECLARE
        idspe ALIAS FOR $1; rec RECORD; nb INTEGER := 0; LST_CIP character varying;
BEGIN FOR rec IN SELECT PRE_CODE_PK AS CIP
                 FROM PRE_PRESENTATION
                 WHERE PRE_SP_CODE_FK = idspe
                   AND PRE_ETAT_COMMER = ''D'' LOOP
                IF nb = 0 THEN
                    LST_CIP := rec.CIP; ELSE
                    LST_CIP := LST_CIP || '', '' || rec.CIP; END IF; nb := nb + 1; END LOOP; RETURN LST_CIP; END;

' LANGUAGE 'plpgsql';

--
-- Cette fonction retourne une liste des formes idspe = 4561
--
CREATE
OR REPLACE FUNCTION thesorimed.get_frm(NUMERIC(6)) RETURNS character varying AS
'
    DECLARE
        idspe ALIAS FOR $1; rec RECORD; nb INTEGER := 0; LST_FRM character varying;
BEGIN FOR rec IN SELECT CDF_NOM as FRM
                 FROM CDF_CODIF,
                      SPFO_SPECIALITE_FORME
                 WHERE SPFO_SP_CODE_FK_PK = idspe
                   AND CDF_CODE_PK = SPFO_CDF_FO_CODE_FK_PK
                   AND CDF_NUMERO_PK = ''06''
                 ORDER BY SPFO_NUMORD LOOP
                IF nb = 0 THEN
                    LST_FRM := rec.FRM; ELSE
                    LST_FRM := LST_FRM || '', '' || rec.FRM; END IF; nb := nb + 1; END LOOP; RETURN LST_FRM; END;

' LANGUAGE 'plpgsql';

--
-- Cette fonction retourne une liste des voies idspe = 4561
--
CREATE
OR REPLACE FUNCTION thesorimed.get_voie(NUMERIC(6)) RETURNS character varying AS
'
    DECLARE
        idspe ALIAS FOR $1; rec RECORD; nb INTEGER := 0; LST_VOIE character varying;
BEGIN FOR rec IN SELECT CDF_NOM as VOIE
                 FROM CDF_CODIF,
                      SPVO_SPECIALITE_VOIE
                 WHERE SPVO_SP_CODE_FK_PK = idspe
                   AND CDF_CODE_PK = SPVO_CDF_VO_CODE_FK_PK
                   AND CDF_NUMERO_PK = ''18''
                 ORDER BY SPVO_NUMSEQ LOOP
                IF nb = 0 THEN
                    LST_VOIE := rec.VOIE; ELSE
                    LST_VOIE := LST_VOIE || '', '' || rec.VOIE; END IF; nb := nb + 1; END LOOP; RETURN LST_VOIE; END;

' LANGUAGE 'plpgsql';

--
-- Cette fonction retourne le statut ATU O ou N test : idspe = 7087 (PROSTIGMIN : Oui) / 8849 (EPREX : Non)
--
CREATE
OR REPLACE FUNCTION thesorimed.is_atu(NUMERIC(6)) RETURNS character varying AS
'
    DECLARE
        idspe ALIAS FOR $1; rec RECORD; O INTEGER := 0; N INTEGER := 0; ATU character varying;
BEGIN SELECT DISTINCT COUNT(*)
      INTO O
      FROM SP_SPECIALITE
               JOIN CDF_CODIF CDF ON (CDF.CDF_CODE_PK = SP_CDF_SLAB_CODE_FK
          AND CDF.CDF_NUMERO_PK = ''15''
          AND CDF.CDF_CODE_PK = ''6'')
      WHERE SP_CODE_SQ_PK = idspe;

    SELECT DISTINCT COUNT(*)
    INTO N
    FROM SP_SPECIALITE
             JOIN CDF_CODIF CDF ON (CDF.CDF_CODE_PK = SP_CDF_SLAB_CODE_FK
        AND CDF.CDF_NUMERO_PK = ''15''
        AND CDF.CDF_CODE_PK != ''6'')
    WHERE SP_CODE_SQ_PK = idspe; IF (N > O)
                                    THEN
            ATU = ''N''; ELSE
            ATU = ''O''; END IF; RETURN ATU; END;

' LANGUAGE 'plpgsql';

--
-- Cette fonction retourne le statut RETROCESSION test : idspe = 36271 (TIVICAY : Oui) / 8849 (EPREX : Non)
--
CREATE
OR REPLACE FUNCTION thesorimed.is_retro(NUMERIC(6)) RETURNS character varying AS
'
    DECLARE
        idspe ALIAS FOR $1; RETRO character varying;
BEGIN SELECT DISTINCT CASE WHEN PRIUCD.PRIUCD_UCD_CODE_PK IS NULL THEN ''N'' ELSE ''O''
      INTO RETRO END
      FROM SP_SPECIALITE SP
                                      LEFT JOIN (
                                      SELECT PRIUCD_UCD_CODE_PK, MAX(PRIUCD_DATE_APPLI_PK) as PRIUCD_DATE_APPLI_PK
                                      FROM PRIUCD_PRIX_UCD PRIUCD
                                      GROUP BY PRIUCD_UCD_CODE_PK) prixDate
      ON prixDate.PRIUCD_UCD_CODE_PK = SP.SP_CIPUCD
                                      LEFT JOIN PRIUCD_PRIX_UCD PRIUCD
                                      ON PRIUCD.PRIUCD_UCD_CODE_PK = prixDate.PRIUCD_UCD_CODE_PK
                                      AND PRIUCD.PRIUCD_DATE_APPLI_PK = prixDate.PRIUCD_DATE_APPLI_PK
                                      AND PRIUCD.PRIUCD_CODE_LISTE_PK = 2
      WHERE SP.SP_CODE_SQ_PK = idspe
    ; RETURN RETRO; END;

' LANGUAGE 'plpgsql';

--
-- Cette fonction retourne le statut T2A test : idspe = 8849 (EPREX : Oui)
--
CREATE
OR REPLACE FUNCTION thesorimed.is_t2a(NUMERIC(6)) RETURNS character varying AS
'
    DECLARE
        idspe ALIAS FOR $1; T2A character varying;
BEGIN SELECT DISTINCT CASE
                                                      WHEN s311.spcpd_sp_code_fk_pk IS NULL
                                                          AND s312.spcpd_sp_code_fk_pk IS NULL
                                                          AND s313.spcpd_sp_code_fk_pk IS NULL
                                                          THEN ''N''
                                                      ELSE
                                                                  CASE
                                                                      WHEN s311.spcpd_sp_code_fk_pk IS NULL THEN ''''
                                                                      ELSE ''SSR '' END ||
                                                                  CASE
                                                                      WHEN s312.spcpd_sp_code_fk_pk IS NULL THEN ''''
                                                                      ELSE ''HAD '' END ||
                                                                  CASE
                                                                      WHEN s313.spcpd_sp_code_fk_pk IS NULL THEN ''''
                                                                      ELSE ''T2A'' END
                                                      END
      INTO T2A
      FROM SP_SPECIALITE SP
               LEFT JOIN vspcpd_spe_cdt_prescr s311
                         ON s311.spcpd_sp_code_fk_pk = sp.sp_code_sq_pk
                             AND s311.spcpd_cdf_stp_code_fk_pk = ''S311''
               LEFT JOIN vspcpd_spe_cdt_prescr s312
                         ON s312.spcpd_sp_code_fk_pk = sp.sp_code_sq_pk
                             AND s312.spcpd_cdf_stp_code_fk_pk = ''S312''
               LEFT JOIN vspcpd_spe_cdt_prescr s313
                         ON s313.spcpd_sp_code_fk_pk = sp.sp_code_sq_pk
                             AND s313.spcpd_cdf_stp_code_fk_pk = ''S313''
      WHERE SP.SP_CODE_SQ_PK = idspe
    ; RETURN T2A; END;

' LANGUAGE 'plpgsql';

--
-- Cette fonction retourne les conditions de conservation pour un CIP donné test : 3400955849513
--
DROP FUNCTION IF EXISTS thesorimed.get_cons(VARCHAR(13), NUMERIC);
DROP FUNCTION IF EXISTS thesorimed.get_cons(NUMERIC, NUMERIC);
CREATE
    OR REPLACE FUNCTION thesorimed.get_cons(NUMERIC, NUMERIC) RETURNS TEXT AS
$$
DECLARE
    speId ALIAS FOR $1;
    numord ALIAS FOR $2;
    result                                       TEXT := ''; -- Variable pour stocker la chaîne résultante
    rec                                          RECORD; -- Variable pour parcourir les résultats de la requête
BEGIN
    -- Boucle sur les résultats de la requête
    FOR rec IN (SELECT DISTINCT CDF_NOM as CONS,
                                percs.PERCS_NUMORD
                FROM PRE_PRESENTATION pre
                         JOIN PERCS_PERIODE_COND_CSV percs
                              ON pre.PRE_CODE_PK = percs.PERCS_PRE_CODE_FK_PK
                                  AND percs.PERCS_NUM_CODE_PK = numord
                         JOIN CDF_CODIF cdf
                              ON cdf.CDF_CODE_PK = percs.PERCS_CDF_CSV_CODE_FK_PK
                                  AND cdf.CDF_NUMERO_PK = '03'
                WHERE pre.PRE_SP_CODE_FK = speId
                ORDER BY percs.PERCS_NUMORD) LOOP
        -- Concaténer la valeur actuelle avec le séparateur si nécessaire
            IF result != '' THEN
                result := result || ', ';
            END IF;
            result := result || rec.CONS;
        END LOOP;

    -- Retourner la chaîne résultante
    RETURN result;
END;
$$ LANGUAGE plpgsql;

--
-- Cette fonction retourne une liste de code NGAP pour un IDSPE (38867) : ex = select get_ngap(38867);
--
CREATE
OR REPLACE FUNCTION thesorimed.get_ngap(numeric) RETURNS character varying AS
'
    DECLARE
        idspe ALIAS FOR $1; rec RECORD; cnt INTEGER := 0; LST_NGAP character varying ;
BEGIN FOR rec IN SELECT DISTINCT NGA_CODE_PK AS NGAP
                 FROM PRE_PRESENTATION PRE
                          LEFT JOIN VNGAPRE_NGA_PRESENTATION NGA ON NGA.PRE_CODE_PK = PRE.PRE_CODE_PK
                 WHERE PRE_SP_CODE_FK = idspe
                   AND PRE_ETAT_COMMER = ''D'' LOOP
                IF cnt = 0 THEN
                    LST_NGAP := rec.NGAP; ELSE
                    LST_NGAP := LST_NGAP || '', '' || rec.NGAP; END IF; cnt := cnt + 1; END LOOP; RETURN LST_NGAP; END;

' LANGUAGE 'plpgsql';

--
-- Cette fonction retourne le libelle GSP
--
CREATE
OR REPLACE FUNCTION thesorimed.get_lb_gsp(NUMERIC(6)) RETURNS character varying AS
'
    DECLARE
        idgsp ALIAS FOR $1; LBL character varying;
BEGIN SELECT GSP_NOM
      INTO LBL
      FROM V_GSP_LIBELLE
      where GSP_CODE_FK = idgsp
    ; RETURN LBL; END;

' LANGUAGE 'plpgsql';

-- Spécialités équivalentes ou génériques
-- TFL-1393 - 2023-04-13
-- TFL-1407 - 2023-05-11
-- TFL-1415 - 2023-06-21
-- EXEMPLE : select GET_THE_GEN_EQUIV('13520', 1);
-- EXEMPLE : select GET_THE_GEN_EQUIV('49233', 2);
CREATE
OR REPLACE FUNCTION GET_THE_GEN_EQUIV(NUMERIC, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        CODEID ALIAS FOR $1; VARTYP ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF VARTYP = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT gsp.GSP_NOM,
                                    speRef.SP_CODE_SQ_PK           AS SP_PARAM,
                                    get_lb_gsp(gsp.GSP_CODE_SQ_PK) AS LIB_VIRT,
                                    spe.SP_NOM                     AS SP_CODE_EQUIV,
                                    spe.SP_CODE_SQ_PK              AS SP_CODE,
                                    CASE
                                        WHEN gener.ANSMGEN_TYPGEN_FK = 0 THEN ''''R''''
                                        WHEN gener.ANSMGEN_TYPGEN_FK IS NOT NULL THEN ''''G''''
                                        ELSE ''''E'''' END    AS STATUT_GRP,
                                    gener.GRP_ID_GENER,
                                    gener.GRP_LIB_GENER
                    FROM SP_SPECIALITE speRef
                             JOIN GSP_GENERIQUE_SPECIALITE gsp
                                  ON speRef.SP_GSP_CODE_FK = gsp.GSP_CODE_SQ_PK
                             JOIN SP_SPECIALITE spe
                                  ON gsp.GSP_CODE_SQ_PK = spe.SP_GSP_CODE_FK
                             LEFT JOIN (SELECT gener.ANSMGEN_SP_CODE_SQ_PK,
                                               gener.ANSMGEN_TYPGEN_FK,
                                               grp.ANSMGRP_CODE_PK AS GRP_ID_GENER,
                                               grp.ANSMGRP_LIBELLE AS GRP_LIB_GENER
                                        FROM ANSM_GENER gener
                                                 JOIN ANSM_GROUP grp
                                                      ON gener.ANSMGEN_GRP_CODE_PK = grp.ANSMGRP_CODE_PK
                                                          AND (grp.ANSMGRP_DATE_FIN IS NULL OR grp.ANSMGRP_DATE_FIN > now())
                                                 JOIN ANSM_TYPE_GENER typeg
                                                      ON gener.ANSMGEN_TYPGEN_FK = typeg.ANSMTYPGEN_CODE_PK
                                        WHERE (gener.ANSMGEN_DATEFIN IS NULL OR gener.ANSMGEN_DATEFIN > now())) gener
                                       ON spe.SP_CODE_SQ_PK = gener.ANSMGEN_SP_CODE_SQ_PK
                    WHERE speRef.SP_CODE_SQ_PK = '''''' || CODEID || ''''''
                ORDER BY gsp.GSP_NOM,
                         gener.GRP_LIB_GENER,
                         STATUT_GRP DESC,
                         spe.SP_NOM
        '';
        END IF;
        IF VARTYP = 2 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT gsp.GSP_NOM,
                                    generRef.ANSMGEN_SP_CODE_SQ_PK AS SP_PARAM,
                                    get_lb_gsp(gsp.GSP_CODE_SQ_PK) AS LIB_VIRT,
                                    spe.SP_NOM                     AS SP_CODE_EQUIV,
                                    spe.SP_CODE_SQ_PK              AS SP_CODE,
                                    CASE
                                        WHEN gener.ANSMGEN_TYPGEN_FK = 0 THEN ''''R''''
                                        WHEN gener.ANSMGEN_TYPGEN_FK IS NOT NULL THEN ''''G''''
                                        ELSE ''''E'''' END               AS STATUT_GRP,
                                    gener.GRP_ID_GENER,
                                    gener.GRP_LIB_GENER
                    FROM ANSM_GENER generRef
                        JOIN ANSM_GROUP grpRef
                             ON generRef.ANSMGEN_GRP_CODE_PK = grpRef.ANSMGRP_CODE_PK
                                 AND (grpRef.ANSMGRP_DATE_FIN IS NULL OR grpRef.ANSMGRP_DATE_FIN > now())
                             LEFT JOIN (SELECT gener.ANSMGEN_SP_CODE_SQ_PK,
                                               gener.ANSMGEN_TYPGEN_FK,
                                               grp.ANSMGRP_CODE_PK            AS GRP_ID_GENER,
                                               grp.ANSMGRP_LIBELLE            AS GRP_LIB_GENER
                                        FROM ANSM_GENER gener
                                                 JOIN ANSM_GROUP grp
                                                      ON gener.ANSMGEN_GRP_CODE_PK = grp.ANSMGRP_CODE_PK
                                                          AND (grp.ANSMGRP_DATE_FIN IS NULL OR grp.ANSMGRP_DATE_FIN > now())
                                                 JOIN ANSM_TYPE_GENER typeg
                                                      ON gener.ANSMGEN_TYPGEN_FK = typeg.ANSMTYPGEN_CODE_PK
                                        WHERE (gener.ANSMGEN_DATEFIN IS NULL OR gener.ANSMGEN_DATEFIN > now())) gener
                                       ON generRef.ANSMGEN_GRP_CODE_PK = gener.GRP_ID_GENER
                             LEFT JOIN SP_SPECIALITE spe
                                       ON gener.ANSMGEN_SP_CODE_SQ_PK = spe.SP_CODE_SQ_PK
                             LEFT JOIN GSP_GENERIQUE_SPECIALITE gsp
                                       ON spe.SP_GSP_CODE_FK = gsp.GSP_CODE_SQ_PK
                    WHERE generRef.ANSMGEN_SP_CODE_SQ_PK = '''''' || CODEID || ''''''
                    AND (generRef.ANSMGEN_DATEFIN IS NULL OR generRef.ANSMGEN_DATEFIN > now())
                ORDER BY gsp.GSP_NOM,
                         gener.GRP_LIB_GENER,
                         STATUT_GRP DESC,
                         spe.SP_NOM
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API EEN - TFL-1354
-- EXEMPLE: CIS_OU_SPE_ID := '24258' ou '40311' ou '6 056 285 5' ou '6 777 037 8'
-- DROP FUNCTION EEN(VARCHAR);
CREATE
OR REPLACE FUNCTION EEN(VARCHAR) RETURNS REFCURSOR AS
'
    DECLARE
        CIS_OU_SPE_ID ALIAS FOR $1;
        CURRET REFCURSOR;
    BEGIN
        OPEN CURRET FOR EXECUTE ''SELECT VCISEEN_EEN_OUI_NON AS EEN,
                       VCISEEN_CHAMPS      AS EEN_TEXTE
                FROM VCISEEN_CIS_EEN vcis
                WHERE vcis.VCISEEN_CIS_CODE_FK_PK = '''''' || CIS_OU_SPE_ID || ''''''
                UNION
                SELECT VCISEEN_EEN_OUI_NON AS EEN,
                       VCISEEN_CHAMPS      AS EEN_TEXTE
                FROM SP_SPECIALITE spe
                         JOIN VCISEEN_CIS_EEN vcis
                              ON vcis.VCISEEN_CIS_CODE_FK_PK = spe.SP_NL
                WHERE cast(spe.SP_CODE_SQ_PK as text) = ANY (string_to_array('''''' || CIS_OU_SPE_ID || '''''','''',''''))
        '';
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API GET_THE_SPE_DETAILS
-- EXEMPLE: LISTID := '7690,7335,5925,4143' ET TYPID := 1

-- DROP FUNCTION GET_THE_SPE_DETAILS(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_SPE_DETAILS(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        CODEID ALIAS FOR $1; VARTYP ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF VARTYP = 0 THEN
            OPEN CURRET FOR EXECUTE ''select distinct SP.SP_CODE_SQ_PK, b.CDF_NOM, SP.SP_CATC_CODE_FK, SP.SP_CEPH_CODE_FK,
      SP.SP_NOM, SP.SP_NOMCOMP, SP.SP_CIPUCD, SP.SP_NL, SP.SP_NOMLONG,
      ETAT_COMMERCIALISATION AS ETA_COM, RESERVE_HOSPITALIERE AS RH, get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS MED_VIRT,get_cip(SP.SP_CODE_SQ_PK) AS CIP, get_frm(SP.SP_CODE_SQ_PK) AS FORME,
      get_voie(SP.SP_CODE_SQ_PK) AS VOIE, is_atu(SP.SP_CODE_SQ_PK) AS ATU, is_retro(SP.SP_CODE_SQ_PK) AS RETRO, is_t2a(SP.SP_CODE_SQ_PK) AS T2A, get_ngap(SP.SP_CODE_SQ_PK) AS NGA
      from SP_SPECIALITE SP
      LEFT JOIN GSP_GENERIQUE_SPECIALITE GSP ON GSP.GSP_CODE_SQ_PK = SP.SP_GSP_CODE_FK,
      CDF_CODIF a, CDF_CODIF b, sp_informations INF
      where SP.SP_CDF_SLAB_CODE_FK = a.CDF_CODE_PK and SP.SP_CDF_LI_CODE_FK = b.CDF_CODE_PK
      and a.CDF_NUMERO_PK = ''''15'''' and b.CDF_NUMERO_PK = ''''08'''' and SP.SP_NOM LIKE '''''' || CODEID || '''''' and (SP.SP_CDF_SLAB_CODE_FK  <> ''''7'''' and SP.SP_CDF_SLAB_CODE_FK <> ''''3'''')
      -- Evolution 2,00
      AND INF.SP_CODE_SQ_PK = SP.SP_CODE_SQ_PK
 order by SP_NOM asc
        '';
        END IF;
        IF VARTYP = 1 THEN
            OPEN CURRET FOR EXECUTE ''select distinct SP.SP_CODE_SQ_PK, b.CDF_NOM, SP.SP_CATC_CODE_FK, SP.SP_CEPH_CODE_FK,
      SP.SP_NOM, SP.SP_NOMCOMP, SP.SP_CIPUCD, SP.SP_NL, SP.SP_NOMLONG,
      ETAT_COMMERCIALISATION AS ETA_COM, RESERVE_HOSPITALIERE AS RH, get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS MED_VIRT,get_cip(SP.SP_CODE_SQ_PK) AS CIP, get_frm(SP.SP_CODE_SQ_PK) AS FORME,
      get_voie(SP.SP_CODE_SQ_PK) AS VOIE, is_atu(SP.SP_CODE_SQ_PK) AS ATU, is_retro(SP.SP_CODE_SQ_PK) AS RETRO, is_t2a(SP.SP_CODE_SQ_PK) AS T2A, get_ngap(SP.SP_CODE_SQ_PK) AS NGA
      from SP_SPECIALITE SP
      LEFT JOIN GSP_GENERIQUE_SPECIALITE GSP ON GSP.GSP_CODE_SQ_PK = SP.SP_GSP_CODE_FK,
      CDF_CODIF a, CDF_CODIF b, sp_informations INF
      where SP.SP_CDF_SLAB_CODE_FK = a.CDF_CODE_PK and SP.SP_CDF_LI_CODE_FK = b.CDF_CODE_PK
      and a.CDF_NUMERO_PK = ''''15'''' and b.CDF_NUMERO_PK = ''''08'''' and SP.SP_CODE_SQ_PK = '''''' || CODEID || '''''' and (SP.SP_CDF_SLAB_CODE_FK  <> ''''7'''' and SP.SP_CDF_SLAB_CODE_FK <> ''''3'''')
      -- Evolution 2,00
      AND INF.SP_CODE_SQ_PK = SP.SP_CODE_SQ_PK
 order by SP_NOM asc
        '';
        END IF;
        IF VARTYP = 2 THEN
            OPEN CURRET FOR EXECUTE ''select distinct SP.SP_CODE_SQ_PK, b.CDF_NOM, SP.SP_CATC_CODE_FK, SP.SP_CEPH_CODE_FK,
      SP.SP_NOM, SP.SP_NOMCOMP, SP.SP_CIPUCD, SP.SP_NL, SP.SP_NOMLONG,
      ETAT_COMMERCIALISATION AS ETA_COM, RESERVE_HOSPITALIERE AS RH, get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS MED_VIRT,get_cip(SP.SP_CODE_SQ_PK) AS CIP, get_frm(SP.SP_CODE_SQ_PK) AS FORME,
      get_voie(SP.SP_CODE_SQ_PK) AS VOIE, is_atu(SP.SP_CODE_SQ_PK) AS ATU, is_retro(SP.SP_CODE_SQ_PK) AS RETRO, is_t2a(SP.SP_CODE_SQ_PK) AS T2A, get_ngap(SP.SP_CODE_SQ_PK) AS NGA
      from SP_SPECIALITE SP
      LEFT JOIN GSP_GENERIQUE_SPECIALITE GSP ON GSP.GSP_CODE_SQ_PK = SP.SP_GSP_CODE_FK,
      CDF_CODIF a, CDF_CODIF b, sp_informations INF
      where SP.SP_CDF_SLAB_CODE_FK = a.CDF_CODE_PK and SP.SP_CDF_LI_CODE_FK = b.CDF_CODE_PK
      and a.CDF_NUMERO_PK = ''''15'''' and b.CDF_NUMERO_PK = ''''08'''' and SP.SP_CIPUCD = '''''' || CODEID || '''''' and (SP.SP_CDF_SLAB_CODE_FK  <> ''''7'''' and SP.SP_CDF_SLAB_CODE_FK <> ''''3'''')
      -- Evolution 2,00
      AND INF.SP_CODE_SQ_PK = SP.SP_CODE_SQ_PK
      order by SP_NOM asc
        '';
        END IF;
        IF VARTYP = 3 THEN
            OPEN CURRET FOR EXECUTE ''
 		select DISTINCT SP.SP_CODE_SQ_PK,
                                   b.CDF_NOM,
                                   SP.SP_CATC_CODE_FK,
                                   SP.SP_CEPH_CODE_FK,
                                   SP_NOM,
                                   SP_NOMCOMP,
                                   SP_CIPUCD,
                                   SP_NL,
                                   SP_NOMLONG,
                                   ETAT_COMMERCIALISATION     AS ETA_COM,
                                   RESERVE_HOSPITALIERE       AS RH,
                                   get_lb_gsp(GSP.GSP_CODE_SQ_PK)                AS MED_VIRT,
                                   get_cip(SP.SP_CODE_SQ_PK)  AS CIP,
                                   get_frm(SP.SP_CODE_SQ_PK)  AS FORME,
                                   get_voie(SP.SP_CODE_SQ_PK) AS VOIE,
                                   is_atu(SP.SP_CODE_SQ_PK)   AS ATU,
                                   is_retro(SP.SP_CODE_SQ_PK) AS RETRO,
                                   is_t2a(SP.SP_CODE_SQ_PK)   AS T2A,
                                   get_ngap(SP.SP_CODE_SQ_PK) AS NGA
                            from PRE_PRESENTATION PRE
                                     JOIN SP_SPECIALITE SP ON PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK
                                     LEFT JOIN GSP_GENERIQUE_SPECIALITE GSP ON GSP.GSP_CODE_SQ_PK = SP.SP_GSP_CODE_FK,
                                 CDF_CODIF a,
                                 CDF_CODIF b,
                                 sp_informations INF
                            where SP_CDF_SLAB_CODE_FK = a.CDF_CODE_PK
                              and SP_CDF_LI_CODE_FK = b.CDF_CODE_PK
                              and a.CDF_NUMERO_PK = ''''15''''
                              and b.CDF_NUMERO_PK = ''''08''''
                              AND PRE.PRE_CODE_PK = '''''' || CODEID || ''''''
                              and (SP_CDF_SLAB_CODE_FK <> ''''7'''' and SP_CDF_SLAB_CODE_FK <> ''''3'''')
                              -- Evolution 2,00
                              AND INF.SP_CODE_SQ_PK = SP.SP_CODE_SQ_PK
                            order by SP_NOM asc;
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- DROP FUNCTION ATC_EPHMRA(VARCHAR,NUMERIC);
CREATE
    OR REPLACE FUNCTION ATC_EPHMRA(NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        CODEID ALIAS FOR $1;
        curRet REFCURSOR;
    BEGIN
        OPEN curRet FOR SELECT catc.CATC_CODE_PK,
                               catc.CATC_NOMF,
                               ceph.CEPH_CODE_PK,
                               ceph.CEPH_NOMF
                        FROM SP_SPECIALITE spe
                                 JOIN GSP_GENERIQUE_SPECIALITE gsp
                                      ON spe.SP_GSP_CODE_FK = gsp.GSP_CODE_SQ_PK
                                 LEFT JOIN CATC_CLASSEATC catc
                                           ON gsp.GSP_CATC_CODE_FK = catc.CATC_CODE_PK
                                 LEFT JOIN CEPH_CLASSEEPHMRA ceph
                                           ON gsp.GSP_CEPH_CODE_FK = ceph.CEPH_CODE_PK
                        WHERE spe.SP_CODE_SQ_PK = CODEID;
        RETURN curRet;
    END;

' LANGUAGE plpgsql;


-- API GET_THE_CONSERVATION_SPE
-- EXEMPLE: CIPUCD := '9348035'

-- DROP FUNCTION GET_THE_CONSERVATION_SPE(VARCHAR);
CREATE
OR REPLACE FUNCTION GET_THE_CONSERVATION_SPE(VARCHAR) RETURNS REFCURSOR AS
'
    DECLARE
        CIPUCD ALIAS FOR $1;
        CURRET REFCURSOR;
    BEGIN
        OPEN CURRET FOR EXECUTE ''
SELECT DISTINCT spe.SP_CIPUCD                                         AS CIP,
                                get_cons(pre.PRE_SP_CODE_FK, spper.SPPER_NUM_CODE_PK) AS COND_CONS,
                                spper.SPPER_DUREE                                     AS DUR_CONS,
                                dur.CDF_NOM                                           AS UNIT_CONS
                FROM SP_SPECIALITE spe
                         JOIN PRE_PRESENTATION pre
                              ON spe.SP_CODE_SQ_PK = pre.PRE_SP_CODE_FK
                         LEFT JOIN SPPER_SPECIALITE_PERIO_CSV spper
                                   ON spe.SP_CODE_SQ_PK = spper.SPPER_SP_CODE_FK_PK
                         LEFT JOIN CDF_CODIF dur
                                   ON (dur.CDF_CODE_PK = spper.SPPER_CDF_UT_CODE_FK
                                       AND dur.CDF_NUMERO_PK = ''''PU'''')
                WHERE SP_CIPUCD = '''''' || CIPUCD || ''''''
                  AND PRE_SP_CODE_FK = SP_CODE_SQ_PK
                UNION
                SELECT DISTINCT pre.PRE_CODE_PK                                       AS CIP,
                                get_cons(pre.PRE_SP_CODE_FK, spper.SPPER_NUM_CODE_PK) AS COND_CONS,
                                spper.SPPER_DUREE                                     AS DUR_CONS,
                                dur.CDF_NOM                                           AS UNIT_CONS
                FROM PRE_PRESENTATION pre
                         LEFT JOIN SPPER_SPECIALITE_PERIO_CSV spper
                                   ON pre.PRE_SP_CODE_FK = spper.SPPER_SP_CODE_FK_PK
                         LEFT JOIN CDF_CODIF dur
                                   ON (dur.CDF_CODE_PK = spper.SPPER_CDF_UT_CODE_FK
                                       AND dur.CDF_NUMERO_PK = ''''PU'''')
                WHERE PRE_CODE_PK = '''''' || CIPUCD || ''''''
'';
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API GET_THE_INTER_SACINTER_SAC
-- EXEMPLE: LISTID := '1299,1761' ET TYPID := 5

-- DROP FUNCTION GET_THE_INTER_SACINTER_SAC(VARCHAR,VARCHAR);
CREATE
OR REPLACE FUNCTION GET_THE_INTER_SACINTER_SAC(VARCHAR, VARCHAR) RETURNS REFCURSOR AS
'
    DECLARE
        LISTESAC ALIAS FOR $1; GRAVITE ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF GRAVITE = ''5'' THEN
            OPEN CURRET FOR EXECUTE ''SELECT IT1SAC_FIT_CODE_FK_PK AS IDINTER, A.SAC_NOM AS TERME_1, SP1.SP_NOM AS SP_NOM1,B.SAC_NOM AS TERME_2, SP2.SP_NOM AS SP_NOM2,
       SP1.SP_CODE_SQ_PK AS ID_T1,
       SP2.SP_CODE_SQ_PK AS ID_T2,
       FITNA_CDF_NAIT_CODE_FK_PK AS NIVEAU
FROM IT1SAC_TERME1SUBACTIVE, IT2SAC_TERME2SUBACTIVE, FITNA_INTERACTION_NATURE, FITVA_NIVEAU_VALIDATION, CDF_CODIF, SAC_SUBACTIVE A
JOIN COSAC_COMPO_SUBACT COS1 on ( COS1.COSAC_SAC_CODE_FK_PK = A.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP1 ON (SP1.SP_CODE_SQ_PK = COS1.COSAC_SP_CODE_FK_PK),
 SAC_SUBACTIVE B
JOIN COSAC_COMPO_SUBACT COS2 on ( COS2.COSAC_SAC_CODE_FK_PK = B.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP2 ON (SP2.SP_CODE_SQ_PK = COS2.COSAC_SP_CODE_FK_PK)
WHERE IT1SAC_FIT_CODE_FK_PK = IT2SAC_FIT_CODE_FK_PK
AND IT1SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT2SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT1SAC_SAC_CODE_FK_PK <> IT2SAC_SAC_CODE_FK_PK
AND A.SAC_CODE_SQ_PK = IT1SAC_SAC_CODE_FK_PK
AND B.SAC_CODE_SQ_PK = IT2SAC_SAC_CODE_FK_PK
AND NOT EXISTS (SELECT IT1SAC_FIT_CODE_FK_PK, IT1SAC_SAC_CODE_FK_PK
                FROM IT1SAC_TERME1SUBACTIVE
                WHERE IT1SAC_FIT_CODE_FK_PK = IT2SAC_FIT_CODE_FK_PK
                AND IT1SAC_SAC_CODE_FK_PK = IT2SAC_SAC_CODE_FK_PK)
AND FITNA_CDF_NAIT_CODE_FK_PK <= '''''' || GRAVITE || ''''''
AND FITNA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND FITVA_CDF_VAIT_CODE_FK_PK = ''''1''''
AND FITVA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND CDF_CODE_PK = FITVA_CDF_VAIT_CODE_FK_PK
AND CDF_NUMERO_PK = ''''IV''''
UNION
SELECT IT1SAC_FIT_CODE_FK_PK AS IDINTER, A.SAC_NOM AS TERME_1, SP1.SP_NOM AS SP_NOM1,B.SAC_NOM AS TERME_2, SP2.SP_NOM AS SP_NOM2,
       SP1.SP_CODE_SQ_PK AS ID_T1,
       SP2.SP_CODE_SQ_PK AS ID_T2,
       FITNA_CDF_NAIT_CODE_FK_PK AS NIVEAU
FROM IT1SAC_TERME1SUBACTIVE, IT2SAC_TERME2SUBACTIVE, FITNA_INTERACTION_NATURE, FITVA_NIVEAU_VALIDATION, CDF_CODIF, SAC_SUBACTIVE A
JOIN COSAC_COMPO_SUBACT COS1 on ( COS1.COSAC_SAC_CODE_FK_PK = A.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP1 ON (SP1.SP_CODE_SQ_PK = COS1.COSAC_SP_CODE_FK_PK),
 SAC_SUBACTIVE B
JOIN COSAC_COMPO_SUBACT COS2 on ( COS2.COSAC_SAC_CODE_FK_PK = B.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP2 ON (SP2.SP_CODE_SQ_PK = COS2.COSAC_SP_CODE_FK_PK)
WHERE IT1SAC_FIT_CODE_FK_PK = IT2SAC_FIT_CODE_FK_PK
AND IT1SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT2SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT1SAC_SAC_CODE_FK_PK <> IT2SAC_SAC_CODE_FK_PK
AND A.SAC_CODE_SQ_PK = IT1SAC_SAC_CODE_FK_PK
AND B.SAC_CODE_SQ_PK = IT2SAC_SAC_CODE_FK_PK
AND NOT EXISTS (SELECT IT2SAC_FIT_CODE_FK_PK, IT2SAC_SAC_CODE_FK_PK
                FROM IT2SAC_TERME2SUBACTIVE
                WHERE IT2SAC_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
                AND IT2SAC_SAC_CODE_FK_PK = IT1SAC_SAC_CODE_FK_PK)
AND FITNA_CDF_NAIT_CODE_FK_PK <= '''''' || GRAVITE || ''''''
AND FITNA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND FITVA_CDF_VAIT_CODE_FK_PK = ''''1''''
AND FITVA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND CDF_CODE_PK = FITVA_CDF_VAIT_CODE_FK_PK
AND CDF_NUMERO_PK = ''''IV''''
UNION
SELECT IT1SAC_FIT_CODE_FK_PK AS IDINTER,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN B.SAC_NOM ELSE A.SAC_NOM END AS TERME_1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_NOM ELSE SP2.SP_NOM END AS SP_NOM1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN A.SAC_NOM ELSE B.SAC_NOM END AS TERME_2,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_NOM ELSE SP1.SP_NOM END AS SP_NOM2,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_CODE_SQ_PK ELSE SP2.SP_CODE_SQ_PK END AS ID_T1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_CODE_SQ_PK ELSE SP1.SP_CODE_SQ_PK END AS ID_T2,
       FITNA_CDF_NAIT_CODE_FK_PK AS NIVEAU
FROM IT1SAC_TERME1SUBACTIVE, IT2SAC_TERME2SUBACTIVE, FITNA_INTERACTION_NATURE, FITVA_NIVEAU_VALIDATION, CDF_CODIF, SAC_SUBACTIVE A
JOIN COSAC_COMPO_SUBACT COS1 on ( COS1.COSAC_SAC_CODE_FK_PK = A.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP1 ON (SP1.SP_CODE_SQ_PK = COS1.COSAC_SP_CODE_FK_PK),
 SAC_SUBACTIVE B
JOIN COSAC_COMPO_SUBACT COS2 on ( COS2.COSAC_SAC_CODE_FK_PK = B.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP2 ON (SP2.SP_CODE_SQ_PK = COS2.COSAC_SP_CODE_FK_PK)
WHERE IT1SAC_FIT_CODE_FK_PK = IT2SAC_FIT_CODE_FK_PK
AND IT1SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT2SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT1SAC_SAC_CODE_FK_PK <> IT2SAC_SAC_CODE_FK_PK
AND A.SAC_CODE_SQ_PK = IT1SAC_SAC_CODE_FK_PK
AND B.SAC_CODE_SQ_PK = IT2SAC_SAC_CODE_FK_PK
AND NOT EXISTS (SELECT IT2SAC_FIT_CODE_FK_PK, IT2SAC_SAC_CODE_FK_PK
                FROM IT2SAC_TERME2SUBACTIVE
                WHERE IT2SAC_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
                AND IT2SAC_SAC_CODE_FK_PK = IT1SAC_SAC_CODE_FK_PK)
AND FITNA_CDF_NAIT_CODE_FK_PK <= '''''' || GRAVITE || ''''''
AND FITNA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND FITVA_CDF_VAIT_CODE_FK_PK = ''''1''''
AND FITVA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND CDF_CODE_PK = FITVA_CDF_VAIT_CODE_FK_PK
AND CDF_NUMERO_PK = ''''IV''''
GROUP BY IT1SAC_FIT_CODE_FK_PK, CDF_NOM,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN B.SAC_NOM ELSE A.SAC_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN A.SAC_NOM ELSE B.SAC_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_CODE_SQ_PK ELSE SP1.SP_CODE_SQ_PK END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_CODE_SQ_PK ELSE SP2.SP_CODE_SQ_PK END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_NOM ELSE SP1.SP_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_NOM ELSE SP2.SP_NOM END,
       FITNA_CDF_NAIT_CODE_FK_PK
HAVING COUNT(*) > 1
UNION
SELECT IT1SAC_FIT_CODE_FK_PK AS IDINTER,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN B.SAC_NOM ELSE A.SAC_NOM END AS TERME_1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_NOM ELSE SP2.SP_NOM END AS SP_NOM1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN A.SAC_NOM ELSE B.SAC_NOM END AS TERME_2,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_NOM ELSE SP1.SP_NOM END AS SP_NOM2,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_CODE_SQ_PK ELSE SP2.SP_CODE_SQ_PK END AS ID_T1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_CODE_SQ_PK ELSE SP1.SP_CODE_SQ_PK END AS ID_T2,
       FITNA_CDF_NAIT_CODE_FK_PK AS NIVEAU
FROM IT1SAC_TERME1SUBACTIVE, IT2SAC_TERME2SUBACTIVE, FITNA_INTERACTION_NATURE, FITVA_NIVEAU_VALIDATION, CDF_CODIF, SAC_SUBACTIVE A
JOIN COSAC_COMPO_SUBACT COS1 on ( COS1.COSAC_SAC_CODE_FK_PK = A.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP1 ON (SP1.SP_CODE_SQ_PK = COS1.COSAC_SP_CODE_FK_PK),
 SAC_SUBACTIVE B
JOIN COSAC_COMPO_SUBACT COS2 on ( COS2.COSAC_SAC_CODE_FK_PK = B.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP2 ON (SP2.SP_CODE_SQ_PK = COS2.COSAC_SP_CODE_FK_PK)
WHERE IT1SAC_FIT_CODE_FK_PK = IT2SAC_FIT_CODE_FK_PK
AND IT1SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT2SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT1SAC_SAC_CODE_FK_PK <> IT2SAC_SAC_CODE_FK_PK
AND A.SAC_CODE_SQ_PK = IT1SAC_SAC_CODE_FK_PK
AND B.SAC_CODE_SQ_PK = IT2SAC_SAC_CODE_FK_PK
AND EXISTS (SELECT IT2SAC_FIT_CODE_FK_PK, IT2SAC_SAC_CODE_FK_PK
                FROM IT2SAC_TERME2SUBACTIVE
                WHERE IT2SAC_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
                AND IT2SAC_SAC_CODE_FK_PK = IT1SAC_SAC_CODE_FK_PK)
AND FITNA_CDF_NAIT_CODE_FK_PK <= '''''' || GRAVITE || ''''''
AND FITNA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND FITVA_CDF_VAIT_CODE_FK_PK = ''''1''''
AND FITVA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND CDF_CODE_PK = FITVA_CDF_VAIT_CODE_FK_PK
AND CDF_NUMERO_PK = ''''IV''''
GROUP BY IT1SAC_FIT_CODE_FK_PK, CDF_NOM,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN B.SAC_NOM ELSE A.SAC_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN A.SAC_NOM ELSE B.SAC_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_CODE_SQ_PK ELSE SP1.SP_CODE_SQ_PK END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_CODE_SQ_PK ELSE SP2.SP_CODE_SQ_PK END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_NOM ELSE SP1.SP_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_NOM ELSE SP2.SP_NOM END,
       FITNA_CDF_NAIT_CODE_FK_PK
HAVING COUNT(*) > 1
ORDER BY IDINTER, NIVEAU
        '';
        ELSE
            OPEN CURRET FOR EXECUTE ''SELECT IT1SAC_FIT_CODE_FK_PK AS IDINTER, A.SAC_NOM AS TERME_1, SP1.SP_NOM AS SP_NOM1,B.SAC_NOM AS TERME_2, SP2.SP_NOM AS SP_NOM2,
       SP1.SP_CODE_SQ_PK AS ID_T1,
       SP2.SP_CODE_SQ_PK AS ID_T2,
       FITNA_CDF_NAIT_CODE_FK_PK AS NIVEAU
FROM IT1SAC_TERME1SUBACTIVE, IT2SAC_TERME2SUBACTIVE, FITNA_INTERACTION_NATURE, FITVA_NIVEAU_VALIDATION, CDF_CODIF, SAC_SUBACTIVE A
JOIN COSAC_COMPO_SUBACT COS1 on ( COS1.COSAC_SAC_CODE_FK_PK = A.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP1 ON (SP1.SP_CODE_SQ_PK = COS1.COSAC_SP_CODE_FK_PK),
 SAC_SUBACTIVE B
JOIN COSAC_COMPO_SUBACT COS2 on ( COS2.COSAC_SAC_CODE_FK_PK = B.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP2 ON (SP2.SP_CODE_SQ_PK = COS2.COSAC_SP_CODE_FK_PK)
WHERE IT1SAC_FIT_CODE_FK_PK = IT2SAC_FIT_CODE_FK_PK
AND IT1SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT2SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT1SAC_SAC_CODE_FK_PK <> IT2SAC_SAC_CODE_FK_PK
AND A.SAC_CODE_SQ_PK = IT1SAC_SAC_CODE_FK_PK
AND B.SAC_CODE_SQ_PK = IT2SAC_SAC_CODE_FK_PK
AND NOT EXISTS (SELECT IT1SAC_FIT_CODE_FK_PK, IT1SAC_SAC_CODE_FK_PK
                FROM IT1SAC_TERME1SUBACTIVE
                WHERE IT1SAC_FIT_CODE_FK_PK = IT2SAC_FIT_CODE_FK_PK
                AND IT1SAC_SAC_CODE_FK_PK = IT2SAC_SAC_CODE_FK_PK)
AND FITNA_CDF_NAIT_CODE_FK_PK = '''''' || GRAVITE || ''''''
AND FITNA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND FITVA_CDF_VAIT_CODE_FK_PK = ''''1''''
AND FITVA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND CDF_CODE_PK = FITVA_CDF_VAIT_CODE_FK_PK
AND CDF_NUMERO_PK = ''''IV''''
UNION
SELECT IT1SAC_FIT_CODE_FK_PK AS IDINTER, A.SAC_NOM AS TERME_1, SP1.SP_NOM AS SP_NOM1,B.SAC_NOM AS TERME_2, SP2.SP_NOM AS SP_NOM2,
       SP1.SP_CODE_SQ_PK AS ID_T1,
       SP2.SP_CODE_SQ_PK AS ID_T2,
       FITNA_CDF_NAIT_CODE_FK_PK AS NIVEAU
FROM IT1SAC_TERME1SUBACTIVE, IT2SAC_TERME2SUBACTIVE, FITNA_INTERACTION_NATURE, FITVA_NIVEAU_VALIDATION, CDF_CODIF, SAC_SUBACTIVE A
JOIN COSAC_COMPO_SUBACT COS1 on ( COS1.COSAC_SAC_CODE_FK_PK = A.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP1 ON (SP1.SP_CODE_SQ_PK = COS1.COSAC_SP_CODE_FK_PK),
 SAC_SUBACTIVE B
JOIN COSAC_COMPO_SUBACT COS2 on ( COS2.COSAC_SAC_CODE_FK_PK = B.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP2 ON (SP2.SP_CODE_SQ_PK = COS2.COSAC_SP_CODE_FK_PK)
WHERE IT1SAC_FIT_CODE_FK_PK = IT2SAC_FIT_CODE_FK_PK
AND IT1SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT2SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT1SAC_SAC_CODE_FK_PK <> IT2SAC_SAC_CODE_FK_PK
AND A.SAC_CODE_SQ_PK = IT1SAC_SAC_CODE_FK_PK
AND B.SAC_CODE_SQ_PK = IT2SAC_SAC_CODE_FK_PK
AND NOT EXISTS (SELECT IT2SAC_FIT_CODE_FK_PK, IT2SAC_SAC_CODE_FK_PK
                FROM IT2SAC_TERME2SUBACTIVE
                WHERE IT2SAC_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
                AND IT2SAC_SAC_CODE_FK_PK = IT1SAC_SAC_CODE_FK_PK)
AND FITNA_CDF_NAIT_CODE_FK_PK = '''''' || GRAVITE || ''''''
AND FITNA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND FITVA_CDF_VAIT_CODE_FK_PK = ''''1''''
AND FITVA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND CDF_CODE_PK = FITVA_CDF_VAIT_CODE_FK_PK
AND CDF_NUMERO_PK = ''''IV''''
UNION
SELECT IT1SAC_FIT_CODE_FK_PK AS IDINTER,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN B.SAC_NOM ELSE A.SAC_NOM END AS TERME_1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_NOM ELSE SP2.SP_NOM END AS SP_NOM1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN A.SAC_NOM ELSE B.SAC_NOM END AS TERME_2,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_NOM ELSE SP1.SP_NOM END AS SP_NOM2,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_CODE_SQ_PK ELSE SP2.SP_CODE_SQ_PK END AS ID_T1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_CODE_SQ_PK ELSE SP1.SP_CODE_SQ_PK END AS ID_T2,
       FITNA_CDF_NAIT_CODE_FK_PK AS NIVEAU
FROM IT1SAC_TERME1SUBACTIVE, IT2SAC_TERME2SUBACTIVE, FITNA_INTERACTION_NATURE, FITVA_NIVEAU_VALIDATION, CDF_CODIF, SAC_SUBACTIVE A
JOIN COSAC_COMPO_SUBACT COS1 on ( COS1.COSAC_SAC_CODE_FK_PK = A.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP1 ON (SP1.SP_CODE_SQ_PK = COS1.COSAC_SP_CODE_FK_PK),
 SAC_SUBACTIVE B
JOIN COSAC_COMPO_SUBACT COS2 on ( COS2.COSAC_SAC_CODE_FK_PK = B.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP2 ON (SP2.SP_CODE_SQ_PK = COS2.COSAC_SP_CODE_FK_PK)
WHERE IT1SAC_FIT_CODE_FK_PK = IT2SAC_FIT_CODE_FK_PK
AND IT1SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT2SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT1SAC_SAC_CODE_FK_PK <> IT2SAC_SAC_CODE_FK_PK
AND A.SAC_CODE_SQ_PK = IT1SAC_SAC_CODE_FK_PK
AND B.SAC_CODE_SQ_PK = IT2SAC_SAC_CODE_FK_PK
AND NOT EXISTS (SELECT IT2SAC_FIT_CODE_FK_PK, IT2SAC_SAC_CODE_FK_PK
                FROM IT2SAC_TERME2SUBACTIVE
                WHERE IT2SAC_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
                AND IT2SAC_SAC_CODE_FK_PK = IT1SAC_SAC_CODE_FK_PK)
AND FITNA_CDF_NAIT_CODE_FK_PK = '''''' || GRAVITE || ''''''
AND FITNA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND FITVA_CDF_VAIT_CODE_FK_PK = ''''1''''
AND FITVA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND CDF_CODE_PK = FITVA_CDF_VAIT_CODE_FK_PK
AND CDF_NUMERO_PK = ''''IV''''
GROUP BY IT1SAC_FIT_CODE_FK_PK, CDF_NOM,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN B.SAC_NOM ELSE A.SAC_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN A.SAC_NOM ELSE B.SAC_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_CODE_SQ_PK ELSE SP1.SP_CODE_SQ_PK END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_CODE_SQ_PK ELSE SP2.SP_CODE_SQ_PK END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_NOM ELSE SP1.SP_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_NOM ELSE SP2.SP_NOM END,
       FITNA_CDF_NAIT_CODE_FK_PK
HAVING COUNT(*) > 1
UNION
SELECT IT1SAC_FIT_CODE_FK_PK AS IDINTER,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN B.SAC_NOM ELSE A.SAC_NOM END AS TERME_1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_NOM ELSE SP2.SP_NOM END AS SP_NOM1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN A.SAC_NOM ELSE B.SAC_NOM END AS TERME_2,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_NOM ELSE SP1.SP_NOM END AS SP_NOM2,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_CODE_SQ_PK ELSE SP2.SP_CODE_SQ_PK END AS ID_T1,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_CODE_SQ_PK ELSE SP1.SP_CODE_SQ_PK END AS ID_T2,
       FITNA_CDF_NAIT_CODE_FK_PK AS NIVEAU
FROM IT1SAC_TERME1SUBACTIVE, IT2SAC_TERME2SUBACTIVE, FITNA_INTERACTION_NATURE, FITVA_NIVEAU_VALIDATION, CDF_CODIF, SAC_SUBACTIVE A
JOIN COSAC_COMPO_SUBACT COS1 on ( COS1.COSAC_SAC_CODE_FK_PK = A.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP1 ON (SP1.SP_CODE_SQ_PK = COS1.COSAC_SP_CODE_FK_PK),
 SAC_SUBACTIVE B
JOIN COSAC_COMPO_SUBACT COS2 on ( COS2.COSAC_SAC_CODE_FK_PK = B.SAC_CODE_SQ_PK)
JOIN SP_SPECIALITE SP2 ON (SP2.SP_CODE_SQ_PK = COS2.COSAC_SP_CODE_FK_PK)
WHERE IT1SAC_FIT_CODE_FK_PK = IT2SAC_FIT_CODE_FK_PK
AND IT1SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT2SAC_SAC_CODE_FK_PK IN ('' || LISTESAC || '')
AND IT1SAC_SAC_CODE_FK_PK <> IT2SAC_SAC_CODE_FK_PK
AND A.SAC_CODE_SQ_PK = IT1SAC_SAC_CODE_FK_PK
AND B.SAC_CODE_SQ_PK = IT2SAC_SAC_CODE_FK_PK
AND EXISTS (SELECT IT2SAC_FIT_CODE_FK_PK, IT2SAC_SAC_CODE_FK_PK
                FROM IT2SAC_TERME2SUBACTIVE
                WHERE IT2SAC_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
                AND IT2SAC_SAC_CODE_FK_PK = IT1SAC_SAC_CODE_FK_PK)
AND FITNA_CDF_NAIT_CODE_FK_PK = '''''' || GRAVITE || ''''''
AND FITNA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND FITVA_CDF_VAIT_CODE_FK_PK = ''''1''''
AND FITVA_FIT_CODE_FK_PK = IT1SAC_FIT_CODE_FK_PK
AND CDF_CODE_PK = FITVA_CDF_VAIT_CODE_FK_PK
AND CDF_NUMERO_PK = ''''IV''''
GROUP BY IT1SAC_FIT_CODE_FK_PK, CDF_NOM,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN B.SAC_NOM ELSE A.SAC_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN A.SAC_NOM ELSE B.SAC_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_CODE_SQ_PK ELSE SP1.SP_CODE_SQ_PK END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_CODE_SQ_PK ELSE SP2.SP_CODE_SQ_PK END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP2.SP_NOM ELSE SP1.SP_NOM END,
       CASE WHEN IT1SAC_SAC_CODE_FK_PK>IT2SAC_SAC_CODE_FK_PK THEN SP1.SP_NOM ELSE SP2.SP_NOM END,
       FITNA_CDF_NAIT_CODE_FK_PK
HAVING COUNT(*) > 1
ORDER BY IDINTER, NIVEAU
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API SMR ET ASMR DE LA SPECIALITE
-- EXEMPLE: LISTID := '14584,31544,4289,7286' ET TYPID := 0 POUR SMR OU LISTID := '14584,31544,4289,7286' ET TYPID := 1 POUR ASMR

-- DROP FUNCTION GET_THE_SMR_ASMR_SPE(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_SMR_ASMR_SPE (VARCHAR,NUMERIC) RETURNS REFCURSOR AS '
DECLARE
  LISTID ALIAS FOR $1;  TYPID ALIAS FOR $2;
  CURRET REFCURSOR;
BEGIN
  IF TYPID = 1 THEN
    OPEN CURRET FOR EXECUTE ''SELECT spe.SP_CIPUCD,
                           spe.SP_CODE_SQ_PK,
                           spe.SP_NOM,
                           MAX(ct.CTHAS_DATE)                                         AS CTHAS_DATE,
                           smr.CTSMR_NIVEAU,
                           ct.CTHAS_TYPE,
                           ct.CTHAS_CODE_SQ_PK,
                           REPLACE(smr.CTSMR_TEXTE, ''''¿'''', '''''''''''''''') AS CTSMR_TEXTE
                    FROM sp_specialite spe
                             JOIN ctspe_cis_ct ctspe
                                  ON ctspe.CTSPE_SP_NL = spe.SP_NL
                             JOIN cthas_avis ct
                                  ON ct.CTHAS_CODE_SQ_PK = ctspe.CTSPE_CTHAS_CODE_FK_PK
                             JOIN ctsmr_detail_ct smr
                                  ON smr.CTSMR_CTHAS_CODE_FK_PK = ctspe.CTSPE_CTHAS_CODE_FK_PK
                    WHERE (SPE.SP_CODE_SQ_PK IN ('' || LISTID || '') OR SPE.SP_CIPUCD IN ('' || LISTID || ''))
                    GROUP BY spe.SP_CIPUCD,
                             spe.SP_CODE_SQ_PK,
                             spe.SP_NOM,
                             smr.CTSMR_NIVEAU,
                             ct.CTHAS_TYPE,
                             ct.CTHAS_CODE_SQ_PK,
                             REPLACE(smr.CTSMR_TEXTE, ''''¿'''', '''''''''''''''')
                    ORDER BY spe.SP_NOM,
                             CTHAS_DATE'';
  END IF;
  IF TYPID = 2 THEN
    OPEN CURRET FOR EXECUTE ''SELECT spe.SP_CIPUCD,
                           spe.SP_CODE_SQ_PK,
                           spe.SP_NOM,
                           MAX(ct.CTHAS_DATE)                    AS CTHAS_DATE,
                           asmr.CTASMR_NIVEAU,
                           ct.CTHAS_TYPE,
                           ct.CTHAS_CODE_SQ_PK,
                           REPLACE(asmr.CTASMR_TEXTE, ''''¿'''', '''''''''''''''') AS CTASMR_TEXTE
                    FROM sp_specialite spe
                             JOIN ctspe_cis_ct ctspe
                                  ON ctspe.CTSPE_SP_NL = spe.SP_NL
                             JOIN cthas_avis ct
                                  ON ct.CTHAS_CODE_SQ_PK = ctspe.CTSPE_CTHAS_CODE_FK_PK
                             JOIN ctasmr_detail_ct asmr
                                  ON asmr.CTASMR_CTHAS_CODE_FK_PK = ctspe.CTSPE_CTHAS_CODE_FK_PK
                    WHERE (SPE.SP_CODE_SQ_PK IN ('' || LISTID || '') OR SPE.SP_CIPUCD IN ('' || LISTID || ''))
                    GROUP BY spe.SP_CIPUCD,
                             spe.SP_CODE_SQ_PK,
                             spe.SP_NOM,
                             asmr.CTASMR_NIVEAU,
                             ct.CTHAS_TYPE,
                             ct.CTHAS_CODE_SQ_PK, REPLACE(asmr.CTASMR_TEXTE, ''''¿'''', '''''''''''''''')
                    ORDER BY spe.SP_NOM,
                             CTHAS_DATE'';
  END IF;
  RETURN CURRET;
END;

' LANGUAGE PLPGSQL;


-- API PRODUIT STUPEFIANT
-- EXEMPLE: LISTID := '7690,7335,5925,4143' ET TYPID := 1

-- DROP FUNCTION GET_THE_PRODUIT_STUP(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_PRODUIT_STUP(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, ''''O'''' AS STUP, ''''-'''' AS TYPAGE
            FROM SP_SPECIALITE SP
            WHERE SP.SP_CDF_LI_CODE_FK = ''''3''''
            UNION
            SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, ''''O'''' AS STUP, spcpd.spcpd_typage AS TYPAGE
            FROM SP_SPECIALITE SP, VSPCPD_SPE_CDT_PRESCR SPCPD, CDF_CODIF CDF14
            WHERE SP.SP_CODE_SQ_PK = SPCPD.SPCPD_SP_CODE_FK_PK
            AND SPCPD.SPCPD_CDF_STP_CODE_FK_PK = CDF14.CDF_CODE_PK
            AND CDF14.CDF_NUMERO_PK = ''''14''''
            AND CDF14.CDF_CODE_PK = ''''S95''''
            UNION
            SELECT SPN.SP_CIPUCD AS SP_CIPUCD, SPN.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SPN.SP_NOM AS SP_NOM, ''''N'''' AS STUP, ''''-'''' AS TYPAGE
            FROM SP_SPECIALITE SPN
            WHERE SPN.SP_CODE_SQ_PK NOT IN (
              SELECT DISTINCT SP.SP_CODE_SQ_PK
              FROM SP_SPECIALITE SP
              WHERE SP.SP_CDF_LI_CODE_FK = ''''3''''
              UNION
              SELECT DISTINCT SP.SP_CODE_SQ_PK
              FROM SP_SPECIALITE SP, VSPCPD_SPE_CDT_PRESCR SPCPD, CDF_CODIF CDF14
              WHERE SP.SP_CODE_SQ_PK = SPCPD.SPCPD_SP_CODE_FK_PK
              AND SPCPD.SPCPD_CDF_STP_CODE_FK_PK = CDF14.CDF_CODE_PK
              AND CDF14.CDF_NUMERO_PK = ''''14''''
              AND CDF14.CDF_CODE_PK = ''''S95'''')'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, ''''O'''' AS STUP, ''''-'''' AS TYPAGE
        FROM SP_SPECIALITE SP
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR SP.SP_CIPUCD IN ('' || LISTID || ''))
        AND SP.SP_CDF_LI_CODE_FK = ''''3''''
        UNION
        SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, ''''O'''' AS STUP, spcpd.spcpd_typage AS TYPAGE
        FROM SP_SPECIALITE SP, VSPCPD_SPE_CDT_PRESCR SPCPD, CDF_CODIF CDF14
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR SP.SP_CIPUCD IN ('' || LISTID || ''))
        AND SP.SP_CODE_SQ_PK = SPCPD.SPCPD_SP_CODE_FK_PK
        AND SPCPD.SPCPD_CDF_STP_CODE_FK_PK = CDF14.CDF_CODE_PK
        AND CDF14.CDF_NUMERO_PK = ''''14''''
        AND ''''S95'''' = CDF14.CDF_CODE_PK
        UNION
        SELECT SPN.SP_CIPUCD AS SP_CIPUCD, SPN.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SPN.SP_NOM AS SP_NOM, ''''N'''' AS STUP, ''''-'''' AS TYPAGE
        FROM SP_SPECIALITE SPN
        WHERE (SPN.SP_CODE_SQ_PK IN ('' || LISTID || '') OR SPN.SP_CIPUCD IN ('' || LISTID || ''))
        AND SPN.SP_CODE_SQ_PK NOT IN (
          SELECT DISTINCT SP.SP_CODE_SQ_PK
          FROM SP_SPECIALITE SP
          WHERE SP.SP_CDF_LI_CODE_FK = ''''3''''
          UNION
          SELECT DISTINCT SP.SP_CODE_SQ_PK
          FROM SP_SPECIALITE SP, VSPCPD_SPE_CDT_PRESCR SPCPD, CDF_CODIF CDF14
          WHERE SP.SP_CODE_SQ_PK = SPCPD.SPCPD_SP_CODE_FK_PK
          AND SPCPD.SPCPD_CDF_STP_CODE_FK_PK = CDF14.CDF_CODE_PK
          AND CDF14.CDF_NUMERO_PK = ''''14''''
          AND CDF14.CDF_CODE_PK = ''''S95'''')'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API PRODUIT STUPEFIANT GSP
-- EXEMPLE: SELECT  GET_THE_PRODUIT_STUP_GSP ('8167,6484,2654,6460,8167,8564', 1);

-- DROP FUNCTION GET_THE_PRODUIT_STUP_GSP(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_PRODUIT_STUP_GSP(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT GSP.GSP_CODE_SQ_PK             AS GSP_CODE,
			get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS GSP_NOM,
			MAX(CASE
			        WHEN SP.SP_CDF_LI_CODE_FK = ''''3''''
			        OR SPCPD.SPCPD_SP_CODE_FK_PK IS NOT NULL
			    THEN ''''O''''
			    ELSE ''''N'''' END)           AS STUP,
			MIN(spcpd_typage)              AS TYPAGE
	FROM GSP_GENERIQUE_SPECIALITE GSP
		 JOIN SP_SPECIALITE SP
		      ON SP.SP_GSP_CODE_FK = GSP.GSP_CODE_SQ_PK
		 LEFT JOIN VSPCPD_SPE_CDT_PRESCR SPCPD
			   ON SPCPD.SPCPD_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
			       AND SPCPD.SPCPD_CDF_STP_CODE_FK_PK = ''''S95''''
	GROUP BY GSP.GSP_CODE_SQ_PK,
	    get_lb_gsp(GSP.GSP_CODE_SQ_PK)
	ORDER BY GSP_NOM'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT GSP.GSP_CODE_SQ_PK             AS GSP_CODE,
			get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS GSP_NOM,
			MAX(CASE
			        WHEN SP.SP_CDF_LI_CODE_FK = ''''3''''
			        OR SPCPD.SPCPD_SP_CODE_FK_PK IS NOT NULL
			    THEN ''''O''''
			    ELSE ''''N'''' END)           AS STUP,
			MIN(spcpd_typage)              AS TYPAGE
	FROM GSP_GENERIQUE_SPECIALITE GSP
		 JOIN SP_SPECIALITE SP
		      ON SP.SP_GSP_CODE_FK = GSP.GSP_CODE_SQ_PK
		 LEFT JOIN VSPCPD_SPE_CDT_PRESCR SPCPD
			   ON SPCPD.SPCPD_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
			       AND SPCPD.SPCPD_CDF_STP_CODE_FK_PK = ''''S95''''
	WHERE GSP.GSP_CODE_SQ_PK IN ('' || LISTID || '')
	GROUP BY GSP.GSP_CODE_SQ_PK,
	    get_lb_gsp(GSP.GSP_CODE_SQ_PK)'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API PRODUIT DOPANT
-- EXEMPLE: LISTID := '7990,11278,7335,4289,5925' ET TYPID := 1

-- DROP FUNCTION GET_THE_PRODUIT_DOP(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_PRODUIT_DOP(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
                SELECT DISTINCT SP.SP_CIPUCD                                                AS SP_CIPUCD,
                                SP.SP_CODE_SQ_PK                                            AS SP_CODE_SQ_PK,
                                SP.SP_NOM                                                   AS SP_NOM,
                                CASE WHEN INFO.GSP_CODE_FK_PK IS NULL THEN ''''N'''' ELSE ''''O'''' END AS PRODUIT_DOPANT
                FROM SP_SPECIALITE SP
                         LEFT JOIN DOPAGE_GSP_INFO_TRANSVERSE INFO
                                   ON INFO.GSP_CODE_FK_PK = SP.SP_GSP_CODE_FK AND INFO.GIT_CODE_FK_PK IN (''''D1'''', ''''D2'''', ''''D3'''', ''''D4'''')
            '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
                SELECT DISTINCT SP.SP_CIPUCD                                                AS SP_CIPUCD,
                                SP.SP_CODE_SQ_PK                                            AS SP_CODE_SQ_PK,
                                SP.SP_NOM                                                   AS SP_NOM,
                                CASE WHEN INFO.GSP_CODE_FK_PK IS NULL THEN ''''N'''' ELSE ''''O'''' END AS PRODUIT_DOPANT
                FROM SP_SPECIALITE SP
                         LEFT JOIN DOPAGE_GSP_INFO_TRANSVERSE INFO
                                   ON INFO.GSP_CODE_FK_PK = SP.SP_GSP_CODE_FK AND INFO.GIT_CODE_FK_PK IN (''''D1'''', ''''D2'''', ''''D3'''', ''''D4'''')
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')) )
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

