-- API RESERVE HOSPITALIERE SPE
-- EXEMPLE: select GET_THE_RESERVE_HOSP ('4561,206,9120579', 1);
-- 2020-04-27 : From GSP
CREATE
OR REPLACE FUNCTION GET_THE_RESERVE_HOSP(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CIPUCD     AS SP_CIPUCD,
                   SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK,
                   SP.SP_NOM        AS SP_NOM,
                   ''''OUI''''            AS RESERVE_HOSPITALIERE,
                   spcpd_typage AS TYPAGE
            FROM SP_SPECIALITE SP
                     JOIN VSPCPD_SPE_CDT_PRESCR
                          ON SP_CODE_SQ_PK = SPCPD_SP_CODE_FK_PK
                              AND SPCPD_CDF_STP_CODE_FK_PK = ''''S7''''
            WHERE SP_CDF_SLAB_CODE_FK <> 7
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CIPUCD     AS SP_CIPUCD,
                   SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK,
                   SP.SP_NOM        AS SP_NOM,
                   CASE
                       WHEN SPCPD_SP_CODE_FK_PK IS NULL
                           THEN ''''NON''''
                       ELSE ''''OUI''''
                       END          AS RESERVE_HOSPITALIERE,
                       spcpd_typage AS TYPAGE
            FROM SP_SPECIALITE SP
                     LEFT JOIN VSPCPD_SPE_CDT_PRESCR
                               ON SP_CODE_SQ_PK = SPCPD_SP_CODE_FK_PK
                                   AND SPCPD_CDF_STP_CODE_FK_PK = ''''S7''''
            WHERE SP_CDF_SLAB_CODE_FK <> 7
              AND (SP.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
            ORDER BY SP.SP_CODE_SQ_PK
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API STATUT GENERIQUE OU REFERENT
-- EXEMPLE: SELECT GET_THE_GEN_REF('48478,8575,55714', 1);

-- DROP FUNCTION GET_THE_GEN_REF(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_GEN_REF(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD                   AS SP_CIPUCD,
                       SP.SP_CODE_SQ_PK               AS SP_CODE_SQ_PK,
                       SP.SP_NOM                      AS SP_NOM,
                       COALESCE(vspsg.VSPSG_TYPGEN, ''''E'''')    AS SP_TYPE_SPE,
                       CASE
                           WHEN vspsg.VSPSG_TYPGEN IS NOT NULL
                               THEN vspsg.VSPSG_DATEFIN END AS SP_TYPE_DATEFIN,
                       SP.SP_GSP_CODE_FK              AS GSP_CODE,
                       get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS GSP_NOM
                FROM SP_SPECIALITE SP
                         JOIN GSP_GENERIQUE_SPECIALITE GSP
                             ON GSP.GSP_CODE_SQ_PK = SP.SP_GSP_CODE_FK
                         JOIN VSPSG_SPE_STATUT_GENERIQUE vspsg
                              ON SP.SP_CODE_SQ_PK = vspsg.VSPSG_SP_CODE_FK_PK
                ORDER BY GSP_NOM,
                         SP_NOM'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD                   AS SP_CIPUCD,
                           SP.SP_CODE_SQ_PK               AS SP_CODE_SQ_PK,
                           SP.SP_NOM                      AS SP_NOM,
                           COALESCE(vspsg.VSPSG_TYPGEN, ''''E'''')    AS SP_TYPE_SPE,
                       CASE
                           WHEN vspsg.VSPSG_TYPGEN IS NOT NULL
                               THEN vspsg.VSPSG_DATEFIN END AS SP_TYPE_DATEFIN,
                           SP.SP_GSP_CODE_FK              AS GSP_CODE,
                           get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS GSP_NOM
                    FROM SP_SPECIALITE SP
                             JOIN GSP_GENERIQUE_SPECIALITE GSP
                                 ON GSP.GSP_CODE_SQ_PK = SP.SP_GSP_CODE_FK
                         JOIN VSPSG_SPE_STATUT_GENERIQUE vspsg
                              ON SP.SP_CODE_SQ_PK = vspsg.VSPSG_SP_CODE_FK_PK
                    WHERE SP.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''',''''))
                ORDER BY GSP_NOM,
                         SP_NOM'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API STATUT T2A / RETROCESSION / PRODUIT ONEREUX
-- EXEMPLE: LISTID := '25398,15985,22093,14654' ET TYPID := 1    ||     LISTID := '9182190,8211,9161294,17341,17090' ET TYPID := 2;

-- DROP FUNCTION T2A_RETROC(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION T2A_RETROC(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT DISTINCT SP.SP_CIPUCD     AS SP_CIPUCD,
                            SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK,
                            SP.SP_NOM        AS SP_NOM,
                            MAX(CASE
                                    WHEN PRIUCD.PRIUCD_UCD_CODE_PK IS NULL OR cipCommer.PRE_SP_CODE_FK IS NULL THEN ''''N''''
                                    ELSE ''''O''''
                                END)         AS RETROCESSION
            FROM SP_SPECIALITE SP
                     LEFT JOIN (SELECT PRE_SP_CODE_FK
                                FROM PRE_PRESENTATION PRE
                                WHERE PRE_ETAT_COMMER = ''''D'''') cipCommer ON cipCommer.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK
                     LEFT JOIN (
                SELECT PRIUCD_UCD_CODE_PK, MAX(PRIUCD_DATE_APPLI_PK) as PRIUCD_DATE_APPLI_PK
                FROM PRIUCD_PRIX_UCD PRIUCD
                GROUP BY PRIUCD_UCD_CODE_PK) prixDate ON prixDate.PRIUCD_UCD_CODE_PK = SP.SP_CIPUCD
                     LEFT JOIN PRIUCD_PRIX_UCD PRIUCD
                               ON PRIUCD.PRIUCD_UCD_CODE_PK = prixDate.PRIUCD_UCD_CODE_PK
                                   AND PRIUCD.PRIUCD_DATE_APPLI_PK = prixDate.PRIUCD_DATE_APPLI_PK
                                   AND PRIUCD.PRIUCD_CODE_LISTE_PK = 1
            WHERE SP.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''',''''))
            GROUP BY SP.SP_CIPUCD, SP.SP_CODE_SQ_PK, SP.SP_NOM
          '';
        END IF;
        IF TYPID = 2 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT DISTINCT SP.SP_CIPUCD     AS SP_CIPUCD,
                            SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK,
                            SP.SP_NOM        AS SP_NOM,
                            MAX(CASE
                                    WHEN PRIUCD.PRIUCD_UCD_CODE_PK IS NULL OR cipCommer.PRE_SP_CODE_FK IS NULL THEN ''''N''''
                                    ELSE ''''O''''
                                END)         AS PRODUIT_ONEREUX
            FROM SP_SPECIALITE SP
                     LEFT JOIN (SELECT PRE_SP_CODE_FK
                                FROM PRE_PRESENTATION PRE
                                WHERE PRE_ETAT_COMMER = ''''D'''') cipCommer ON cipCommer.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK
                     LEFT JOIN (
                SELECT PRIUCD_UCD_CODE_PK, MAX(PRIUCD_DATE_APPLI_PK) as PRIUCD_DATE_APPLI_PK
                FROM PRIUCD_PRIX_UCD PRIUCD
                GROUP BY PRIUCD_UCD_CODE_PK) prixDate ON prixDate.PRIUCD_UCD_CODE_PK = SP.SP_CIPUCD
                     LEFT JOIN PRIUCD_PRIX_UCD PRIUCD
                               ON PRIUCD.PRIUCD_UCD_CODE_PK = prixDate.PRIUCD_UCD_CODE_PK
                                   AND PRIUCD.PRIUCD_DATE_APPLI_PK = prixDate.PRIUCD_DATE_APPLI_PK
                                   AND PRIUCD.PRIUCD_CODE_LISTE_PK = 2
            WHERE SP.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''',''''))
            GROUP BY SP.SP_CIPUCD, SP.SP_CODE_SQ_PK, SP.SP_NOM
          '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API PRIX
-- EXEMPLE: LISTID := '3737,22613,4289,7286,156,15985,22093' ET TYPID := 1

-- DROP FUNCTION GET_THE_PRIX(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_PRIX(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT DISTINCT PRE.PRE_CODE_PK         AS PRE_CODE_PK,
                            SP.SP_CIPUCD            AS SP_CIPUCD,
                            SP.SP_CODE_SQ_PK        AS SP_CODE_SQ_PK,
                            PRIPRE.PRIPRE_PRIX_EURO AS PRIX_PRESENTATION,
                            CASE
                                WHEN PRE.PRE_NATUCD_CONTENU > 0 THEN PRIPRE.PRIPRE_PRIX_EURO / PRE.PRE_NATUCD_CONTENU
                                ELSE 0 END          AS PRIX_UCD
            FROM SP_SPECIALITE SP
                     LEFT JOIN PRIUCD_PRIX_UCD PRIUCD ON (PRIUCD.PRIUCD_UCD_CODE_PK = SP.SP_CIPUCD)
                     LEFT JOIN PRE_PRESENTATION PRE ON (SP.SP_CODE_SQ_PK = PRE.PRE_SP_CODE_FK)
                     LEFT JOIN VPRETSS_DERNIER_TAUX v ON v.PRETSS_PRE_CODE_FK_PK = PRE.PRE_CODE_PK
                     LEFT JOIN CDF_CODIF cdfTaux ON cdfTaux.CDF_CODE_PK = CAST(v.CDF_TAUX AS VARCHAR) AND cdfTaux.CDF_NUMERO_PK = ''''17''''
                     LEFT JOIN PRIPRE_PRIX_PRESENTATION PRIPRE
                               ON (PRE.PRE_CODE_PK = PRIPRE.PRIPRE_PRE_CODE_FK_PK AND PRE.PRE_ETAT_COMMER = ''''D'''')
            ORDER BY 3'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT DISTINCT PRE.PRE_CODE_PK         AS PRE_CODE_PK,
                            SP.SP_CIPUCD            AS SP_CIPUCD,
                            SP.SP_CODE_SQ_PK        AS SP_CODE_SQ_PK,
                            PRIPRE.PRIPRE_PRIX_EURO AS PRIX_PRESENTATION,
                            CASE
                                WHEN PRE.PRE_NATUCD_CONTENU > 0 THEN PRIPRE.PRIPRE_PRIX_EURO / PRE.PRE_NATUCD_CONTENU
                                ELSE 0 END          AS PRIX_UCD
            FROM SP_SPECIALITE SP
                     LEFT JOIN PRIUCD_PRIX_UCD PRIUCD ON (PRIUCD.PRIUCD_UCD_CODE_PK = SP.SP_CIPUCD)
                     LEFT JOIN PRE_PRESENTATION PRE ON (SP.SP_CODE_SQ_PK = PRE.PRE_SP_CODE_FK)
                     LEFT JOIN VPRETSS_DERNIER_TAUX v ON v.PRETSS_PRE_CODE_FK_PK = PRE.PRE_CODE_PK
                     LEFT JOIN CDF_CODIF cdfTaux ON cdfTaux.CDF_CODE_PK = CAST(v.CDF_TAUX AS VARCHAR) AND cdfTaux.CDF_NUMERO_PK = ''''17''''
                     LEFT JOIN PRIPRE_PRIX_PRESENTATION PRIPRE
                               ON (PRE.PRE_CODE_PK = PRIPRE.PRIPRE_PRE_CODE_FK_PK AND PRE.PRE_ETAT_COMMER = ''''D'''')
			WHERE SP.SP_CODE_SQ_PK IN ('' || LISTID || '')
			ORDER BY 3'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API VIGILANCE CONDUCTEUR
-- EXEMPLE: SELECT  GET_THE_VIGI_CONDUCT ('29517,50702,1973,4222,50393,7871,53347', 1);

-- DROP FUNCTION GET_THE_VIGI_CONDUCT(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_VIGI_CONDUCT(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
    SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, CDF_NOM AS ALERTE, fcotxt.FCOTXT_TEXTE AS COMMENTAIRE
            FROM FCOSP_CONDUCTEUR_SPEC
            JOIN SP_SPECIALITE SP ON (SP.SP_CODE_SQ_PK = FCOSP_SP_CODE_FK_PK)
            JOIN FCOREC_FCO_REC ON (FCOREC_FCO_CODE_FK_PK = FCOSP_FCO_CODE_FK_PK)
            JOIN CDF_CODIF ON (CDF_CODE_PK = FCOREC_CDF_REC_CODE_FK_PK
              AND CDF_NUMERO_PK = ''''CC''''
              AND CDF_CODE_PK IN (''''X30'''',''''X31'''',''''X32'''',''''X40''''))
            JOIN FCO_CONDUCTEUR fco ON FCOSP_FCO_CODE_FK_PK = fco.FCO_CODE_SQ_PK
            LEFT JOIN FCOTXT_FCO_TEXTE fcotxt ON fcotxt.FCOTXT_CODE_SQ_PK = fco.FCO_FCOTXT_CODE_FK
          '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
    SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, CDF_NOM AS ALERTE, fcotxt.FCOTXT_TEXTE AS COMMENTAIRE
            FROM FCOSP_CONDUCTEUR_SPEC
            JOIN SP_SPECIALITE SP ON (SP.SP_CODE_SQ_PK = FCOSP_SP_CODE_FK_PK)
            JOIN FCOREC_FCO_REC ON (FCOREC_FCO_CODE_FK_PK = FCOSP_FCO_CODE_FK_PK)
            JOIN CDF_CODIF ON (CDF_CODE_PK = FCOREC_CDF_REC_CODE_FK_PK
              AND CDF_NUMERO_PK = ''''CC''''
              AND CDF_CODE_PK IN (''''X30'''',''''X31'''',''''X32'''',''''X40''''))
            JOIN FCO_CONDUCTEUR fco ON FCOSP_FCO_CODE_FK_PK = fco.FCO_CODE_SQ_PK
            LEFT JOIN FCOTXT_FCO_TEXTE fcotxt ON fcotxt.FCOTXT_CODE_SQ_PK = fco.FCO_FCOTXT_CODE_FK
        WHERE SP.SP_CODE_SQ_PK IN ('' || LISTID || '')
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

