-- API ATC ET DDD
-- EXEMPLE: LISTID := '4289,28001,5925,26236,3671,8932,8141,22169,12368,14838' ET TYPID := 1

-- DROP FUNCTION GET_THE_ATC_DDD_V2(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_ATC_DDD_V2(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
                SELECT DISTINCT SP.SP_CIPUCD            AS SP_CIPUCD,
                                SP.SP_CODE_SQ_PK        AS SP_CODE_SQ_PK,
                                SP.SP_NOM               AS SP_NOM,
                                CATC.CATC_CODE_PK       AS CATC_CODE,
                                CATC.CATC_CATC_CODE_FK  AS CATC_CATC_CODE,
                                CDFVO.CDF_NOM           AS VOIE,
                                ATCDDD.ATCDDD_DOSAGE_PK AS DOSAGE,
                                CDFUD.CDF_NOM           AS UNITE_DOSE
                FROM SP_SPECIALITE SP
                         JOIN CATC_CLASSEATC CATC ON CATC.CATC_CODE_PK = SP.SP_CATC_CODE_FK
                         JOIN SPVO_SPECIALITE_VOIE SPVO ON SPVO.SPVO_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
                    AND SPVO.spvo_cdf_vo_code_fk_pk NOT IN
                        (''''6'''', ''''8'''', ''''9'''', ''''14'''', ''''11'''', ''''17'''', ''''19'''', ''''20'''', ''''23'''', ''''25'''', ''''26'''', ''''27'''', ''''37'''', ''''47'''', ''''52'''', ''''53'''', ''''66'''', ''''67'''', ''''72'''',
                         ''''80'''', ''''82'''')
                         JOIN CDF_CODIF CDFVO ON (CDFVO.CDF_CODE_PK = SPVO.SPVO_CDF_VO_CODE_FK_PK
                    AND CDFVO.CDF_NUMERO_PK = ''''18'''')
                         LEFT JOIN ATCDDD_DOSE_USUELLE_JOUR ATCDDD ON ATCDDD.ATCDDD_CATC_CODE_FK_PK = SP.SP_CATC_CODE_FK
                    AND ATCDDD.ATCDDD_CDF_VO_CODE_FK_PK = SPVO.SPVO_CDF_VO_CODE_FK_PK
                         LEFT JOIN CDF_CODIF CDFUD ON (CDFUD.CDF_CODE_PK = ATCDDD.ATCDDD_CDF_UD_CODE_FK_PK
                    AND CDFUD.CDF_NUMERO_PK = ''''19'''')
                ORDER BY SP.SP_CODE_SQ_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
                SELECT DISTINCT SP.SP_CIPUCD            AS SP_CIPUCD,
                                SP.SP_CODE_SQ_PK        AS SP_CODE_SQ_PK,
                                SP.SP_NOM               AS SP_NOM,
                                CATC.CATC_CODE_PK       AS CATC_CODE,
                                CATC.CATC_CATC_CODE_FK  AS CATC_CATC_CODE,
                                CDFVO.CDF_NOM           AS VOIE,
                                ATCDDD.ATCDDD_DOSAGE_PK AS DOSAGE,
                                CDFUD.CDF_NOM           AS UNITE_DOSE
                FROM SP_SPECIALITE SP
                         JOIN CATC_CLASSEATC CATC ON CATC.CATC_CODE_PK = SP.SP_CATC_CODE_FK
                         JOIN SPVO_SPECIALITE_VOIE SPVO ON SPVO.SPVO_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
                    AND SPVO.spvo_cdf_vo_code_fk_pk NOT IN
                        (''''6'''', ''''8'''', ''''9'''', ''''14'''', ''''11'''', ''''17'''', ''''19'''', ''''20'''', ''''23'''', ''''25'''', ''''26'''', ''''27'''', ''''37'''', ''''47'''', ''''52'''', ''''53'''', ''''66'''', ''''67'''', ''''72'''',
                         ''''80'''', ''''82'''')
                         JOIN CDF_CODIF CDFVO ON (CDFVO.CDF_CODE_PK = SPVO.SPVO_CDF_VO_CODE_FK_PK
                    AND CDFVO.CDF_NUMERO_PK = ''''18'''')
                         LEFT JOIN ATCDDD_DOSE_USUELLE_JOUR ATCDDD ON ATCDDD.ATCDDD_CATC_CODE_FK_PK = SP.SP_CATC_CODE_FK
                    AND ATCDDD.ATCDDD_CDF_VO_CODE_FK_PK = SPVO.SPVO_CDF_VO_CODE_FK_PK
                         LEFT JOIN CDF_CODIF CDFUD ON (CDFUD.CDF_CODE_PK = ATCDDD.ATCDDD_CDF_UD_CODE_FK_PK
                    AND CDFUD.CDF_NUMERO_PK = ''''19'''')
        WHERE SP.SP_CODE_SQ_PK IN ('' || LISTID || '')
        ORDER BY SP.SP_CODE_SQ_PK
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API SOLUTE.
-- 2020-04-28 : From GSP
-- EXEMPLE: SELECT  GET_THE_SOLUTE ('4561,9243454', 1);
CREATE
OR REPLACE FUNCTION GET_THE_SOLUTE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CIPUCD     AS SP_CIPUCD,
                   SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK,
                   SP.SP_NOM        AS SP_NOM,
                   CATC.CATC_CODE_PK,
                   ''''O''''              AS SOLUTE
            FROM SP_SPECIALITE SP
                     JOIN GSP_GENERIQUE_SPECIALITE ON GSP_CODE_SQ_PK = SP_GSP_CODE_FK
                     JOIN CATC_CLASSEATC CATC ON CATC.CATC_CODE_PK = SP.SP_CATC_CODE_FK
                     JOIN gsptype_gsp_type ON GSPTYPE_FK_PK = SP_GSP_CODE_FK AND TYPE_CODE_FK_PK = 8
            WHERE SP_CDF_SLAB_CODE_FK <> 7
          '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
                SELECT SP.SP_CIPUCD                                          AS SP_CIPUCD,
                       SP.SP_CODE_SQ_PK                                      AS SP_CODE_SQ_PK,
                       SP.SP_NOM                                             AS SP_NOM,
                       CATC.CATC_CODE_PK,
                       CASE WHEN GSPTYPE_FK_PK IS NULL THEN ''''N'''' ELSE ''''O'''' END AS SOLUTE
                FROM SP_SPECIALITE SP
                         JOIN GSP_GENERIQUE_SPECIALITE ON GSP_CODE_SQ_PK = SP_GSP_CODE_FK
                         JOIN CATC_CLASSEATC CATC ON CATC.CATC_CODE_PK = SP.SP_CATC_CODE_FK
                         LEFT JOIN gsptype_gsp_type ON GSPTYPE_FK_PK = SP_GSP_CODE_FK AND TYPE_CODE_FK_PK = 8
                WHERE SP_CDF_SLAB_CODE_FK <> 7
                  AND (SP.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API SOLUTE GSP.
-- 2020-04-28 : From GSP
-- EXEMPLE: SELECT  GET_THE_SOLUTE_GSP ('4612,106', 1);
CREATE
OR REPLACE FUNCTION GET_THE_SOLUTE_GSP(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT DISTINCT GSP.GSP_CODE_SQ_PK                                    AS GSP_CODE,
                            get_lb_gsp(GSP.GSP_CODE_SQ_PK)                                           AS GSP_NOM,
                            CATC.CATC_CODE_PK,
                            ''''O'''' AS SOLUTE
            FROM GSP_GENERIQUE_SPECIALITE GSP
                     JOIN SP_SPECIALITE SP ON SP.SP_GSP_CODE_FK = GSP.GSP_CODE_SQ_PK
                     JOIN CATC_CLASSEATC CATC ON CATC.CATC_CODE_PK = SP.SP_CATC_CODE_FK
                     JOIN gsptype_gsp_type ON GSPTYPE_FK_PK = SP_GSP_CODE_FK AND TYPE_CODE_FK_PK = 8
          '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
                SELECT DISTINCT GSP.GSP_CODE_SQ_PK                                    AS GSP_CODE,
                                get_lb_gsp(GSP.GSP_CODE_SQ_PK)                                           AS GSP_NOM,
                                CATC.CATC_CODE_PK,
                                CASE WHEN GSPTYPE_FK_PK IS NULL THEN ''''N'''' ELSE ''''O'''' END AS SOLUTE
                FROM GSP_GENERIQUE_SPECIALITE GSP
                         JOIN SP_SPECIALITE SP ON SP.SP_GSP_CODE_FK = GSP.GSP_CODE_SQ_PK
                         JOIN CATC_CLASSEATC CATC ON CATC.CATC_CODE_PK = SP.SP_CATC_CODE_FK
                         LEFT JOIN gsptype_gsp_type ON GSPTYPE_FK_PK = SP_GSP_CODE_FK AND TYPE_CODE_FK_PK = 8
                WHERE GSP.GSP_CODE_SQ_PK IN ('' || LISTID || '')
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API MEDICAMENT VIRTUEL
