-- DROP FUNCTION GET_THE_VIRTUEL(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_VIRTUEL(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, GSP.GSP_CODE_SQ_PK AS CODE_GSP, get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS NOM_GENERIQUE
        FROM SP_SPECIALITE SP
        JOIN GSP_GENERIQUE_SPECIALITE GSP ON GSP.GSP_CODE_SQ_PK = SP.SP_GSP_CODE_FK
        WHERE SP.SP_CODE_SQ_PK IN ('' || LISTID || '')'';
        END IF;
        IF TYPID = 2 THEN
            OPEN CURRET FOR EXECUTE ''SELECT GSP.GSP_CODE_SQ_PK AS CODE_GSP, get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS NOM_GENERIQUE, SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM
        FROM SP_SPECIALITE SP
        JOIN GSP_GENERIQUE_SPECIALITE GSP ON GSP.GSP_CODE_SQ_PK = SP.SP_GSP_CODE_FK
        WHERE GSP.GSP_CODE_SQ_PK IN ('' || LISTID || '')'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API FORME PHARMACEUTIQUE SP
-- EXEMPLE: LISTID := '26236,12368,7130,8238,34245,13563,8141,17204,6849,2715' ET TYPID := 1

-- DROP FUNCTION GET_THE_FORME_SPE_V2(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_FORME_SPE_V2(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM,
          CDF0.CDF_CODE_PK AS CODE_FORME, CDF0.CDF_NOM AS FORME,
          CDF_CFORME.CDF_CODE_PK AS CODE_COMPLEMENT, CDF_CFORME.CDF_NOM AS COMPLEMENT_FORME,
          CDF_VOIE.CDF_CODE_PK AS CODE_VOIE, CDF_VOIE.CDF_NOM AS VOIE, GSPVO.GSPVO_NUM_ORDRE  as VOIE_NUM_ORD,
          CASE
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''47'''',''''50'''',''''89'''',''''8'''',''''9'''',''''90'''',''''81'''',''''11'''',''''7'''',''''97'''',''''57'''',''''72'''',''''53'''',''''14'''',''''48'''',''''80'''',''''98'''',''''82'''',''''15'''',''''17'''',''''32'''',''''64'''',''''91'''',''''20'''',''''92'''',''''23'''',''''93'''',''''94'''',''''24'''',''''25'''',''''26'''',''''67'''',''''27'''',''''70'''',''''86'''',''''54'''',''''19'''',''''52'''',''''66'''',''''60'''',''''45'''',''''37'''',''''68'''') THEN ''''62''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''3'''',''''5'''',''''31'''',''''95'''',''''96'''',''''38'''') THEN ''''30''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''63'''',''''39'''') THEN ''''4''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''1'''',''''6'''') THEN ''''28''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''45'''',''''69'''') THEN ''''29''''
            ELSE CDF_VOIE.CDF_CODE_PK
          END AS CODE_VOIE_PRINCIPALE,
          CASE
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''47'''',''''50'''',''''89'''',''''8'''',''''9'''',''''90'''',''''81'''',''''11'''',''''7'''',''''97'''',''''57'''',''''72'''',''''53'''',''''14'''',''''48'''',''''80'''',''''98'''',''''82'''',''''15'''',''''17'''',''''32'''',''''64'''',''''91'''',''''20'''',''''92'''',''''23'''',''''93'''',''''94'''',''''24'''',''''25'''',''''26'''',''''67'''',''''27'''',''''70'''',''''86'''',''''54'''',''''19'''',''''52'''',''''66'''',''''60'''',''''45'''',''''37'''',''''68'''') THEN ''''INJECTABLE''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''3'''',''''5'''',''''31'''',''''95'''',''''96'''',''''38'''') THEN ''''ORALE''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''63'''',''''39'''') THEN ''''CUTANEE''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''1'''',''''6'''') THEN ''''NASALE''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''45'''',''''69'''') THEN ''''OPHTALMIQUE''''
            ELSE CDF_VOIE.CDF_NOM
          END AS NOM_VOIE_PRINCIPALE
        FROM SP_SPECIALITE SP
        JOIN SPFO_SPECIALITE_FORME SPFO ON (SPFO.SPFO_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK)
        JOIN CDF_CODIF CDF0 ON (CDF0.CDF_CODE_PK = SPFO.SPFO_CDF_FO_CODE_FK_PK AND CDF0.CDF_NUMERO_PK = ''''06'''')
        LEFT JOIN SPFOCFO_SPE_FORME_COMPFORME SPFOCFO ON (SPFOCFO.SPFOCFO_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        	AND SPFOCFO_CDF_FO_CODE_FK_PK = SPFO.SPFO_CDF_FO_CODE_FK_PK
        	AND  SPFOCFO_CDF_CFO_CODE_FK_PK NOT IN (''''4'''',''''209'''',''''18'''',''''78'''' ,''''186'''' ,''''257'''',''''170'''',''''58'''',''''280'''',''''60'''',''''10'''',''''11'''',''''212'''',''''277'''',''''20'''',''''23'''',''''64'''',''''108'''',''''77'''',''''73'''',''''24'''',''''235'''',''''15'''',''''5'''' ,''''40'''',''''42'''',''''61'''',''''562'''',''''96'''',''''44'''',''''25'''',''''65'''',''''249'''',''''233'''',''''26'''',''''250'''',''''461'''',''''186'''',''''607'''',''''245'''')
        	AND SPFOCFO_SPFO_NUMSEQ_FK_PK = SPFO.SPFO_NUMSEQ_PK)
        LEFT JOIN CDF_CODIF CDF_CFORME ON (CDF_CFORME.CDF_CODE_PK = SPFOCFO.SPFOCFO_CDF_CFO_CODE_FK_PK
          AND CDF_CFORME.CDF_NUMERO_PK = ''''02'''')
        LEFT JOIN SPVO_SPECIALITE_VOIE SPVO ON SPVO.SPVO_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        LEFT JOIN GSPVO_GSP_VOIE GSPVO ON GSPVO.GSPVO_GSP_CODE_FK_PK = SP.SP_GSP_CODE_FK AND GSPVO.GSPVO_CDF_VO_CODE_FK_PK = SPVO.SPVO_CDF_VO_CODE_FK_PK
        LEFT JOIN CDF_CODIF CDF_VOIE ON (CDF_VOIE.CDF_CODE_PK = SPVO.SPVO_CDF_VO_CODE_FK_PK
          AND CDF_VOIE.CDF_NUMERO_PK = (''''18''''))
		ORDER BY SP.SP_CODE_SQ_PK, CDF0.CDF_NOM, GSPVO.GSPVO_NUM_ORDRE'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM,
          CDF0.CDF_CODE_PK AS CODE_FORME, CDF0.CDF_NOM AS FORME,
          CDF_CFORME.CDF_CODE_PK AS CODE_COMPLEMENT, CDF_CFORME.CDF_NOM AS COMPLEMENT_FORME,
          CDF_VOIE.CDF_CODE_PK AS CODE_VOIE, CDF_VOIE.CDF_NOM AS VOIE, GSPVO.GSPVO_NUM_ORDRE  as VOIE_NUM_ORD,
          CASE
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''47'''',''''50'''',''''89'''',''''8'''',''''9'''',''''90'''',''''81'''',''''11'''',''''7'''',''''97'''',''''57'''',''''72'''',''''53'''',''''14'''',''''48'''',''''80'''',''''98'''',''''82'''',''''15'''',''''17'''',''''32'''',''''64'''',''''91'''',''''20'''',''''92'''',''''23'''',''''93'''',''''94'''',''''24'''',''''25'''',''''26'''',''''67'''',''''27'''',''''70'''',''''86'''',''''54'''',''''19'''',''''52'''',''''66'''',''''60'''',''''45'''',''''37'''',''''68'''') THEN ''''62''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''3'''',''''5'''',''''31'''',''''95'''',''''96'''',''''38'''') THEN ''''30''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''63'''',''''39'''') THEN ''''4''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''1'''',''''6'''') THEN ''''28''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''45'''',''''69'''') THEN ''''29''''
            ELSE CDF_VOIE.CDF_CODE_PK
          END AS CODE_VOIE_PRINCIPALE,
          CASE
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''47'''',''''50'''',''''89'''',''''8'''',''''9'''',''''90'''',''''81'''',''''11'''',''''7'''',''''97'''',''''57'''',''''72'''',''''53'''',''''14'''',''''48'''',''''80'''',''''98'''',''''82'''',''''15'''',''''17'''',''''32'''',''''64'''',''''91'''',''''20'''',''''92'''',''''23'''',''''93'''',''''94'''',''''24'''',''''25'''',''''26'''',''''67'''',''''27'''',''''70'''',''''86'''',''''54'''',''''19'''',''''52'''',''''66'''',''''60'''',''''45'''',''''37'''',''''68'''') THEN ''''INJECTABLE''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''3'''',''''5'''',''''31'''',''''95'''',''''96'''',''''38'''') THEN ''''ORALE''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''63'''',''''39'''') THEN ''''CUTANEE''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''1'''',''''6'''') THEN ''''NASALE''''
            WHEN CDF_VOIE.CDF_CODE_PK IN (''''45'''',''''69'''') THEN ''''OPHTALMIQUE''''
            ELSE CDF_VOIE.CDF_NOM
          END AS NOM_VOIE_PRINCIPALE
        FROM SP_SPECIALITE SP
        JOIN SPFO_SPECIALITE_FORME SPFO ON (SPFO.SPFO_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK)
        JOIN CDF_CODIF CDF0 ON (CDF0.CDF_CODE_PK = SPFO.SPFO_CDF_FO_CODE_FK_PK AND CDF0.CDF_NUMERO_PK = ''''06'''')
        LEFT JOIN SPFOCFO_SPE_FORME_COMPFORME SPFOCFO ON (SPFOCFO.SPFOCFO_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        	AND SPFOCFO_CDF_FO_CODE_FK_PK = SPFO.SPFO_CDF_FO_CODE_FK_PK
        	AND  SPFOCFO_CDF_CFO_CODE_FK_PK NOT IN (''''4'''',''''209'''',''''18'''',''''78'''' ,''''186'''' ,''''257'''',''''170'''',''''58'''',''''280'''',''''60'''',''''10'''',''''11'''',''''212'''',''''277'''',''''20'''',''''23'''',''''64'''',''''108'''',''''77'''',''''73'''',''''24'''',''''235'''',''''15'''',''''5'''' ,''''40'''',''''42'''',''''61'''',''''562'''',''''96'''',''''44'''',''''25'''',''''65'''',''''249'''',''''233'''',''''26'''',''''250'''',''''461'''',''''186'''',''''607'''',''''245'''')
        	AND SPFOCFO_SPFO_NUMSEQ_FK_PK = SPFO.SPFO_NUMSEQ_PK)
        LEFT JOIN CDF_CODIF CDF_CFORME ON (CDF_CFORME.CDF_CODE_PK = SPFOCFO.SPFOCFO_CDF_CFO_CODE_FK_PK
          AND CDF_CFORME.CDF_NUMERO_PK = ''''02'''')
        LEFT JOIN SPVO_SPECIALITE_VOIE SPVO ON SPVO.SPVO_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        LEFT JOIN GSPVO_GSP_VOIE GSPVO ON GSPVO.GSPVO_GSP_CODE_FK_PK = SP.SP_GSP_CODE_FK AND GSPVO.GSPVO_CDF_VO_CODE_FK_PK = SPVO.SPVO_CDF_VO_CODE_FK_PK
        LEFT JOIN CDF_CODIF CDF_VOIE ON (CDF_VOIE.CDF_CODE_PK = SPVO.SPVO_CDF_VO_CODE_FK_PK
          AND CDF_VOIE.CDF_NUMERO_PK = (''''18''''))
        WHERE SP.SP_CODE_SQ_PK IN ('' || LISTID || '')
        ORDER BY SP.SP_CODE_SQ_PK, CDF0.CDF_NOM, GSPVO.GSPVO_NUM_ORDRE'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API COMPOSITION DETAILLEE SPECIALITE
-- EXEMPLE: LISTID := '4650,2715'

-- DROP FUNCTION GET_THE_COMPO_SPE(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_COMPO_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, SUB.ID AS SUBSTANCE_ID, SUB.NOM AS SUBSTANCE_NOM,
        GSAC.GSAC_CODE_SQ_PK AS SAC_CODE, GSAC.GSAC_NOM AS SAC_NOM, COSAC.COSAC_DOSAGE AS DOSAGE, COSAC.COSAC_UNITEDOSAGE AS UNITE_DOSAGE, COSAC_NUMORD AS NUMORD
        FROM SP_SPECIALITE SP
        LEFT JOIN COSAC_COMPO_SUBACT COSAC ON (COSAC.COSAC_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK)
        LEFT JOIN SAC_SUBACTIVE SAC ON (SAC.SAC_CODE_SQ_PK = COSAC.COSAC_SAC_CODE_FK_PK)
        LEFT JOIN GSAC_PERE_SUBACT GSAC ON GSAC.GSAC_CODE_SQ_PK = SAC.SAC_GSAC_CODE_FK
        LEFT JOIN SUBSTANCE_SACSAU SACSAU ON (SACSAU.SACSAU_ID = COSAC.COSAC_SAC_CODE_FK_PK
          AND UPPER(SACSAU.SACSAU) = ''''SAC'''')
        LEFT JOIN SUBSTANCE SUB ON SUB.ID = SACSAU.SUBSTANCE_ID
        ORDER BY SP_CODE_SQ_PK, NUMORD'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, SUB.ID AS SUBSTANCE_ID, SUB.NOM AS SUBSTANCE_NOM,
        GSAC.GSAC_CODE_SQ_PK AS SAC_CODE, GSAC.GSAC_NOM AS SAC_NOM, COSAC.COSAC_DOSAGE AS DOSAGE, COSAC.COSAC_UNITEDOSAGE AS UNITE_DOSAGE, COSAC_NUMORD AS NUMORD
        FROM SP_SPECIALITE SP
        LEFT JOIN COSAC_COMPO_SUBACT COSAC ON (COSAC.COSAC_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK)
        LEFT JOIN SAC_SUBACTIVE SAC ON (SAC.SAC_CODE_SQ_PK = COSAC.COSAC_SAC_CODE_FK_PK)
        LEFT JOIN GSAC_PERE_SUBACT GSAC ON GSAC.GSAC_CODE_SQ_PK = SAC.SAC_GSAC_CODE_FK
        LEFT JOIN SUBSTANCE_SACSAU SACSAU ON (SACSAU.SACSAU_ID = COSAC.COSAC_SAC_CODE_FK_PK
          AND UPPER(SACSAU.SACSAU) = ''''SAC'''')
        LEFT JOIN SUBSTANCE SUB ON SUB.ID = SACSAU.SUBSTANCE_ID
        WHERE SP.SP_CODE_SQ_PK IN ('' || LISTID || '')
        ORDER BY SP_CODE_SQ_PK, NUMORD'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API COMPOSITION DETAILLEE MEDICAMENT VIRTUEL
-- EXEMPLE: LISTID := '17,4669'

-- DROP FUNCTION GET_THE_COMPO_GSP(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_COMPO_GSP(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT GSP.GSP_CODE_SQ_PK AS CODE_GSP, get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS NOM_GENERIQUE, SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, SUB.ID AS SUBSTANCE_ID, SUB.NOM AS SUBSTANCE_NOM,
        GSAC.GSAC_CODE_SQ_PK AS SAC_CODE, GSAC.GSAC_NOM AS SAC_NOM, CG.COSAC_GSP_DOSAGE AS DOSAGE, CG.COSAC_GSP_UNITEDOSAGE AS UNITE_DOSAGE, COSAC_GSP_NUMORD_PK AS NUMORD
        FROM GSP_GENERIQUE_SPECIALITE GSP
        JOIN SP_SPECIALITE SP ON (SP.SP_GSP_CODE_FK = GSP.GSP_CODE_SQ_PK
          AND GSP.GSP_NB_SUB < 4)
        JOIN COSAC_GSP_COMPO_SUBACT CG ON (CG.COSAC_GSP_CODE_FK_PK = GSP.GSP_CODE_SQ_PK)
        JOIN SAC_SUBACTIVE SAC ON (SAC.SAC_CODE_SQ_PK = COSAC_GSP_SAC_CODE_FK)
        JOIN GSAC_PERE_SUBACT GSAC on (GSAC.GSAC_CODE_SQ_PK = SAC.SAC_GSAC_CODE_FK)
        LEFT JOIN SUBSTANCE_SACSAU SACSAU ON (SACSAU.SACSAU_ID = SAC.SAC_CODE_SQ_PK
          AND UPPER(SACSAU.SACSAU) = ''''SAC'''')
        LEFT JOIN SUBSTANCE SUB ON SUB.ID = SACSAU.SUBSTANCE_ID
        ORDER BY GSP.GSP_CODE_SQ_PK, SP_CODE_SQ_PK, NUMORD;'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT GSP.GSP_CODE_SQ_PK AS CODE_GSP, get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS NOM_GENERIQUE, SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, SUB.ID AS SUBSTANCE_ID, SUB.NOM AS SUBSTANCE_NOM,
        GSAC.GSAC_CODE_SQ_PK AS SAC_CODE, GSAC.GSAC_NOM AS SAC_NOM, CG.COSAC_GSP_DOSAGE AS DOSAGE, CG.COSAC_GSP_UNITEDOSAGE AS UNITE_DOSAGE, COSAC_GSP_NUMORD_PK AS NUMORD
        FROM GSP_GENERIQUE_SPECIALITE GSP
        JOIN SP_SPECIALITE SP ON (SP.SP_GSP_CODE_FK = GSP.GSP_CODE_SQ_PK
          AND GSP.GSP_NB_SUB < 4)
        JOIN COSAC_GSP_COMPO_SUBACT CG ON (CG.COSAC_GSP_CODE_FK_PK = GSP.GSP_CODE_SQ_PK)
        JOIN SAC_SUBACTIVE SAC ON (SAC.SAC_CODE_SQ_PK = COSAC_GSP_SAC_CODE_FK)
        JOIN GSAC_PERE_SUBACT GSAC on (GSAC.GSAC_CODE_SQ_PK = SAC.SAC_GSAC_CODE_FK)
        LEFT JOIN SUBSTANCE_SACSAU SACSAU ON (SACSAU.SACSAU_ID = SAC.SAC_CODE_SQ_PK
          AND UPPER(SACSAU.SACSAU) = ''''SAC'''')
        LEFT JOIN SUBSTANCE SUB ON SUB.ID = SACSAU.SUBSTANCE_ID
        WHERE GSP.GSP_CODE_SQ_PK IN ('' || LISTID || '')
        ORDER BY GSP.GSP_CODE_SQ_PK, SP_CODE_SQ_PK, NUMORD;'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API COMPOSITION SYNTHETIQUE SPECIALITE
-- EXEMPLE: LISTID := '26236,7130,8238,34245,13563,6849,2715'

-- DROP FUNCTION GET_THE_COMPO_SYNTH_SPE(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_COMPO_SYNTH_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT SP.SP_CIPUCD                                                     AS SP_CIPUCD,
                                SP.SP_CODE_SQ_PK                                                 AS SP_CODE_SQ_PK,
                                SP.SP_NOM                                                        AS SP_NOM,
                                DC.ID                                                            AS ID_PRODUIT_DC,
                                DC.LABEL                                                         AS NOM_PRODUIT_DC,
                                GSAC.GSAC_CODE_SQ_PK                                             AS SAC_CODE,
                                COALESCE(GSAC.GSAC_NOM, ''''Non Précisé ou > 3 substances actives'''') AS SAC_NOM,
                                PREDISP.PREDISP_UNITEDISP                                        AS DOSAGE,
                                DOSE.CDF_NOM                                                     AS UNITE_DOSAGE,
                                CG.COSAC_GSP_NUMORD_PK                                           AS NUMORD
                FROM SP_SPECIALITE SP
                         JOIN PRE_PRESENTATION PRE ON (PRE.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK AND PRE.PRE_ETAT_COMMER = ''''D'''')
                         LEFT JOIN PREDISP_PRE_DISPENSATION PREDISP ON PREDISP.PREDISP_PRE_CODE_FK_PK = PRE.PRE_CODE_PK
                         JOIN GSAC_PERE_SUBACT GSAC ON GSAC.GSAC_CODE_SQ_PK = PREDISP.PREDISP_GSAC_CODE_FK
                         JOIN SAC_SUBACTIVE SAC ON SAC.SAC_GSAC_CODE_FK = PREDISP.PREDISP_GSAC_CODE_FK
                         JOIN COSAC_GSP_COMPO_SUBACT CG
                              ON CG.COSAC_GSP_CODE_FK_PK = SP.SP_GSP_CODE_FK AND CG.COSAC_GSP_SAC_CODE_FK = SAC.SAC_CODE_SQ_PK
                         LEFT JOIN CDF_CODIF DOSE ON (DOSE.CDF_CODE_PK = PREDISP.PREDISP_CDF_UD_CODE_FK
                    AND DOSE.CDF_NUMERO_PK = ''''19'''')
                         JOIN GSP_GENERIQUE GSP ON GSP.GSP_GSP_CODE_FK = SP.SP_GSP_CODE_FK
                         JOIN PRODUIT_DC DC ON DC.ID = GSP.GSP_PRODUIT_DC_CODE_FK
                ORDER BY SP_CODE_SQ_PK, CG.COSAC_GSP_NUMORD_PK'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT SP.SP_CIPUCD                                                     AS SP_CIPUCD,
                                SP.SP_CODE_SQ_PK                                                 AS SP_CODE_SQ_PK,
                                SP.SP_NOM                                                        AS SP_NOM,
                                DC.ID                                                            AS ID_PRODUIT_DC,
                                DC.LABEL                                                         AS NOM_PRODUIT_DC,
                                GSAC.GSAC_CODE_SQ_PK                                             AS SAC_CODE,
                                COALESCE(GSAC.GSAC_NOM, ''''Non Précisé ou > 3 substances actives'''') AS SAC_NOM,
                                PREDISP.PREDISP_UNITEDISP                                        AS DOSAGE,
                                DOSE.CDF_NOM                                                     AS UNITE_DOSAGE,
                                CG.COSAC_GSP_NUMORD_PK                                           AS NUMORD
                FROM SP_SPECIALITE SP
                         JOIN PRE_PRESENTATION PRE ON (PRE.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK AND PRE.PRE_ETAT_COMMER = ''''D'''')
                         LEFT JOIN PREDISP_PRE_DISPENSATION PREDISP ON PREDISP.PREDISP_PRE_CODE_FK_PK = PRE.PRE_CODE_PK
                         JOIN GSAC_PERE_SUBACT GSAC ON GSAC.GSAC_CODE_SQ_PK = PREDISP.PREDISP_GSAC_CODE_FK
                         JOIN SAC_SUBACTIVE SAC ON SAC.SAC_GSAC_CODE_FK = PREDISP.PREDISP_GSAC_CODE_FK
                         JOIN COSAC_GSP_COMPO_SUBACT CG
                              ON CG.COSAC_GSP_CODE_FK_PK = SP.SP_GSP_CODE_FK AND CG.COSAC_GSP_SAC_CODE_FK = SAC.SAC_CODE_SQ_PK
                         LEFT JOIN CDF_CODIF DOSE ON (DOSE.CDF_CODE_PK = PREDISP.PREDISP_CDF_UD_CODE_FK
                    AND DOSE.CDF_NUMERO_PK = ''''19'''')
                         JOIN GSP_GENERIQUE GSP ON GSP.GSP_GSP_CODE_FK = SP.SP_GSP_CODE_FK
                         JOIN PRODUIT_DC DC ON DC.ID = GSP.GSP_PRODUIT_DC_CODE_FK
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        ORDER BY SP_CODE_SQ_PK, CG.COSAC_GSP_NUMORD_PK'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API COMPOSITION SYNTHETIQUE MEDICAMENT VIRTUEL
-- EXEMPLE: LISTID := '650,1234,460,2100,3456'

-- DROP FUNCTION GET_THE_COMPO_SYNTH_GSP(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_COMPO_SYNTH_GSP(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT GSP_SPE.GSP_CODE_SQ_PK AS CODE_GSP, get_lb_gsp(GSP_SPE.GSP_CODE_SQ_PK) AS NOM_GENERIQUE, DC.ID AS ID_PRODUIT_DC, DC.LABEL AS NOM_PRODUIT_DC,
        GSAC.GSAC_CODE_SQ_PK AS SAC_CODE, GSAC.GSAC_NOM AS SAC_NOM, CG.COSAC_GSP_DOSAGE AS DOSAGE, CG.COSAC_GSP_UNITEDOSAGE AS UNITE_DOSAGE, COSAC_GSP_NUMORD_PK AS NUMORD
        FROM GSP_GENERIQUE_SPECIALITE GSP_SPE
        JOIN SP_SPECIALITE SP ON SP.SP_GSP_CODE_FK = GSP_SPE.GSP_CODE_SQ_PK
        LEFT JOIN PRE_PRESENTATION PRE ON PRE.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK
        JOIN COSAC_GSP_COMPO_SUBACT CG ON (CG.COSAC_GSP_CODE_FK_PK = GSP_SPE.GSP_CODE_SQ_PK)
        JOIN SAC_SUBACTIVE SAC ON (SAC.SAC_CODE_SQ_PK = COSAC_GSP_SAC_CODE_FK)
        JOIN GSAC_PERE_SUBACT GSAC on (GSAC.GSAC_CODE_SQ_PK = SAC.SAC_GSAC_CODE_FK)
        LEFT JOIN GSP_GENERIQUE GSP ON GSP.GSP_GSP_CODE_FK = GSP_SPE.GSP_CODE_SQ_PK
        LEFT JOIN PRODUIT_DC DC ON DC.ID = GSP.GSP_PRODUIT_DC_CODE_FK
        ORDER BY CODE_GSP, NUMORD'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT GSP_SPE.GSP_CODE_SQ_PK AS CODE_GSP, get_lb_gsp(GSP_SPE.GSP_CODE_SQ_PK) AS NOM_GENERIQUE, DC.ID AS ID_PRODUIT_DC, DC.LABEL AS NOM_PRODUIT_DC,
        GSAC.GSAC_CODE_SQ_PK AS SAC_CODE, GSAC.GSAC_NOM AS SAC_NOM, CG.COSAC_GSP_DOSAGE AS DOSAGE, CG.COSAC_GSP_UNITEDOSAGE AS UNITE_DOSAGE, COSAC_GSP_NUMORD_PK AS NUMORD
        FROM GSP_GENERIQUE_SPECIALITE GSP_SPE
        JOIN SP_SPECIALITE SP ON SP.SP_GSP_CODE_FK = GSP_SPE.GSP_CODE_SQ_PK
        LEFT JOIN PRE_PRESENTATION PRE ON PRE.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK
        JOIN COSAC_GSP_COMPO_SUBACT CG ON (CG.COSAC_GSP_CODE_FK_PK = GSP_SPE.GSP_CODE_SQ_PK)
        JOIN SAC_SUBACTIVE SAC ON (SAC.SAC_CODE_SQ_PK = COSAC_GSP_SAC_CODE_FK)
        JOIN GSAC_PERE_SUBACT GSAC on (GSAC.GSAC_CODE_SQ_PK = SAC.SAC_GSAC_CODE_FK)
        LEFT JOIN GSP_GENERIQUE GSP ON GSP.GSP_GSP_CODE_FK = GSP_SPE.GSP_CODE_SQ_PK
        LEFT JOIN PRODUIT_DC DC ON DC.ID = GSP.GSP_PRODUIT_DC_CODE_FK
        WHERE GSP_SPE.GSP_CODE_SQ_PK IN ('' || LISTID || '')
        ORDER BY CODE_GSP, NUMORD'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API CI OU PE AVEC INSUFFISANCE RENALE
-- EXEMPLE: LISTID := '26236,3671,8932,22169,12368' ET TYPID := 1

-- DROP FUNCTION GET_THE_TER_CIPEMG_CLR(VARCHAR);
CREATE OR REPLACE FUNCTION GET_THE_TER_CIPEMG_CLR (VARCHAR) RETURNS REFCURSOR AS '
DECLARE
  LISTID ALIAS FOR $1;
  CURRET REFCURSOR;
BEGIN
    OPEN CURRET FOR EXECUTE ''SELECT DISTINCT FICHE_CODE,
		               GSP_CODE_SQ_PK AS CODE_GSP,
		               GSP_NOM AS NOM_GENERIQUE,
		               CI_PE,
		               CIM_LIBELLE,
		               STR_MIN AS PDS_MIN,
		               V_MIN,
		               U_MIN,
		               STR_MAX AS PDS_MAX,
		               V_MAX,
		               U_MAX
                FROM VCIPEMG_MIN_MAX
                WHERE ID_UNIT = 70
                  AND SP_CODE_SQ_PK IN (''||LISTID||'')'';
  RETURN CURRET;
END;

' LANGUAGE PLPGSQL;

-- API CI OU PE AVEC INSUFFISANCE RENALE GSP
-- EXEMPLE: SELECT GET_THE_TER_CIPEMG_PDS_GSP ('17,57', 45, 2);

-- DROP FUNCTION GET_THE_TER_CIPEMG_CLR_GSP(VARCHAR);
CREATE OR REPLACE FUNCTION GET_THE_TER_CIPEMG_CLR_GSP (VARCHAR) RETURNS REFCURSOR AS '
DECLARE
  LISTID ALIAS FOR $1;
  CURRET REFCURSOR;
BEGIN
    OPEN CURRET FOR EXECUTE ''SELECT DISTINCT MAX(FICHE_CODE) AS FICHE_CODE,
		               GSP_CODE_SQ_PK AS CODE_GSP,
		               GSP_NOM AS NOM_GENERIQUE,
		               CI_PE,
		               CIM_LIBELLE,
		               STR_MIN AS PDS_MIN,
		               V_MIN,
		               U_MIN,
		               STR_MAX AS PDS_MAX,
		               V_MAX,
		               U_MAX
                FROM VCIPEMG_MIN_MAX
                WHERE ID_UNIT = 70
                  AND GSP_CODE_SQ_PK IN (''||LISTID||'')
                  GROUP BY GSP_CODE_SQ_PK,
                 		   GSP_NOM,
                 		   CI_PE,
                 		   CIM_LIBELLE,
                 		   STR_MIN,
                 		   V_MIN,
                 		   U_MIN,
                 		   STR_MAX,
                 		   V_MAX,
                 		   U_MAX'';
  RETURN CURRET;
END;

' LANGUAGE PLPGSQL;


-- API CI OU PE PROCREATION HOMME ET FEMME SPE V2 EN FONCTION DE L AGE
-- EXEMPLE: LISTID := '22207,7306' ET TYPID := 2

-- DROP FUNCTION GET_THE_PROC_SPEV2(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_PROC_SPEV2(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK AS FICHE_CODE, SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK AS CI_PE, FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_TEXTE AS INFOS
        FROM SP_SPECIALITE SP
        JOIN FCPMSP_CIPEMG_SPE ON FCPMSP_CIPEMG_SPE.FCPMSP_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        JOIN FCPMTER_FCPM_TERRAIN ON (FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK = FCPMSP_CIPEMG_SPE.FCPMSP_FCPM_CODE_FK_PK
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK IN (''''C'''', ''''P'''')
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_CIM_TER_CODE_FK_PK  IN (''''18447'''',''''20449''''))
        LEFT JOIN CDF_MIN_MAX_CODIF CDFMM ON (CDFMM.CDFMM_CDF_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_CDF_TER_CODE_FK_PK
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_CDF_TER_CODE_FK_PK IN(''''6564'''',''''6563''''))
        LEFT JOIN FCPMTX_FICHECIPEMG_TEXTE ON (FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_FCPM_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK
          AND FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_CIM_TER_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_CIM_TER_CODE_FK_PK
          AND FCPMTX_NATURECIPEMG_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK
          AND FCPMTX_NUMSEQ_TER_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_NUMSEQ_PK)
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))'';
        END IF;
        IF TYPID = 2 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK AS FICHE_CODE, SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK AS CI_PE, FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_TEXTE AS INFOS
        FROM SP_SPECIALITE SP
        JOIN FCPMSP_CIPEMG_SPE ON FCPMSP_CIPEMG_SPE.FCPMSP_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        JOIN FCPMTER_FCPM_TERRAIN ON (FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK = FCPMSP_CIPEMG_SPE.FCPMSP_FCPM_CODE_FK_PK
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK IN (''''C'''', ''''P'''')
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_CIM_TER_CODE_FK_PK  IN (''''18448'''',''''20449''''))
        LEFT JOIN CDF_MIN_MAX_CODIF CDFMM ON (CDFMM.CDFMM_CDF_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_CDF_TER_CODE_FK_PK
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_CDF_TER_CODE_FK_PK IN(''''6565'''',''''6563''''))
        LEFT JOIN FCPMTX_FICHECIPEMG_TEXTE ON (FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_FCPM_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK
          AND FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_CIM_TER_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_CIM_TER_CODE_FK_PK
          AND FCPMTX_NATURECIPEMG_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK
          AND FCPMTX_NUMSEQ_TER_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_NUMSEQ_PK)
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API CI OU PE PROCREATION HOMME ET FEMME GSP V2 EN FONCTION DE L AGE
-- EXEMPLE: LISTID := '1747,1758' ET TYPID := 2

-- DROP FUNCTION GET_THE_PROC_GSPV2(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_PROC_GSPV2(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK AS FICHE_CODE, GSP.GSP_CODE_SQ_PK AS GSP_CODE, get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS GSP_NOM, FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK AS CI_PE, FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_TEXTE AS INFOS
        FROM GSP_GENERIQUE_SPECIALITE GSP
        JOIN SP_SPECIALITE SP ON (SP.SP_GSP_CODE_FK = GSP.GSP_CODE_SQ_PK
          AND GSP.GSP_NB_SUB < 4)
        JOIN FCPMSP_CIPEMG_SPE ON FCPMSP_CIPEMG_SPE.FCPMSP_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        JOIN FCPMTER_FCPM_TERRAIN ON (FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK = FCPMSP_CIPEMG_SPE.FCPMSP_FCPM_CODE_FK_PK
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK IN (''''C'''', ''''P'''')
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_CIM_TER_CODE_FK_PK  IN (''''18447'''',''''20449''''))
        LEFT JOIN CDF_MIN_MAX_CODIF CDFMM ON (CDFMM.CDFMM_CDF_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_CDF_TER_CODE_FK_PK
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_CDF_TER_CODE_FK_PK IN(''''6564'''',''''6563''''))
        LEFT JOIN FCPMTX_FICHECIPEMG_TEXTE ON (FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_FCPM_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK
          AND FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_CIM_TER_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_CIM_TER_CODE_FK_PK
          AND FCPMTX_NATURECIPEMG_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK
          AND FCPMTX_NUMSEQ_TER_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_NUMSEQ_PK)
        WHERE GSP.GSP_CODE_SQ_PK IN ('' || LISTID || '')'';
        END IF;
        IF TYPID = 2 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK AS FICHE_CODE, GSP.GSP_CODE_SQ_PK AS GSP_CODE, get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS GSP_NOM, FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK AS CI_PE, FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_TEXTE AS INFOS
        FROM GSP_GENERIQUE_SPECIALITE GSP
        JOIN SP_SPECIALITE SP ON (SP.SP_GSP_CODE_FK = GSP.GSP_CODE_SQ_PK
          AND GSP.GSP_NB_SUB < 4)
        JOIN FCPMSP_CIPEMG_SPE ON FCPMSP_CIPEMG_SPE.FCPMSP_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        JOIN FCPMTER_FCPM_TERRAIN ON (FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK = FCPMSP_CIPEMG_SPE.FCPMSP_FCPM_CODE_FK_PK
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK IN (''''C'''', ''''P'''')
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_CIM_TER_CODE_FK_PK  IN (''''18448'''',''''20449''''))
        LEFT JOIN CDF_MIN_MAX_CODIF CDFMM ON (CDFMM.CDFMM_CDF_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_CDF_TER_CODE_FK_PK
          AND FCPMTER_FCPM_TERRAIN.FCPMTER_CDF_TER_CODE_FK_PK IN(''''6565'''',''''6563''''))
        LEFT JOIN FCPMTX_FICHECIPEMG_TEXTE ON (FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_FCPM_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK
          AND FCPMTX_FICHECIPEMG_TEXTE.FCPMTX_CIM_TER_CODE_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_CIM_TER_CODE_FK_PK
          AND FCPMTX_NATURECIPEMG_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK
          AND FCPMTX_NUMSEQ_TER_FK_PK = FCPMTER_FCPM_TERRAIN.FCPMTER_NUMSEQ_PK)
        WHERE GSP.GSP_CODE_SQ_PK IN ('' || LISTID || '')'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

