        JOIN FCPMTER_FCPM_TERRAIN ON (FCPMTER_FCPM_TERRAIN.FCPMTER_FCPM_CODE_FK_PK = FCPMSP_CIPEMG_SPE.FCPMSP_FCPM_CODE_FK_PK
        AND FCPMTER_FCPM_TERRAIN.FCPMTER_NATURE_CIPEMG_PK IN (''''C'''', ''''P'''')
