            AND CDFMM.CDFMM_CDF_CODE_FK_PK IN (''''PA'''',''''1340'''',''''1346'''',''''1353'''',''''1611'''',''''2714'''',''''4671'''',''''4719'''',''''5694''''))
        WHERE GSP.GSP_CODE_SQ_PK IN ('' || LISTID || '')'';
