CREATE
OR REPLACE FUNCTION GET_THE_CIPE_GSP_CIM10(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
                SELECT DISTINCT GSP.GSP_CODE_SQ_PK               AS GSP_CODE,
                                get_lb_gsp(GSP.GSP_CODE_SQ_PK)   AS GSP_NOM,
                                FCPMTER.FCPMTER_NATURE_CIPEMG_PK AS CIPE,
                                substr(CIM10.CIM_CODE, 1, 3)      AS CODE_CIM10,
                                CIM10.CIM_LIBELLE                AS LIBELLE_CIM10,
                                CIM10.CIM_CODE                    AS CODE_CIM10_COMPLET
                FROM GSP_GENERIQUE_SPECIALITE GSP
                         JOIN SP_SPECIALITE SP ON (SP.SP_GSP_CODE_FK = GSP.GSP_CODE_SQ_PK
                    AND GSP.GSP_NB_SUB < 4)
