-- API HYPNOTIQUES SPE.
-- 2020-04-28 : From GSP
-- EXEMPLE: SELECT  GET_THE_HYPNO_SPE ('4561,9243454,408', 1);
CREATE
OR REPLACE FUNCTION GET_THE_HYPNO_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CIPUCD     AS SP_CIPUCD,
                   SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK,
                   SP.SP_NOM        AS SP_NOM,
                   ''''O''''              AS HYPNOTIQUE
            FROM SP_SPECIALITE SP
                     JOIN GSP_GENERIQUE_SPECIALITE ON GSP_CODE_SQ_PK = SP_GSP_CODE_FK
                     JOIN gsptype_gsp_type ON GSPTYPE_FK_PK = SP_GSP_CODE_FK AND TYPE_CODE_FK_PK = 11
            WHERE SP_CDF_SLAB_CODE_FK <> 7
            ORDER BY SP_CODE_SQ_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CIPUCD                                            AS SP_CIPUCD,
                   SP.SP_CODE_SQ_PK                                        AS SP_CODE_SQ_PK,
                   SP.SP_NOM                                               AS SP_NOM,
                   CASE WHEN TYPE_CODE_FK_PK is null then ''''N'''' else ''''O'''' end AS HYPNOTIQUE
            FROM SP_SPECIALITE SP
                     JOIN GSP_GENERIQUE_SPECIALITE ON GSP_CODE_SQ_PK = SP_GSP_CODE_FK
                     LEFT JOIN gsptype_gsp_type ON GSPTYPE_FK_PK = SP_GSP_CODE_FK AND TYPE_CODE_FK_PK = 11
            WHERE SP_CDF_SLAB_CODE_FK <> 7
              AND (SP.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
        ORDER BY SP_CODE_SQ_PK
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

