CREATE
OR REPLACE FUNCTION GET_THE_CFO_SECABLE_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CIPUCD,
                   SP.SP_CODE_SQ_PK,
                   SP.SP_NOM,
                   CDF.CDF_NOM AS LIBELLE
            FROM SP_SPECIALITE SP
                     JOIN SPFOCFO_SPE_FORME_COMPFORME SPFOCFO
                          ON (SPFOCFO.SPFOCFO_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
                              AND SPFOCFO.SPFOCFO_CDF_CFO_CODE_FK_PK IN (''''14'''', ''''15'''', ''''78''''))
                     JOIN CDF_CODIF CDF
                          ON (CDF.CDF_CODE_PK = SPFOCFO.SPFOCFO_CDF_CFO_CODE_FK_PK
                              AND CDF.CDF_NUMERO_PK = ''''02'''')
            ORDER BY SP.SP_NOM
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, CDF.CDF_NOM AS LIBELLE
        FROM SP_SPECIALITE SP
        LEFT JOIN SPFOCFO_SPE_FORME_COMPFORME SPFOCFO ON (SPFOCFO.SPFOCFO_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
          AND SPFOCFO.SPFOCFO_CDF_CFO_CODE_FK_PK IN (''''14'''', ''''15'''', ''''78''''))
        LEFT JOIN CDF_CODIF CDF ON (CDF.CDF_CODE_PK = SPFOCFO.SPFOCFO_CDF_CFO_CODE_FK_PK
          AND CDF.CDF_NUMERO_PK = ''''02'''')
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        ORDER BY SP.SP_CODE_SQ_PK'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

