-- DROP FUNCTION GET_THE_LI_PRESC_SPE(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_LI_PRESC_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, CDF.CDF_NOM AS PRESCRIPTION
        FROM SP_SPECIALITE SP
        JOIN CDF_CODIF CDF ON CDF.CDF_CODE_PK = SP.SP_CDF_LI_CODE_FK
        WHERE CDF_NUMERO_PK = ''''08''''
        ORDER BY SP_CODE_SQ_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, CDF.CDF_NOM AS PRESCRIPTION
        FROM SP_SPECIALITE SP
        JOIN CDF_CODIF CDF ON CDF.CDF_CODE_PK = SP.SP_CDF_LI_CODE_FK
        WHERE CDF_NUMERO_PK = ''''08''''
        AND (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        ORDER BY SP_CODE_SQ_PK'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API CONDITION D ADMINISTRATION SPE
-- EXEMPLE: LISTID := '7690,7335,5925,4143' ET TYPID := 1

-- DROP FUNCTION GET_THE_COND_ADMIN_SPE(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_COND_ADMIN_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM,
        CASE
            WHEN CDF.CDF_NOM IS NULL THEN ''''''''
            ELSE CDF.CDF_NOM
          END AS ADMINISTRATION
        FROM SP_SPECIALITE SP
        LEFT JOIN FRECSP_RECONST_SPEC FRECSP ON FRECSP.FRECSP_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        LEFT JOIN FRECCOA_FREC_COMADM FRECCOA ON (FRECCOA.FRECCOA_FREC_CODE_FK_PK = FRECSP.FRECSP_FREC_CODE_FK_PK
          AND FRECCOA.FRECCOA_CDF_COMADM_FK_PK IN (''''M210'''',''''M211'''',''''M214'''',''''M216'''',''''M223'''',''''M224'''',''''M225'''',''''M226'''',''''M227'''',''''M228'''',''''M244'''',''''M245'''',''''M248'''',''''M253'''',''''M258'''',''''M264'''',''''M265'''',''''M266'''',''''M267'''',''''M269'''',''''M274'''',''''M275'''',''''M276'''',''''M286'''',''''M290'''',''''M291'''',''''M292'''',''''M294'''',''''M295'''',''''M298'''',''''M300'''',''''M301'''',''''M302'''',''''M303'''',''''M304'''',''''M305'''',''''M306'''',''''M307'''',''''M308'''',''''M309'''',''''M310'''',''''M312'''',''''M313'''',''''M314'''',''''M315'''',''''M317'''',''''M318'''',''''M319'''',''''M320'''',''''O'''',''''O19'''',''''O2'''',''''O20'''',''''O22'''',''''O23'''',''''O26'''',''''O29'''',''''O31'''',''''O32'''',''''O33'''',''''O36'''',''''O41'''',''''O42'''',''''O46'''',''''O47'''',''''O50'''',''''O51'''',''''O53'''',''''O54'''',''''O56'''',''''O57'''',''''O69'''',''''O7'''',''''O70'''',''''O71'''',''''O72'''',''''O73'''',''''O75'''',''''O76'''',''''O77'''',''''O78'''',''''O79'''',''''O8'''',''''O80'''',''''O81'''',''''O83'''',''''O84'''',''''O85''''))
        LEFT JOIN CDF_CODIF CDF ON (CDF.CDF_CODE_PK = FRECCOA.FRECCOA_CDF_COMADM_FK_PK
          AND CDF.CDF_NUMERO_PK = ''''RC'''')
        ORDER BY SP_CODE_SQ_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM,
        CASE
            WHEN CDF.CDF_NOM IS NULL THEN ''''''''
            ELSE CDF.CDF_NOM
          END AS ADMINISTRATION
        FROM SP_SPECIALITE SP
        LEFT JOIN FRECSP_RECONST_SPEC FRECSP ON FRECSP.FRECSP_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        LEFT JOIN FRECCOA_FREC_COMADM FRECCOA ON (FRECCOA.FRECCOA_FREC_CODE_FK_PK = FRECSP.FRECSP_FREC_CODE_FK_PK
          AND FRECCOA.FRECCOA_CDF_COMADM_FK_PK IN (''''M210'''',''''M211'''',''''M214'''',''''M216'''',''''M223'''',''''M224'''',''''M225'''',''''M226'''',''''M227'''',''''M228'''',''''M244'''',''''M245'''',''''M248'''',''''M253'''',''''M258'''',''''M264'''',''''M265'''',''''M266'''',''''M267'''',''''M269'''',''''M274'''',''''M275'''',''''M276'''',''''M286'''',''''M290'''',''''M291'''',''''M292'''',''''M294'''',''''M295'''',''''M298'''',''''M300'''',''''M301'''',''''M302'''',''''M303'''',''''M304'''',''''M305'''',''''M306'''',''''M307'''',''''M308'''',''''M309'''',''''M310'''',''''M312'''',''''M313'''',''''M314'''',''''M315'''',''''M317'''',''''M318'''',''''M319'''',''''M320'''',''''O'''',''''O19'''',''''O2'''',''''O20'''',''''O22'''',''''O23'''',''''O26'''',''''O29'''',''''O31'''',''''O32'''',''''O33'''',''''O36'''',''''O41'''',''''O42'''',''''O46'''',''''O47'''',''''O50'''',''''O51'''',''''O53'''',''''O54'''',''''O56'''',''''O57'''',''''O69'''',''''O7'''',''''O70'''',''''O71'''',''''O72'''',''''O73'''',''''O75'''',''''O76'''',''''O77'''',''''O78'''',''''O79'''',''''O8'''',''''O80'''',''''O81'''',''''O83'''',''''O84'''',''''O85''''))
        LEFT JOIN CDF_CODIF CDF ON (CDF.CDF_CODE_PK = FRECCOA.FRECCOA_CDF_COMADM_FK_PK
          AND CDF.CDF_NUMERO_PK = ''''RC'''')
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        ORDER BY SP_CODE_SQ_PK'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API LABORATOIRE EXPLOITANT SPE
-- EXEMPLE: LISTID := '7690,7335,5925,4143' ET TYPID := 1

-- DROP FUNCTION GET_THE_LABO_EXPLOIT_SPE(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_LABO_EXPLOIT_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD     AS SP_CIPUCD,
                   SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK,
                   SP.SP_NOM        AS SP_NOM,
                   LSP.LSP_LIBELLE  AS LABO_EXPLOITANT
            FROM SP_SPECIALITE SP
                     LEFT JOIN SPLSPEX_SPECIALITE_LABO SPLSP
                               ON SPLSP.SPLSPEX_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
                     LEFT JOIN LABO_SP LSP
                               ON LSP.LSP_CODE_SQ_PK = SPLSP.SPLSPEX_LSP_CODE_FK_PK
            ORDER BY SP_CODE_SQ_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CIPUCD     AS SP_CIPUCD,
                   SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK,
                   SP.SP_NOM        AS SP_NOM,
                   LSP.LSP_LIBELLE  AS LABO_EXPLOITANT
            FROM SP_SPECIALITE SP
                     LEFT JOIN SPLSPEX_SPECIALITE_LABO SPLSP
                               ON SPLSP.SPLSPEX_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
                     LEFT JOIN LABO_SP LSP
                               ON LSP.LSP_CODE_SQ_PK = SPLSP.SPLSPEX_LSP_CODE_FK_PK
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        ORDER BY SP_CODE_SQ_PK'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API PRODUIT DERIVE DU SANG SPE
-- EXEMPLE: select GET_THE_PR_DERIV_SANG_SPE ('4561,9246116,3473', 1);
-- 2020-04-27 : From GSP
CREATE
OR REPLACE FUNCTION GET_THE_PR_DERIV_SANG_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CIPUCD     AS SP_CIPUCD,
                   SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK,
                   SP.SP_NOM        AS SP_NOM,
                   ''''O''''              AS PRODUIT_DERIV_SANG
            FROM SP_SPECIALITE SP
                     JOIN GSP_GENERIQUE_SPECIALITE ON GSP_CODE_SQ_PK = SP_GSP_CODE_FK
                     JOIN gsptype_gsp_type ON GSPTYPE_FK_PK = SP_GSP_CODE_FK AND TYPE_CODE_FK_PK = 19
            WHERE SP_CDF_SLAB_CODE_FK <> 7
            ORDER BY PRODUIT_DERIV_SANG DESC, SP_CODE_SQ_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CIPUCD                                            AS SP_CIPUCD,
                   SP.SP_CODE_SQ_PK                                        AS SP_CODE_SQ_PK,
                   SP.SP_NOM                                               AS SP_NOM,
                   CASE WHEN TYPE_CODE_FK_PK is null then ''''N'''' else ''''O'''' end AS PRODUIT_DERIV_SANG
            FROM SP_SPECIALITE SP
                     JOIN GSP_GENERIQUE_SPECIALITE ON GSP_CODE_SQ_PK = SP_GSP_CODE_FK
                     LEFT JOIN gsptype_gsp_type ON GSPTYPE_FK_PK = SP_GSP_CODE_FK AND TYPE_CODE_FK_PK = 19
            WHERE SP_CDF_SLAB_CODE_FK <> 7
              AND (SP.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
            ORDER BY PRODUIT_DERIV_SANG DESC,SP_CODE_SQ_PK
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API PRODUIT DERIVE DU SANG GSP
-- EXEMPLE: select GET_THE_PR_DERIV_SANG_GSP ('4612,12,1788', 1);
-- 2020-04-27 : From GSP
CREATE
OR REPLACE FUNCTION GET_THE_PR_DERIV_SANG_GSP(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT DISTINCT GSP.GSP_CODE_SQ_PK                                      AS GSP_CODE,
                            get_lb_gsp(GSP.GSP_CODE_SQ_PK)                                             AS GSP_NOM,
                            ''''O'''' AS PRODUIT_DERIV_SANG
            FROM GSP_GENERIQUE_SPECIALITE GSP
                     JOIN gsptype_gsp_type ON GSPTYPE_FK_PK = GSP_CODE_SQ_PK AND TYPE_CODE_FK_PK = 19
            ORDER BY PRODUIT_DERIV_SANG DESC, GSP_CODE
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
              SELECT DISTINCT GSP.GSP_CODE_SQ_PK AS GSP_CODE,
                              get_lb_gsp(GSP.GSP_CODE_SQ_PK) AS GSP_NOM,
                              CASE WHEN TYPE_CODE_FK_PK is null then ''''N'''' else ''''O'''' end AS PRODUIT_DERIV_SANG
              FROM GSP_GENERIQUE_SPECIALITE GSP
               LEFT JOIN gsptype_gsp_type ON GSPTYPE_FK_PK = GSP_CODE_SQ_PK AND TYPE_CODE_FK_PK = 19
              WHERE GSP.GSP_CODE_SQ_PK IN ('' || LISTID || '')
        ORDER BY PRODUIT_DERIV_SANG DESC,GSP_CODE
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API MEDICAMENT ORPHELIN SPE
-- EXEMPLE: LISTID := '7690,7335,5925,4143' ET TYPID := 1

-- DROP FUNCTION GET_THE_MEDIC_ORPH_SPE(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_MEDIC_ORPH_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM,
          CASE
              WHEN PRESTC.PRESTC_CDF_STCOMP_CODE_FK_PK = ''''C8'''' THEN ''''O''''
              ELSE ''''N''''
            END AS MEDICAMENT_ORPHELIN
        FROM SP_SPECIALITE SP
        LEFT JOIN PRE_PRESENTATION PRE ON PRE.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK
        LEFT JOIN PRESTC_STATUTCOMP_PRESENT PRESTC ON (PRESTC.PRESTC_PRE_CODE_FK_PK = PRE.PRE_CODE_PK
          AND PRESTC.PRESTC_CDF_STCOMP_CODE_FK_PK = ''''C8'''')
        ORDER BY SP_CODE_SQ_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM,
          CASE
              WHEN PRESTC.PRESTC_CDF_STCOMP_CODE_FK_PK = ''''C8'''' THEN ''''O''''
              ELSE ''''N''''
            END AS MEDICAMENT_ORPHELIN
        FROM SP_SPECIALITE SP
        LEFT JOIN PRE_PRESENTATION PRE ON PRE.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK
        LEFT JOIN PRESTC_STATUTCOMP_PRESENT PRESTC ON (PRESTC.PRESTC_PRE_CODE_FK_PK = PRE.PRE_CODE_PK
          AND PRESTC.PRESTC_CDF_STCOMP_CODE_FK_PK = ''''C8'''')
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        ORDER BY SP_CODE_SQ_PK'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API PGR ET SURVEILLANCE RENFORCEE SPE
-- EXEMPLE: LISTID := '4561,12660,20668' ET TYPID := 1
-- TFL 1323 => Modification API basée sur PGR
-- EXEMPLE : select GET_THE_PGR_SURV_RENF_SPE('46, 52068, 52082, 52104, 52108, 2 , 3', 1);

-- DROP FUNCTION GET_THE_PGR_SURV_RENF_SPE(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_PGR_SURV_RENF_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;


    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT DISTINCT SP.SP_CIPUCD     AS SP_CIPUCD,
                            SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK,
                            SP.SP_NOM        AS SP_NOM,
                            CASE
                                WHEN pgr.SPCPD_SP_CODE_FK_PK IS NOT NULL THEN ''''O''''
                                ELSE ''''N''''
                                END          AS PGR,
                            CASE
                                WHEN sur.SPCPD_SP_CODE_FK_PK IS NOT NULL THEN ''''O''''
                                ELSE ''''N''''
                                END          AS SURV_RENFORCEE
            FROM SP_SPECIALITE SP
                     LEFT JOIN VSPCPD_SPE_CDT_PRESCR pgr
                               ON pgr.SPCPD_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
                                   AND pgr.SPCPD_CDF_STP_CODE_FK_PK = ''''S999''''
                     LEFT JOIN VSPCPD_SPE_CDT_PRESCR sur
                               ON sur.SPCPD_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
                                   AND sur.SPCPD_CDF_STP_CODE_FK_PK = ''''S114''''
            ORDER BY SP_CODE_SQ_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT DISTINCT SP.SP_CIPUCD     AS SP_CIPUCD,
                            SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK,
                            SP.SP_NOM        AS SP_NOM,
                            CASE
                                WHEN pgr.SPCPD_SP_CODE_FK_PK IS NOT NULL THEN ''''O''''
                                ELSE ''''N''''
                                END          AS PGR,
                            CASE
                                WHEN sur.SPCPD_SP_CODE_FK_PK IS NOT NULL THEN ''''O''''
                                ELSE ''''N''''
                                END          AS SURV_RENFORCEE
            FROM SP_SPECIALITE SP
                     LEFT JOIN VSPCPD_SPE_CDT_PRESCR pgr
                               ON pgr.SPCPD_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
                                   AND pgr.SPCPD_CDF_STP_CODE_FK_PK = ''''S999''''
                     LEFT JOIN VSPCPD_SPE_CDT_PRESCR sur
                               ON sur.SPCPD_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
                                   AND sur.SPCPD_CDF_STP_CODE_FK_PK = ''''S114''''
            WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
            ORDER BY SP_CODE_SQ_PK
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API REDONDANCE SPE
-- EXEMPLE: LISTID := '7690,7335,5925,4143' ET TYPID := 1

-- DROP FUNCTION GET_THE_REDOND_SPE(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_REDOND_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CODE_SQ_PK AS SP_CODE_ANALYSE, SP.SP_NOM AS SP_NOM_ANALYSE, ''''O'''' AS REDONDANCE_MEME_CLASSE_ATC, SP2.SP_CODE_SQ_PK AS SP2_CODE_REDOND, SP2.SP_NOM AS SP2_NOM_REDOND
        FROM SP_SPECIALITE SP, SP_SPECIALITE SP2
       WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''',''''))) AND (SP2.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP2.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
        AND LENGTH(SP.SP_CATC_CODE_FK) = 5
        AND LENGTH(SP2.SP_CATC_CODE_FK) = 5
        AND SP.SP_CATC_CODE_FK = SP2.SP_CATC_CODE_FK
        AND SP.SP_CODE_SQ_PK != SP2.SP_CODE_SQ_PK
        UNION
        SELECT SP.SP_CODE_SQ_PK AS SP_CODE_ANALYSE, SP.SP_NOM AS SP_NOM_ANALYSE, ''''N'''' AS REDONDANCE_MEME_CLASSE_ATC, (null) AS SP2_CODE_REDOND, (null) AS SP2_NOM_REDOND
        FROM SP_SPECIALITE SP
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        AND SP.SP_CODE_SQ_PK NOT IN (
          SELECT SP.SP_CODE_SQ_PK
          FROM SP_SPECIALITE SP, SP_SPECIALITE SP2
          WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''',''''))) AND (SP2.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP2.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
          AND LENGTH(SP.SP_CATC_CODE_FK) = 5
          AND LENGTH(SP2.SP_CATC_CODE_FK) = 5
          AND SP.SP_CATC_CODE_FK = SP2.SP_CATC_CODE_FK
          AND SP.SP_CODE_SQ_PK != SP2.SP_CODE_SQ_PK
        )
        ORDER BY SP_CODE_ANALYSE
        '';
        END IF;
        IF TYPID = 2 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CODE_SQ_PK AS SP_CODE_ANALYSE, SP.SP_NOM AS SP_NOM_ANALYSE, ''''O'''' AS REDONDANCE_MEME_CLASSE_SAC, SP2.SP_CODE_SQ_PK AS SP2_CODE_REDOND, SP2.SP_NOM AS SP2_NOM_REDOND, GSAC1.GSAC_NOM AS NOM_SAC_COMMUNE
        FROM SP_SPECIALITE SP
        JOIN COSAC_COMPO_SUBACT COSAC1 ON COSAC1.COSAC_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        JOIN SAC_SUBACTIVE SAC1 ON SAC1.SAC_CODE_SQ_PK = COSAC1.COSAC_SAC_CODE_FK_PK
        JOIN GSAC_PERE_SUBACT GSAC1 ON GSAC1.GSAC_CODE_SQ_PK = SAC1.SAC_GSAC_CODE_FK,
        SP_SPECIALITE SP2
        JOIN COSAC_COMPO_SUBACT COSAC2 ON COSAC2.COSAC_SP_CODE_FK_PK = SP2.SP_CODE_SQ_PK
        JOIN SAC_SUBACTIVE SAC2 ON SAC2.SAC_CODE_SQ_PK = COSAC2.COSAC_SAC_CODE_FK_PK
        JOIN GSAC_PERE_SUBACT GSAC2 ON GSAC2.GSAC_CODE_SQ_PK = SAC2.SAC_GSAC_CODE_FK
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''',''''))) AND (SP2.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP2.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
        AND LENGTH(SP.SP_CATC_CODE_FK) = 7
        AND LENGTH(SP2.SP_CATC_CODE_FK) = 7
        AND GSAC1.GSAC_CODE_SQ_PK = GSAC2.GSAC_CODE_SQ_PK
        AND SP.SP_CATC_CODE_FK = SP2.SP_CATC_CODE_FK
        AND SP.SP_CODE_SQ_PK != SP2.SP_CODE_SQ_PK
        UNION
        SELECT SP.SP_CODE_SQ_PK AS SP_CODE_ANALYSE, SP.SP_NOM AS SP_NOM_ANALYSE, ''''N'''' AS REDONDANCE_MEME_CLASSE_SAC, (null) AS SP2_CODE_REDOND, (null) AS SP2_NOM_REDOND, (null) AS NOM_SAC_COMMUNE
        FROM SP_SPECIALITE SP
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        AND SP.SP_CODE_SQ_PK NOT IN (
          SELECT SP.SP_CODE_SQ_PK
          FROM SP_SPECIALITE SP
          JOIN COSAC_COMPO_SUBACT COSAC1 ON COSAC1.COSAC_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
          JOIN SAC_SUBACTIVE SAC1 ON SAC1.SAC_CODE_SQ_PK = COSAC1.COSAC_SAC_CODE_FK_PK
          JOIN GSAC_PERE_SUBACT GSAC1 ON GSAC1.GSAC_CODE_SQ_PK = SAC1.SAC_GSAC_CODE_FK,
          SP_SPECIALITE SP2
          JOIN COSAC_COMPO_SUBACT COSAC2 ON COSAC2.COSAC_SP_CODE_FK_PK = SP2.SP_CODE_SQ_PK
          JOIN SAC_SUBACTIVE SAC2 ON SAC2.SAC_CODE_SQ_PK = COSAC2.COSAC_SAC_CODE_FK_PK
          JOIN GSAC_PERE_SUBACT GSAC2 ON GSAC2.GSAC_CODE_SQ_PK = SAC2.SAC_GSAC_CODE_FK
          WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''',''''))) AND (SP2.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP2.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
          AND LENGTH(SP.SP_CATC_CODE_FK) = 7
          AND LENGTH(SP2.SP_CATC_CODE_FK) = 7
          AND GSAC1.GSAC_CODE_SQ_PK = GSAC2.GSAC_CODE_SQ_PK
          AND SP.SP_CATC_CODE_FK = SP2.SP_CATC_CODE_FK
          AND SP.SP_CODE_SQ_PK != SP2.SP_CODE_SQ_PK
        )
        ORDER BY SP_CODE_ANALYSE
        '';
        END IF;
        IF TYPID = 3 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CODE_SQ_PK AS SP_CODE_ANALYSE, SP.SP_NOM AS SP_NOM_ANALYSE, ''''O'''' AS REDONDANCE_MEME_SAC, SP2.SP_CODE_SQ_PK AS SP2_CODE_REDOND, SP2.SP_NOM AS SP2_NOM_REDOND, GSAC1.GSAC_NOM AS NOM_SAC_COMMUNE
        FROM SP_SPECIALITE SP
        JOIN COSAC_COMPO_SUBACT COSAC1 ON COSAC1.COSAC_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
        JOIN SAC_SUBACTIVE SAC1 ON SAC1.SAC_CODE_SQ_PK = COSAC1.COSAC_SAC_CODE_FK_PK
        JOIN GSAC_PERE_SUBACT GSAC1 ON GSAC1.GSAC_CODE_SQ_PK = SAC1.SAC_GSAC_CODE_FK,
        SP_SPECIALITE SP2
        JOIN COSAC_COMPO_SUBACT COSAC2 ON COSAC2.COSAC_SP_CODE_FK_PK = SP2.SP_CODE_SQ_PK
        JOIN SAC_SUBACTIVE SAC2 ON SAC2.SAC_CODE_SQ_PK = COSAC2.COSAC_SAC_CODE_FK_PK
        JOIN GSAC_PERE_SUBACT GSAC2 ON GSAC2.GSAC_CODE_SQ_PK = SAC2.SAC_GSAC_CODE_FK
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''',''''))) AND (SP2.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP2.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
        AND GSAC1.GSAC_CODE_SQ_PK = GSAC2.GSAC_CODE_SQ_PK
        AND SP.SP_CODE_SQ_PK != SP2.SP_CODE_SQ_PK
        UNION
        SELECT SP.SP_CODE_SQ_PK AS SP_CODE_ANALYSE, SP.SP_NOM AS SP_NOM_ANALYSE, ''''N'''' AS REDONDANCE_MEME_SAC, (null) AS SP2_CODE_REDOND, (null) AS SP2_NOM_REDOND, (null) AS NOM_SAC_COMMUNE
        FROM SP_SPECIALITE SP
        WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        AND SP.SP_CODE_SQ_PK NOT IN (
          SELECT SP.SP_CODE_SQ_PK
          FROM SP_SPECIALITE SP
          JOIN COSAC_COMPO_SUBACT COSAC1 ON COSAC1.COSAC_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
          JOIN SAC_SUBACTIVE SAC1 ON SAC1.SAC_CODE_SQ_PK = COSAC1.COSAC_SAC_CODE_FK_PK
          JOIN GSAC_PERE_SUBACT GSAC1 ON GSAC1.GSAC_CODE_SQ_PK = SAC1.SAC_GSAC_CODE_FK,
          SP_SPECIALITE SP2
          JOIN COSAC_COMPO_SUBACT COSAC2 ON COSAC2.COSAC_SP_CODE_FK_PK = SP2.SP_CODE_SQ_PK
          JOIN SAC_SUBACTIVE SAC2 ON SAC2.SAC_CODE_SQ_PK = COSAC2.COSAC_SAC_CODE_FK_PK
          JOIN GSAC_PERE_SUBACT GSAC2 ON GSAC2.GSAC_CODE_SQ_PK = SAC2.SAC_GSAC_CODE_FK
          WHERE (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''',''''))) AND (SP2.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP2.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
          AND GSAC1.GSAC_CODE_SQ_PK = GSAC2.GSAC_CODE_SQ_PK
          AND SP.SP_CODE_SQ_PK != SP2.SP_CODE_SQ_PK
        )
        ORDER BY SP_CODE_ANALYSE'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API GET_THE_GSP_INDIC_BY_CIM10

-- DROP FUNCTION GET_THE_GSP_INDIC_BY_CIM10(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_GSP_INDIC_BY_CIM10(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        CODE_CIM ALIAS FOR $1; TYP ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYP = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT CIM_CODE, CIM_LIBELLE, GSP_CODE_SQ_PK AS ID_GPE, get_lb_gsp(GSP_CODE_SQ_PK) AS LIB_GSP
FROM CIM10V2 CIM
JOIN FIN_FICHEINDIC FIN ON (FIN.FIN_CIM_NAIN_CODE_FK_PK = CIM.ID)
JOIN FINSP_INDSPE FINSP ON (FINSP.FINSP_FIN_CODE_FK_PK = FIN.FIN_CODE_SQ_PK)
		JOIN SP_SPECIALITE SP ON (SP.SP_CODE_SQ_PK = FINSP.FINSP_SP_CODE_FK_PK AND SP.SP_CDF_SLAB_CODE_FK <> ''''7'''')
		JOIN SP_INFORMATIONS INF ON (INF.SP_CODE_SQ_PK = SP.SP_CODE_SQ_PK AND INF.ETAT_COMMERCIALISATION NOT IN (''''S'''', ''''NC'''') AND INF.ETAT_COMMERCIALISATION IS NOT NULL)
JOIN GSP_GENERIQUE_SPECIALITE GSP ON (GSP.GSP_CODE_SQ_PK = SP_GSP_CODE_FK)
WHERE CIM.CIM_CODE LIKE (
CASE
  WHEN POSITION(''''.'''' in '' || CODE_CIM || '' ) = 0 THEN '' || CODE_CIM || '' || ''''%''''
  ELSE SUBSTRING('' || CODE_CIM || '', 0, POSITION(''''.'''' IN '' || CODE_CIM || '') )||''''%''''
END
)
GROUP BY CIM_CODE, CIM_LIBELLE, GSP_CODE_SQ_PK, get_lb_gsp(GSP_CODE_SQ_PK)
ORDER BY CIM_CODE,LIB_GSP'';
        END IF;
        IF TYP = 2 THEN
            OPEN CURRET FOR EXECUTE ''SELECT CIM_CODE, CIM_LIBELLE, GSP_CODE_SQ_PK AS ID_GPE, get_lb_gsp(GSP_CODE_SQ_PK) AS LIB_GSP
FROM CIM10V2 CIM
JOIN FIN_FICHEINDIC FIN ON (FIN.FIN_CIM_NAIN_CODE_FK_PK = CIM.ID)
JOIN FINSP_INDSPE FINSP ON (FINSP.FINSP_FIN_CODE_FK_PK = FIN.FIN_CODE_SQ_PK)
		JOIN SP_SPECIALITE SP ON (SP.SP_CODE_SQ_PK = FINSP.FINSP_SP_CODE_FK_PK AND SP.SP_CDF_SLAB_CODE_FK <> ''''7'''')
		JOIN SP_INFORMATIONS INF ON (INF.SP_CODE_SQ_PK = SP.SP_CODE_SQ_PK AND INF.ETAT_COMMERCIALISATION NOT IN (''''S'''', ''''NC'''') AND INF.ETAT_COMMERCIALISATION IS NOT NULL)
JOIN GSP_GENERIQUE_SPECIALITE GSP ON (GSP.GSP_CODE_SQ_PK = SP_GSP_CODE_FK)
WHERE CIM.CIM_CODE = '' || CODE_CIM || ''
GROUP BY CIM_CODE, CIM_LIBELLE, GSP_CODE_SQ_PK, get_lb_gsp(GSP_CODE_SQ_PK)
ORDER BY CIM_CODE,LIB_GSP'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API GET_THE_COMPO_ALLSUB_SP
-- EXEMPLE: SELECT GET_THE_COMPO_ALLSUB_SP (4561);

-- DROP FUNCTION GET_THE_COMPO_ALLSUB_SP(NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_COMPO_ALLSUB_SP(NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        CODEID ALIAS FOR $1;
        CURRET REFCURSOR;
    BEGIN
        OPEN CURRET FOR EXECUTE ''
              SELECT ''''SUBAUX''''       AS TYPSUBST,
                     COSAU_DOSAGE         AS DOSESUBST,
                     COSAU_UNITEDOSAGE    AS UDOSESUBST,
                     SAU_GSAU_CODE_FK     AS ID_SUB_PERE,
                     GSAU_NOM             AS SUB_PERE,
                     COSAU_SAU_CODE_FK_PK AS ID_SUB,
                     SAU_NOM              AS SUB_NOM,
                     COSAU_NUMORD         AS NUMORDRE,
                     COSAU_COMPO_NUM_PK   AS COMPORDRE
              FROM COSAU_COMPO_SUBAUX
                       JOIN SAU_SUBAUXILIAIRE ON COSAU_SAU_CODE_FK_PK = SAU_CODE_SQ_PK
                       LEFT JOIN GSAU_PERE_SUBAUX ON GSAU_CODE_SQ_PK = SAU_GSAU_CODE_FK
              WHERE COSAU_SP_CODE_FK_PK = '''''' || CODEID || ''''''
        UNION
        SELECT ''''SUBAC''''        AS TYPSUBST,
               COSAC_DOSAGE         AS DOSESUBST,
               COSAC_UNITEDOSAGE    AS UDOSESUBST,
               SAC_GSAC_CODE_FK     AS ID_SUB_PERE,
               GSAC_NOM             AS SUB_PERE,
               COSAC_SAC_CODE_FK_PK AS ID_SUB,
               SAC_NOM              AS SUB_NOM,
               COSAC_NUMORD         AS NUMORDRE,
               COSAC_COMPO_NUM_PK   AS COMPORDRE
        FROM COSAC_COMPO_SUBACT
                 JOIN SAC_SUBACTIVE ON SAC_CODE_SQ_PK = COSAC_SAC_CODE_FK_PK
                 LEFT JOIN GSAC_PERE_SUBACT ON GSAC_CODE_SQ_PK = SAC_GSAC_CODE_FK
        WHERE COSAC_SP_CODE_FK_PK = '''''' || CODEID || ''''''
        ORDER BY 1, 8, 9
        '';
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API GET_THE_DELIVRE_MAX
-- EXEMPLE: select GET_THE_DELIVRE_MAX('4643,16196');

-- DROP FUNCTION GET_THE_DELIVRE_MAX(VARCHAR);
CREATE
OR REPLACE FUNCTION GET_THE_DELIVRE_MAX(VARCHAR) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        CURRET REFCURSOR;
    BEGIN
        OPEN CURRET FOR EXECUTE ''
SELECT SP_CODE_SQ_PK          AS ID_SPE,
       SP_NOM,
       TU.PSO_TYP_UNIT_PK     AS ID_TY_UNIT,
       TU.PSO_TYP_UNIT_NAME   AS TYP_NAME,
       UN.PSO_UNIT_PK         AS ID_UNIT,
       PSO.PSO_POS_V_MAX      AS QTE_MAX,
       UN.PSO_UNIT_NAME_SH    AS UNIT_NAME,
       PSO.PSO_POS_V_PDS      AS nb_pds,
       uPds.PSO_UNIT_NAME_SH  AS un_pds_name,
       PSO.PSO_POS_V_AREA     AS nb_surface,
       uArea.PSO_UNIT_NAME_SH AS un_surface_name,
       BI.PSO_TYP_UNIT_PK     AS ID_UN_ADM,
       PSO.PSO_VAL_UNIT_ADM   AS NB_ADM,
       uAdm.PSO_UNIT_NAME_SH  AS UN_ADM_NAME
FROM  SP_SPECIALITE
         JOIN  PSO_GSP_POSO PSO
              ON (PSO_GSP_CODE_SQ_PK = SP_GSP_CODE_FK
                  AND PSO_NAT_POSO_ID = 314)
         LEFT JOIN  PSO_TYPE_UNIT TU
                   ON (TU.PSO_TYP_UNIT_PK = PSO.PSO_TYP_UNIT_MAX)
         JOIN  PSO_UNIT UN
              ON (UN.PSO_UNIT_PK = PSO.PSO_UNIT_MAX)
         LEFT JOIN  PSO_TYPE_UNIT BI
                   ON (BI.PSO_TYP_UNIT_PK = PSO.PSO_TYP_UNIT_ADM)
         LEFT JOIN  PSO_UNIT uAdm
                   ON (uAdm.PSO_UNIT_PK = PSO.PSO_UNIT_ADM)
         LEFT JOIN  PSO_UNIT uPds
                   ON (uPds.PSO_UNIT_PK = PSO.PSO_UNIT_PDS)
         LEFT JOIN  PSO_UNIT uArea
                   ON (uArea.PSO_UNIT_PK = PSO.PSO_UNIT_AREA)
         LEFT JOIN  PSO_TYPE_POSO NAT
                   ON (NAT.PSO_NAT_POSO_ID = PSO.PSO_POS_V_MAX)
WHERE (SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID ||
                                '''''','''','''')))'';
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API Indique pour une liste de spécialités ou UCD, si cette dernière est d'origine BIOLOGIQUE.
-- 2020-04-28 : From GSP
-- EXEMPLE: SELECT  ORIGINEBIO ('4561,9080118');
CREATE
OR REPLACE FUNCTION ORIGINEBIO(VARCHAR) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        CURRET REFCURSOR;
    BEGIN
        OPEN CURRET FOR EXECUTE ''
              SELECT SP.SP_CODE_SQ_PK                                      AS ID_SPE,
                     SP.SP_CIPUCD                                          AS UCD,
                     SP.SP_NOM,
                     SP.SP_CATC_CODE_FK                                    AS CATC,
                     CATC_NOMF                                             AS CATC_NAME,
                     CASE WHEN GSPTYPE_FK_PK IS NULL THEN ''''N'''' ELSE ''''O'''' END AS IS_BIO
              FROM SP_SPECIALITE SP
                       JOIN GSP_GENERIQUE_SPECIALITE ON GSP_CODE_SQ_PK = SP_GSP_CODE_FK
                       LEFT JOIN gsptype_gsp_type ON SP_GSP_CODE_FK = GSPTYPE_FK_PK AND TYPE_CODE_FK_PK = 70
                       LEFT JOIN CATC_CLASSEATC ON CATC_CODE_PK = SP.SP_CATC_CODE_FK
              WHERE SP_CDF_SLAB_CODE_FK <> 7
                AND (SP.SP_CODE_SQ_PK IN ('' || LISTID ||
                                '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')))
'';
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API retourne le texte d'une interaction
-- DROP FUNCTION GET_THE_GTIAM_TXT(VARCHAR);
CREATE
OR REPLACE FUNCTION thesorimed.GET_THE_GTIAM_TXT(VARCHAR) RETURNS REFCURSOR AS
'
    DECLARE
        LISTFIC ALIAS FOR $1;
        curRet REFCURSOR;
    BEGIN
        OPEN curRet FOR EXECUTE ''SELECT FIT_CODE_SQ_PK AS NOFIT, FIT_TEXTE AS TEXTE, FIT_DATECR AS DATE_TXT
FROM FIT_FICHEINTERAC
WHERE FIT_CODE_SQ_PK IN ('' || LISTFIC || '')
ORDER BY NOFIT'';
        RETURN curRet;
    END;

' LANGUAGE plpgsql;

-- API RESERVE HOSPITALIERE AU CIP
-- EXEMPLE: SELECT GET_THE_RESERVE_HOSP_CIP ('''3400930916292'',''3400955496182''', 1);
-- 2020-04-27 : From GSP
CREATE
OR REPLACE FUNCTION GET_THE_RESERVE_HOSP_CIP(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CODE_SQ_PK AS ID_SPE,
                   SP.SP_CIPUCD     AS SP_CIPUCD,
                   PRE.PRE_CODE_PK  AS CIP,
                   SP.SP_NOM        AS SP_NOM,
                   ''''RH''''             AS RESERVE_HOSPITALIERE,
                   spcpd_typage AS TYPAGE
            FROM SP_SPECIALITE SP
                     JOIN PRE_PRESENTATION PRE ON (PRE.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK)
                     JOIN VSPCPD_SPE_CDT_PRESCR on SP_CODE_SQ_PK = SPCPD_SP_CODE_FK_PK AND SPCPD_CDF_STP_CODE_FK_PK = ''''S7''''
            WHERE SP_CDF_SLAB_CODE_FK <> 7
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
SELECT SP.SP_CODE_SQ_PK AS ID_SPE,
                   SP.SP_CIPUCD     AS SP_CIPUCD,
                   PRE.PRE_CODE_PK  AS CIP,
                   SP.SP_NOM        AS SP_NOM,
                   CASE
                       WHEN SPCPD_SP_CODE_FK_PK IS NULL
                           THEN ''''NON''''
                       ELSE ''''RH''''
                       END          AS RESERVE_HOSPITALIERE,
                       spcpd_typage AS TYPAGE
            FROM SP_SPECIALITE SP
                     JOIN PRE_PRESENTATION PRE ON (PRE.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK)
                     LEFT JOIN VSPCPD_SPE_CDT_PRESCR
                               ON SP_CODE_SQ_PK = SPCPD_SP_CODE_FK_PK
                                   AND SPCPD_CDF_STP_CODE_FK_PK = ''''S7''''
            WHERE SP_CDF_SLAB_CODE_FK <> 7
              AND PRE.PRE_CODE_PK IN ('' || LISTID || '')
            ORDER BY RESERVE_HOSPITALIERE, SP.SP_NOM
            '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- Retourne le statut d'une présentation
-- CODECIP = '3400930916292'
CREATE
OR REPLACE FUNCTION GET_THE_PRE_STATUT(VARCHAR) RETURNS REFCURSOR AS
'
    DECLARE
        CODECIP ALIAS FOR $1;
        curRet REFCURSOR;
    BEGIN
        OPEN curRet FOR SELECT ''1.'' || PRESTP_NUMORD                      AS TYPE,
                               CDF_NOM                                      AS REF_OFF,
                               ''''                                         AS IDENT,
                               TO_CHAR(PRESTP_DATE_AFSSAPS, ''DD/MM/YYYY'') AS DAT_REF_OFF,
                               NULL                                         AS DAT_REVISION
                        FROM PRE_PRESENTATION,
                             PRESTP_PRE_STP,
                             CDF_CODIF
                        WHERE PRE_CODE_PK = CODECIP
                          AND PRESTP_PRE_CODE_FK_PK = PRE_CODE_PK
                          AND PRESTP_CDF_STP_CODE_FK_PK = CDF_CODE_PK
                          AND CDF_NUMERO_PK = ''14''
                        UNION
                        SELECT ''2.''            AS TYPE,
                               CDF_NOM           AS REF_OFF,
                               PRESTC_CODE_IDENT AS IDENT,
                               NULL              AS DAT_REF_OFF,
                               NULL              AS DAT_REVISION
                        FROM PRE_PRESENTATION,
                             PRESTC_STATUTCOMP_PRESENT,
                             CDF_CODIF
                        WHERE PRE_CODE_PK = CODECIP
                          AND PRESTC_PRE_CODE_FK_PK = PRE_CODE_PK
                          AND PRESTC_CDF_STCOMP_CODE_FK_PK = CDF_CODE_PK
                          AND CDF_NUMERO_PK = ''14''
                        UNION
                        SELECT ''3.''                                    AS TYPE,
                               CDF_NOM                                   AS REF_OFF,
                               ''''                                      AS IDENT,
                               TO_CHAR(SPAFS_DATE_PK, ''DD/MM/YYYY'')    AS DAT_REF_OFF,
                               TO_CHAR(SPAFS_DATE_REVIS, ''DD/MM/YYYY'') AS DAT_REVISION
                        FROM PRE_PRESENTATION,
                             SP_SPECIALITE,
                             SPAFS_SPECIALITE_AFSSAPS,
                             CDF_CODIF
                        WHERE PRE_CODE_PK = CODECIP
                          AND SP_CODE_SQ_PK = PRE_SP_CODE_FK
                          AND SPAFS_SP_CODE_FK_PK = SP_CODE_SQ_PK
                          AND SPAFS_DATE_PK = (SELECT MAX(SPAFS_DATE_PK)
                                               FROM SPAFS_SPECIALITE_AFSSAPS
                                               WHERE SPAFS_SP_CODE_FK_PK = SP_CODE_SQ_PK
                                                 AND SPAFS_DATE_REVIS IS NULL)
                          AND CDF_CODE_PK = SPAFS_CDF_CODE_DOC_FK_PK
                          AND CDF_NUMERO_PK = ''25''
                        ORDER BY TYPE;
        RETURN curRet;
    END;

' LANGUAGE plpgsql;


-- API Labo Titulaire
-- EXEMPLE LISTID := '4561,22844' et TYPID := 1
CREATE
OR REPLACE FUNCTION GET_THE_LABO_TIT_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CODE_SQ_PK,
                       SP.SP_NOM,
                       LSP_CODE_SQ_PK AS CODE_LABO,
                       LSP_LIBELLE    AS NOM_LABO
                FROM SP_SPECIALITE SP
                         JOIN SPLSP_SPECIALITE_LABO
                              ON SPLSP_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
                         JOIN LABO_SP
                              ON LSP_CODE_SQ_PK = SPLSP_LSP_CODE_FK_PK
                WHERE SP_CDF_SLAB_CODE_FK NOT IN (''''7'''', ''''3'''')
                ORDER BY SP_NOM'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP.SP_CODE_SQ_PK,
                       SP.SP_NOM,
                       LSP_CODE_SQ_PK AS CODE_LABO,
                       LSP_LIBELLE    AS NOM_LABO
                FROM SP_SPECIALITE SP
                         JOIN SPLSP_SPECIALITE_LABO
                              ON SPLSP_SP_CODE_FK_PK = SP.SP_CODE_SQ_PK
                         JOIN LABO_SP
                              ON LSP_CODE_SQ_PK = SPLSP_LSP_CODE_FK_PK
                WHERE SP_CDF_SLAB_CODE_FK NOT IN (''''7'''', ''''3'''')
        AND (SP.SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        ORDER BY SP_NOM
	'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;


-- API GET_THE_SPE_NMVS
-- EXEMPLE : SELECT GET_THE_SPE_NMVS('4561,3400921604696',1);
CREATE
OR REPLACE FUNCTION GET_THE_SPE_NMVS(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT pre_code_pk              AS cip13,
                                sp_cipucd_long           AS ucd13,
                                sp_cipucd                AS ucd,
                                sp_code_sq_pk            AS idspe,
                                replace(sp_nom, ''''#'''', '''''''') AS sp_nom,
                                sp_catc_code_fk          AS catc,
                                fo.cdf_nom               AS forme,
                                lsp.LSP_LIBELLE          AS labo,
                                pre_natucd_contenu       AS nb_ucd,
                                is_nmvs(pre_code_pk)     AS serie
                FROM sp_specialite
                         JOIN pre_presentation
                              ON pre_sp_code_fk = sp_code_sq_pk
                         JOIN spfo_specialite_forme
                              ON spfo_sp_code_fk_pk = sp_code_sq_pk
                         JOIN cdf_codif fo
                              ON fo.cdf_numero_pk = ''''06''''
                                  AND fo.cdf_code_pk = spfo_cdf_fo_code_fk_pk
                         JOIN SPLSP_SPECIALITE_LABO
                              ON SPLSP_SP_CODE_FK_PK = sp_code_sq_pk
                         JOIN LABO_SP lsp
                              ON lsp.LSP_CODE_SQ_PK = SPLSP_LSP_CODE_FK_PK
                WHERE sp_cdf_slab_code_fk != ''''7''''
                ORDER BY serie,
                         sp_nom'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT pre_code_pk              AS cip13,
                                sp_cipucd_long           AS ucd13,
                                sp_cipucd                AS ucd,
                                sp_code_sq_pk            AS idspe,
                                replace(sp_nom, ''''#'''', '''''''') AS sp_nom,
                                sp_catc_code_fk          AS catc,
                                fo.cdf_nom               AS forme,
                                lsp.LSP_LIBELLE          AS labo,
                                pre_natucd_contenu       AS nb_ucd,
                                is_nmvs(pre_code_pk)     AS serie
                FROM sp_specialite
                         JOIN pre_presentation
                              ON pre_sp_code_fk = sp_code_sq_pk
                         JOIN spfo_specialite_forme
                              ON spfo_sp_code_fk_pk = sp_code_sq_pk
                         JOIN cdf_codif fo
                              ON fo.cdf_numero_pk = ''''06''''
                                  AND fo.cdf_code_pk = spfo_cdf_fo_code_fk_pk
                         JOIN SPLSP_SPECIALITE_LABO
                              ON SPLSP_SP_CODE_FK_PK = sp_code_sq_pk
                         JOIN LABO_SP lsp
                              ON lsp.LSP_CODE_SQ_PK = SPLSP_LSP_CODE_FK_PK
                WHERE sp_cdf_slab_code_fk != ''''7''''
        AND (cast(pre_code_pk as text) = ANY (string_to_array('''''' || LISTID ||
                                    '''''','''','''')) OR cast(pre_sp_code_fk as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        ORDER BY serie, sp_nom
	'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API GET_THE_DUR_MAX_SPE
-- EXEMPLE : GET_THE_DUR_MAX_SPE ('19197,9196246',1);
CREATE
OR REPLACE FUNCTION GET_THE_DUR_MAX_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP_CIPUCD as UCD, SP_CIPUCD_LONG as UCD13, PRE_CODE_PK as CIP13, SP_NOM, DMTGSP_DUREE AS DUREE,PSO_UNIT_NAME_SH AS NATURE_UNITE, DMTGSP_COMMENTAIRE AS COMMENTAIRE
		from DMTGSP_DUREES_MAX_TRAITEMENT
		join GSP_GENERIQUE_SPECIALITE on (GSP_CODE_SQ_PK = DMTGSP_GSP_CODE_FK_PK)
		join PSO_UNIT on (PSO_UNIT_PK = DMTGSP_UNITE_FK)
		join SP_SPECIALITE on (SP_GSP_CODE_FK = DMTGSP_GSP_CODE_FK_PK)
		join PRE_PRESENTATION on (PRE_SP_CODE_FK =SP_CODE_SQ_PK)
		order BY SP_NOM'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT SP_CIPUCD as UCD, SP_CIPUCD_LONG as UCD13, PRE_CODE_PK as CIP13, SP_NOM, DMTGSP_DUREE AS DUREE,PSO_UNIT_NAME_SH AS NATURE_UNITE, DMTGSP_COMMENTAIRE AS COMMENTAIRE
		from DMTGSP_DUREES_MAX_TRAITEMENT
		join GSP_GENERIQUE_SPECIALITE on (GSP_CODE_SQ_PK = DMTGSP_GSP_CODE_FK_PK)
		join PSO_UNIT on (PSO_UNIT_PK = DMTGSP_UNITE_FK)
		join SP_SPECIALITE on (SP_GSP_CODE_FK = DMTGSP_GSP_CODE_FK_PK)
		join PRE_PRESENTATION on (PRE_SP_CODE_FK =SP_CODE_SQ_PK)
        where (SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        ORDER BY sp_nom
	'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API GET_THE_AGE_MIN_SPE
-- EXEMPLE : SELECT GET_THE_AGE_MIN_SPE ('19197,9328498',1);
CREATE
OR REPLACE FUNCTION GET_THE_AGE_MIN_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''select SP_CIPUCD as UCD, SP_CIPUCD_LONG as UCD13, PRE_CODE_PK as CIP13, SP_NOM, BAGSP_AGE_MIN AS UNITE_AGE,
		case
		    when BAGSP_AGE_MIN is null then '''''''' ELSE U1.PSO_UNIT_NAME_SH END AS UNITE_AGE_NATURE,
		BAGSP_POID_MIN AS UNITE_POIDS,
		case
		    when BAGSP_POID_MIN is null then '''''''' ELSE U2.PSO_UNIT_NAME_SH END AS UNITE_POID_NATURE
		from BAGSP_BORNES_AGE
		left join GSP_GENERIQUE_SPECIALITE on (GSP_CODE_SQ_PK = BAGSP_GSP_CODE_FK_PK)
		left join PSO_UNIT U1 on (U1.PSO_UNIT_PK = BAGSP_AGE_MIN_UNITE_FK)
		left join PSO_UNIT U2 on (U2.PSO_UNIT_PK = BAGSP_POID_MIN_UNITE_FK )
		join SP_SPECIALITE on (SP_GSP_CODE_FK = BAGSP_GSP_CODE_FK_PK)
		join PRE_PRESENTATION on (PRE_SP_CODE_FK = SP_CODE_SQ_PK)
		order BY SP_NOM'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''select SP_CIPUCD as UCD, SP_CIPUCD_LONG as UCD13, PRE_CODE_PK as CIP13, SP_NOM, BAGSP_AGE_MIN AS UNITE_AGE,
		case
		    when BAGSP_AGE_MIN is null then '''' ELSE U1.PSO_UNIT_NAME_SH END AS UNITE_AGE_NATURE,
		BAGSP_POID_MIN AS UNITE_POIDS,
		case
		    when BAGSP_POID_MIN is null then '''' ELSE U2.PSO_UNIT_NAME_SH END AS UNITE_POID_NATURE
		from BAGSP_BORNES_AGE
		left join GSP_GENERIQUE_SPECIALITE on (GSP_CODE_SQ_PK = BAGSP_GSP_CODE_FK_PK)
		left join PSO_UNIT U1 on (U1.PSO_UNIT_PK = BAGSP_AGE_MIN_UNITE_FK)
		left join PSO_UNIT U2 on (U2.PSO_UNIT_PK = BAGSP_POID_MIN_UNITE_FK )
		join SP_SPECIALITE on (SP_GSP_CODE_FK = BAGSP_GSP_CODE_FK_PK)
		join PRE_PRESENTATION on (PRE_SP_CODE_FK = SP_CODE_SQ_PK)
        where (SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID || '''''','''','''')))
        ORDER BY sp_nom
	'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API GET_THE_GSP_INTEROP : Interoperabilité MEDICABASE
-- EXEMPLE SELECT  GET_THE_GSP_INTEROP('72, 24', 1)
CREATE
OR REPLACE FUNCTION GET_THE_GSP_INTEROP(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE
                ''SELECT GSP_CODE_SQ_PK as GSP_CODE, GSP_MV_LIBELLE as CODE_INTEROP
        FROM GSP_MV_INTEROP
        order by GSP_CODE'';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE
                        ''SELECT GSP_CODE_SQ_PK as GSP_CODE, GSP_MV_LIBELLE as CODE_INTEROP
        FROM GSP_MV_INTEROP
        WHERE GSP_CODE_SQ_PK IN ('' || LISTID || '')
        order by GSP_CODE'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API PSO MAXIMUM : Remplace GET_THE_PSO_MAX_BY_SPE
-- EXEMPLE ID : '4519,3671,8932,22169,427,5762,11898' POUR ADULTE ET '8662,6519,6199,11965,4245,11217' POUR ENFANT
--
-- REMPLACE   : 2019-06-24 => GET_THE_PSO_MAX_BY_SPE
-- ====================================================================================

-- DROP FUNCTION GET_THE_PSO_MAX_BY_SPE(VARCHAR,NUMERIC);
CREATE
OR REPLACE FUNCTION GET_THE_PSO_MAX_BY_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN

        IF TYPID = 0 THEN
            --
            -- GSP
            --
            OPEN CURRET FOR EXECUTE ''
SELECT DISTINCT SP.SP_CODE_SQ_PK                        AS SP_CODE,
                                SP.SP_NOM                               AS SP_NOM,
                                CASE
                                    WHEN NAT.PSO_NAT_AGE_B_MIN IS NOT NULL OR NAT.PSO_NAT_AGE_B_MAX IS NOT NULL THEN ''''AGE ''''
                                    ELSE '''''''' END ||
                                CASE
                                    WHEN NAT.PSO_NAT_PDS_B_MIN IS NOT NULL OR NAT.PSO_NAT_PDS_B_MAX IS NOT NULL THEN ''''POIDS ''''
                                    ELSE '''''''' END ||
                                CASE
                                    WHEN NAT.PSO_NAT_AREA_B_MIN IS NOT NULL OR NAT.PSO_NAT_AREA_B_MAX IS NOT NULL THEN ''''SURFACE''''
                                    ELSE '''''''' END                         AS CRITERE,
                                NAT.PSO_NAT_POSO_NAME                   AS POSO_NAME,
                                ''''MAX''''                             AS MIN_MAX,
                                NULL                                    AS NATURE,
                                NULL                                    AS BORNE_MIN,
                                NULL                                    AS CD_B_MIN,
                                ''''NA''''                                    AS UNIT_MIN,
                                PSO.PSO_POS_V_MAX                       AS BORNE_MAX,
                                PSO.PSO_UNIT_MAX                        AS CD_B_MAX,
                                COALESCE(V_MAX.PSO_UNIT_NAME_SH, ''''NA'''')  AS UNIT_MAX,
                                PSO.PSO_POS_V_PDS                       AS PAR_MASSE,
                                PSO.PSO_UNIT_PDS                        AS CD_PDS,
                                COALESCE(U_PDS.PSO_UNIT_NAME_SH, ''''NA'''')  AS UNIT_PDS,
                                PSO.PSO_VAL_UNIT_ADM                    AS PAR_ADM,
                                PSO.PSO_UNIT_ADM                        AS CD_ADM,
                                COALESCE(U_ADM.PSO_UNIT_NAME_SH, ''''NA'''')  AS UNIT_ADM,
                                PSO.PSO_POS_V_AREA                      AS PAR_M2,
                                PSO.PSO_UNIT_AREA                       AS CD_AREA,
                                COALESCE(U_AREA.PSO_UNIT_NAME_SH, ''''NA'''') AS UNIT_AREA,
                                NULL                                    AS INFO,
                                NULL                                    AS B_MIN,
                                NULL                                    AS B_MAX,
                                NAT.PSO_NAT_AGE_B_MIN                   AS CRITERE_AGE_MIN,
                                NAT.PSO_NAT_AGE_UNIT_MIN                AS CRITERE_AGE_UNIT_MIN,
                                ageMin.PSO_UNIT_NAME                    AS CRIT_AGE_UNIT_MIN_STR,
                                NAT.PSO_NAT_AGE_B_MAX                   AS CRITERE_AGE_MAX,
                                NAT.PSO_NAT_AGE_UNIT_MAX                AS CRITERE_AGE_UNIT_MAX,
                                ageMax.PSO_UNIT_NAME                    AS CRIT_AGE_UNIT_MAX_STR,
                                NAT.PSO_NAT_PDS_B_MIN                   AS CRITERE_PDS_MIN,
                                NAT.PSO_NAT_PDS_UNIT_MIN                AS CRITERE_PDS_UNIT_MIN,
                                pdsMin.PSO_UNIT_NAME                    AS CRIT_PDS_UNIT_MIN_STR,
                                NAT.PSO_NAT_PDS_B_MAX                   AS CRITERE_PDS_MAX,
                                NAT.PSO_NAT_PDS_UNIT_MAX                AS CRITERE_PDS_UNIT_MAX,
                                pdsMax.PSO_UNIT_NAME                    AS CRIT_PDS_UNIT_MAX_STR,
                                NAT.PSO_NAT_AREA_B_MIN                  AS CRITERE_AREA_MIN,
                                NAT.PSO_NAT_AREA_UNIT_MIN               AS CRITERE_AREA_UNIT_MIN,
                                areaMin.PSO_UNIT_NAME                   AS CRIT_AREA_UNIT_MIN_STR,
                                NAT.PSO_NAT_AREA_B_MAX                  AS CRITERE_AREA_MAX,
                                NAT.PSO_NAT_AREA_UNIT_MAX               AS CRITERE_AREA_UNIT_MAX,
                                areaMax.PSO_UNIT_NAME                   AS CRIT_AREA_UNIT_MAX_STR
                FROM SP_SPECIALITE SP
                         JOIN PSO_GSP_POSO PSO
                              ON PSO.PSO_GSP_CODE_SQ_PK = SP.SP_GSP_CODE_FK
                                  AND (PSO.PSO_POS_V_MIN is NULL OR PSO.PSO_POS_V_MAX is NOT NULL)
                         JOIN PSO_TYPE_POSO NAT
                              ON PSO.PSO_NAT_POSO_ID = NAT.PSO_NAT_POSO_ID
                    -- BORNE MAX
                         LEFT JOIN PSO_UNIT V_MAX ON (V_MAX.PSO_UNIT_PK = PSO_UNIT_MAX)
                    -- IND POIDS
                         LEFT JOIN PSO_UNIT U_PDS ON (U_PDS.PSO_UNIT_PK = PSO_UNIT_PDS)
                    -- IND ADMINISTRATION
                         LEFT JOIN PSO_UNIT U_ADM ON (U_ADM.PSO_UNIT_PK = PSO_UNIT_ADM)
                    -- IND SURFACE C.
                         LEFT JOIN PSO_UNIT U_AREA ON (U_AREA.PSO_UNIT_PK = PSO_UNIT_AREA)
                    -- UNIT age MIN
                         LEFT JOIN PSO_UNIT ageMin
                                   ON ageMin.PSO_UNIT_PK = NAT.PSO_NAT_AGE_UNIT_MIN
                    -- UNIT age MAX
                         LEFT JOIN PSO_UNIT ageMax
                                   ON ageMax.PSO_UNIT_PK = NAT.PSO_NAT_AGE_UNIT_MAX
                    -- UNIT pds MIN
                         LEFT JOIN PSO_UNIT pdsMin
                                   ON pdsMin.PSO_UNIT_PK = NAT.PSO_NAT_PDS_UNIT_MIN
                    -- UNIT pds MAX
                         LEFT JOIN PSO_UNIT pdsMax
                                   ON pdsMax.PSO_UNIT_PK = NAT.PSO_NAT_PDS_UNIT_MAX
                    -- UNIT area MIN
                         LEFT JOIN PSO_UNIT areaMin
                                   ON areaMin.PSO_UNIT_PK = NAT.PSO_NAT_AREA_UNIT_MIN
                    -- UNIT area MAX
                         LEFT JOIN PSO_UNIT areaMax
                                   ON areaMax.PSO_UNIT_PK = NAT.PSO_NAT_AREA_UNIT_MAX
                ORDER BY MIN_MAX DESC, SP_CODE, CRITERE, NATURE
                '';

        END IF;

        IF TYPID = 1 THEN
            --
            -- GSP
            --
            OPEN CURRET FOR EXECUTE ''
SELECT DISTINCT SP.SP_CODE_SQ_PK                        AS SP_CODE,
                                    SP.SP_NOM                               AS SP_NOM,
                                    CASE
                                        WHEN NAT.PSO_NAT_AGE_B_MIN IS NOT NULL OR NAT.PSO_NAT_AGE_B_MAX IS NOT NULL THEN ''''AGE ''''
                                        ELSE '''''''' END ||
                                    CASE
                                        WHEN NAT.PSO_NAT_PDS_B_MIN IS NOT NULL OR NAT.PSO_NAT_PDS_B_MAX IS NOT NULL THEN ''''POIDS ''''
                                        ELSE '''''''' END ||
                                    CASE
                                        WHEN NAT.PSO_NAT_AREA_B_MIN IS NOT NULL OR NAT.PSO_NAT_AREA_B_MAX IS NOT NULL THEN ''''SURFACE''''
                                        ELSE '''''''' END                         AS CRITERE,
                                    NAT.PSO_NAT_POSO_NAME                   AS POSO_NAME,
                                    ''''MAX''''                             AS MIN_MAX,
                                    NULL                                    AS NATURE,
                                    NULL                                    AS BORNE_MIN,
                                    NULL                                    AS CD_B_MIN,
                                    ''''NA''''                                    AS UNIT_MIN,
                                    PSO.PSO_POS_V_MAX                       AS BORNE_MAX,
                                    PSO.PSO_UNIT_MAX                        AS CD_B_MAX,
                                    COALESCE(V_MAX.PSO_UNIT_NAME_SH, ''''NA'''')  AS UNIT_MAX,
                                    PSO.PSO_POS_V_PDS                       AS PAR_MASSE,
                                    PSO.PSO_UNIT_PDS                        AS CD_PDS,
                                    COALESCE(U_PDS.PSO_UNIT_NAME_SH, ''''NA'''')  AS UNIT_PDS,
                                    PSO.PSO_VAL_UNIT_ADM                    AS PAR_ADM,
                                    PSO.PSO_UNIT_ADM                        AS CD_ADM,
                                    COALESCE(U_ADM.PSO_UNIT_NAME_SH, ''''NA'''')  AS UNIT_ADM,
                                    PSO.PSO_POS_V_AREA                      AS PAR_M2,
                                    PSO.PSO_UNIT_AREA                       AS CD_AREA,
                                    COALESCE(U_AREA.PSO_UNIT_NAME_SH, ''''NA'''') AS UNIT_AREA,
                                    NULL                                    AS INFO,
                                    NULL                                    AS B_MIN,
                                    NULL                                    AS B_MAX,
                                    NAT.PSO_NAT_AGE_B_MIN                   AS CRITERE_AGE_MIN,
                                    NAT.PSO_NAT_AGE_UNIT_MIN                AS CRITERE_AGE_UNIT_MIN,
                                    ageMin.PSO_UNIT_NAME                    AS CRIT_AGE_UNIT_MIN_STR,
                                    NAT.PSO_NAT_AGE_B_MAX                   AS CRITERE_AGE_MAX,
                                    NAT.PSO_NAT_AGE_UNIT_MAX                AS CRITERE_AGE_UNIT_MAX,
                                    ageMax.PSO_UNIT_NAME                    AS CRIT_AGE_UNIT_MAX_STR,
                                    NAT.PSO_NAT_PDS_B_MIN                   AS CRITERE_PDS_MIN,
                                    NAT.PSO_NAT_PDS_UNIT_MIN                AS CRITERE_PDS_UNIT_MIN,
                                    pdsMin.PSO_UNIT_NAME                    AS CRIT_PDS_UNIT_MIN_STR,
                                    NAT.PSO_NAT_PDS_B_MAX                   AS CRITERE_PDS_MAX,
                                    NAT.PSO_NAT_PDS_UNIT_MAX                AS CRITERE_PDS_UNIT_MAX,
                                    pdsMax.PSO_UNIT_NAME                    AS CRIT_PDS_UNIT_MAX_STR,
                                    NAT.PSO_NAT_AREA_B_MIN                  AS CRITERE_AREA_MIN,
                                    NAT.PSO_NAT_AREA_UNIT_MIN               AS CRITERE_AREA_UNIT_MIN,
                                    areaMin.PSO_UNIT_NAME                   AS CRIT_AREA_UNIT_MIN_STR,
                                    NAT.PSO_NAT_AREA_B_MAX                  AS CRITERE_AREA_MAX,
                                    NAT.PSO_NAT_AREA_UNIT_MAX               AS CRITERE_AREA_UNIT_MAX,
                                    areaMax.PSO_UNIT_NAME                   AS CRIT_AREA_UNIT_MAX_STR
                    FROM SP_SPECIALITE SP
                             JOIN PSO_GSP_POSO PSO
                                  ON PSO.PSO_GSP_CODE_SQ_PK = SP.SP_GSP_CODE_FK
                                      AND (PSO.PSO_POS_V_MIN is NULL OR PSO.PSO_POS_V_MAX is NOT NULL)
                             JOIN PSO_TYPE_POSO NAT
                                  ON PSO.PSO_NAT_POSO_ID = NAT.PSO_NAT_POSO_ID
                        -- BORNE MAX
                             LEFT JOIN PSO_UNIT V_MAX ON (V_MAX.PSO_UNIT_PK = PSO_UNIT_MAX)
                        -- IND POIDS
                             LEFT JOIN PSO_UNIT U_PDS ON (U_PDS.PSO_UNIT_PK = PSO_UNIT_PDS)
                        -- IND ADMINISTRATION
                             LEFT JOIN PSO_UNIT U_ADM ON (U_ADM.PSO_UNIT_PK = PSO_UNIT_ADM)
                        -- IND SURFACE C.
                             LEFT JOIN PSO_UNIT U_AREA ON (U_AREA.PSO_UNIT_PK = PSO_UNIT_AREA)
                        -- UNIT age MIN
                             LEFT JOIN PSO_UNIT ageMin
                                       ON ageMin.PSO_UNIT_PK = NAT.PSO_NAT_AGE_UNIT_MIN
                        -- UNIT age MAX
                             LEFT JOIN PSO_UNIT ageMax
                                       ON ageMax.PSO_UNIT_PK = NAT.PSO_NAT_AGE_UNIT_MAX
                        -- UNIT pds MIN
                             LEFT JOIN PSO_UNIT pdsMin
                                       ON pdsMin.PSO_UNIT_PK = NAT.PSO_NAT_PDS_UNIT_MIN
                        -- UNIT pds MAX
                             LEFT JOIN PSO_UNIT pdsMax
                                       ON pdsMax.PSO_UNIT_PK = NAT.PSO_NAT_PDS_UNIT_MAX
                        -- UNIT area MIN
                             LEFT JOIN PSO_UNIT areaMin
                                       ON areaMin.PSO_UNIT_PK = NAT.PSO_NAT_AREA_UNIT_MIN
                        -- UNIT area MAX
                             LEFT JOIN PSO_UNIT areaMax
                                       ON areaMax.PSO_UNIT_PK = NAT.PSO_NAT_AREA_UNIT_MAX
                    WHERE SP.SP_CODE_SQ_PK IN ('' || LISTID || '')
                ORDER BY SP_CODE, CRITERE, NATURE, MIN_MAX
'';

        END IF;

        IF TYPID = 2 THEN
            --
            -- GSP
            --
            OPEN CURRET FOR EXECUTE ''
SELECT DISTINCT SP.SP_GSP_CODE_FK AS CODE_GSP,
							get_lb_gsp(SP.SP_GSP_CODE_FK) AS NOM_GSP,
                                    CASE
                                        WHEN NAT.PSO_NAT_AGE_B_MIN IS NOT NULL OR NAT.PSO_NAT_AGE_B_MAX IS NOT NULL THEN ''''AGE ''''
                                        ELSE '''''''' END ||
                                    CASE
                                        WHEN NAT.PSO_NAT_PDS_B_MIN IS NOT NULL OR NAT.PSO_NAT_PDS_B_MAX IS NOT NULL THEN ''''POIDS ''''
                                        ELSE '''''''' END ||
                                    CASE
                                        WHEN NAT.PSO_NAT_AREA_B_MIN IS NOT NULL OR NAT.PSO_NAT_AREA_B_MAX IS NOT NULL THEN ''''SURFACE''''
                                        ELSE '''''''' END                         AS CRITERE,
                                    NAT.PSO_NAT_POSO_NAME                   AS POSO_NAME,
                                    ''''MAX''''                             AS MIN_MAX,
                                    NULL                                    AS NATURE,
                                    NULL                                    AS BORNE_MIN,
                                    NULL                                    AS CD_B_MIN,
                                    ''''NA''''                                    AS UNIT_MIN,
                                    PSO.PSO_POS_V_MAX                       AS BORNE_MAX,
                                    PSO.PSO_UNIT_MAX                        AS CD_B_MAX,
                                    COALESCE(V_MAX.PSO_UNIT_NAME_SH, ''''NA'''')  AS UNIT_MAX,
                                    PSO.PSO_POS_V_PDS                       AS PAR_MASSE,
                                    PSO.PSO_UNIT_PDS                        AS CD_PDS,
                                    COALESCE(U_PDS.PSO_UNIT_NAME_SH, ''''NA'''')  AS UNIT_PDS,
                                    PSO.PSO_VAL_UNIT_ADM                    AS PAR_ADM,
                                    PSO.PSO_UNIT_ADM                        AS CD_ADM,
                                    COALESCE(U_ADM.PSO_UNIT_NAME_SH, ''''NA'''')  AS UNIT_ADM,
                                    PSO.PSO_POS_V_AREA                      AS PAR_M2,
                                    PSO.PSO_UNIT_AREA                       AS CD_AREA,
                                    COALESCE(U_AREA.PSO_UNIT_NAME_SH, ''''NA'''') AS UNIT_AREA,
                                    NULL                                    AS INFO,
                                    NULL                                    AS B_MIN,
                                    NULL                                    AS B_MAX,
                                    NAT.PSO_NAT_AGE_B_MIN                   AS CRITERE_AGE_MIN,
                                    NAT.PSO_NAT_AGE_UNIT_MIN                AS CRITERE_AGE_UNIT_MIN,
                                    ageMin.PSO_UNIT_NAME                    AS CRIT_AGE_UNIT_MIN_STR,
                                    NAT.PSO_NAT_AGE_B_MAX                   AS CRITERE_AGE_MAX,
                                    NAT.PSO_NAT_AGE_UNIT_MAX                AS CRITERE_AGE_UNIT_MAX,
                                    ageMax.PSO_UNIT_NAME                    AS CRIT_AGE_UNIT_MAX_STR,
                                    NAT.PSO_NAT_PDS_B_MIN                   AS CRITERE_PDS_MIN,
                                    NAT.PSO_NAT_PDS_UNIT_MIN                AS CRITERE_PDS_UNIT_MIN,
                                    pdsMin.PSO_UNIT_NAME                    AS CRIT_PDS_UNIT_MIN_STR,
                                    NAT.PSO_NAT_PDS_B_MAX                   AS CRITERE_PDS_MAX,
                                    NAT.PSO_NAT_PDS_UNIT_MAX                AS CRITERE_PDS_UNIT_MAX,
                                    pdsMax.PSO_UNIT_NAME                    AS CRIT_PDS_UNIT_MAX_STR,
                                    NAT.PSO_NAT_AREA_B_MIN                  AS CRITERE_AREA_MIN,
                                    NAT.PSO_NAT_AREA_UNIT_MIN               AS CRITERE_AREA_UNIT_MIN,
                                    areaMin.PSO_UNIT_NAME                   AS CRIT_AREA_UNIT_MIN_STR,
                                    NAT.PSO_NAT_AREA_B_MAX                  AS CRITERE_AREA_MAX,
                                    NAT.PSO_NAT_AREA_UNIT_MAX               AS CRITERE_AREA_UNIT_MAX,
                                    areaMax.PSO_UNIT_NAME                   AS CRIT_AREA_UNIT_MAX_STR
                    FROM SP_SPECIALITE SP
                             JOIN PSO_GSP_POSO PSO
                                  ON PSO.PSO_GSP_CODE_SQ_PK = SP.SP_GSP_CODE_FK
                                      AND (PSO.PSO_POS_V_MIN is NULL OR PSO.PSO_POS_V_MAX is NOT NULL)
                             JOIN PSO_TYPE_POSO NAT
                                  ON PSO.PSO_NAT_POSO_ID = NAT.PSO_NAT_POSO_ID
                        -- BORNE MAX
                             LEFT JOIN PSO_UNIT V_MAX ON (V_MAX.PSO_UNIT_PK = PSO_UNIT_MAX)
                        -- IND POIDS
                             LEFT JOIN PSO_UNIT U_PDS ON (U_PDS.PSO_UNIT_PK = PSO_UNIT_PDS)
                        -- IND ADMINISTRATION
                             LEFT JOIN PSO_UNIT U_ADM ON (U_ADM.PSO_UNIT_PK = PSO_UNIT_ADM)
                        -- IND SURFACE C.
                             LEFT JOIN PSO_UNIT U_AREA ON (U_AREA.PSO_UNIT_PK = PSO_UNIT_AREA)
                        -- UNIT age MIN
                             LEFT JOIN PSO_UNIT ageMin
                                       ON ageMin.PSO_UNIT_PK = NAT.PSO_NAT_AGE_UNIT_MIN
                        -- UNIT age MAX
                             LEFT JOIN PSO_UNIT ageMax
                                       ON ageMax.PSO_UNIT_PK = NAT.PSO_NAT_AGE_UNIT_MAX
                        -- UNIT pds MIN
                             LEFT JOIN PSO_UNIT pdsMin
                                       ON pdsMin.PSO_UNIT_PK = NAT.PSO_NAT_PDS_UNIT_MIN
                        -- UNIT pds MAX
                             LEFT JOIN PSO_UNIT pdsMax
                                       ON pdsMax.PSO_UNIT_PK = NAT.PSO_NAT_PDS_UNIT_MAX
                        -- UNIT area MIN
                             LEFT JOIN PSO_UNIT areaMin
                                       ON areaMin.PSO_UNIT_PK = NAT.PSO_NAT_AREA_UNIT_MIN
                        -- UNIT area MAX
                             LEFT JOIN PSO_UNIT areaMax
                                       ON areaMax.PSO_UNIT_PK = NAT.PSO_NAT_AREA_UNIT_MAX
                    WHERE SP.SP_GSP_CODE_FK IN ('' || LISTID || '')
                ORDER BY CODE_GSP, CRITERE, NATURE, MIN_MAX
'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE plpgsql;


-- API Médicaments à durée de lignePrescription restreinte par rapport au statut stupéfiant ou non
-- EXEMPLE : select GET_THE_DURE_PRESC_REST_STUP ('''26690'',''7330'',''16414''','''3400930171073'',''3400930137864'',''3400894059165''', 1);
CREATE
OR REPLACE FUNCTION GET_THE_DURE_PRESC_REST_STUP(VARCHAR, VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        LISTCIP ALIAS FOR $2;
        TYPID ALIAS FOR $3;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT pre.PRE_CODE_PK AS CIP13,
                        spe.sp_nom      AS LIBELLE,
                        cdf.CDF_NOM     AS CONDITION_PRESC_RESTREINTE,
                        spcpd_typage    AS TYPAGE
        FROM sp_specialite spe
                 JOIN VSPCPD_SPE_CDT_PRESCR spcpd
                      ON spcpd.SPCPD_SP_CODE_FK_PK = spe.SP_CODE_SQ_PK
                          AND spcpd.SPCPD_CDF_STP_CODE_FK_PK IN
                              (''''S11D'''', ''''S11F'''', ''''S11G'''', ''''S11H'''', ''''S11S'''', ''''S12C'''', ''''S153'''', ''''S24'''', ''''S27'''', ''''S46'''', ''''S47'''', ''''S50'''', ''''S96'''')
                 JOIN cdf_codif cdf
                      ON cdf.CDF_NUMERO_PK = ''''14''''
                          AND cdf.CDF_CODE_PK = spcpd.SPCPD_CDF_STP_CODE_FK_PK
                 JOIN pre_presentation pre
                      ON pre.PRE_SP_CODE_FK = spe.SP_CODE_SQ_PK
        ORDER BY LIBELLE
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
        SELECT DISTINCT pre.PRE_CODE_PK AS CIP13,
                        spe.sp_nom      AS LIBELLE,
                        cdf.CDF_NOM     AS CONDITION_PRESC_RESTREINTE,
                        spcpd_typage    AS TYPAGE
        FROM sp_specialite spe
                 LEFT JOIN VSPCPD_SPE_CDT_PRESCR spcpd
                      ON spcpd.SPCPD_SP_CODE_FK_PK = spe.SP_CODE_SQ_PK
                          AND spcpd.SPCPD_CDF_STP_CODE_FK_PK IN
                              (''''S11D'''', ''''S11F'''', ''''S11G'''', ''''S11H'''', ''''S11S'''', ''''S12C'''', ''''S153'''', ''''S24'''', ''''S27'''', ''''S46'''', ''''S47'''', ''''S50'''', ''''S96'''')
                 LEFT JOIN cdf_codif cdf
                      ON cdf.CDF_NUMERO_PK = ''''14''''
                          AND cdf.CDF_CODE_PK = spcpd.SPCPD_CDF_STP_CODE_FK_PK
                 JOIN pre_presentation pre
                      ON pre.PRE_SP_CODE_FK = spe.SP_CODE_SQ_PK
        WHERE (SPE.SP_CODE_SQ_PK IN ('' || LISTID || '') OR SPE.SP_CIPUCD IN ('' || LISTID ||
                                    '') OR PRE.PRE_CODE_PK IN ('' || LISTCIP || ''))
        ORDER BY LIBELLE
	'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API Médicaments non substituables MTE
-- EXEMPLE : select GET_THE_NONSUB_MTE ('4561','3400930121429', 1);
CREATE
OR REPLACE FUNCTION GET_THE_NONSUB_MTE(VARCHAR, VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        LISTCIP ALIAS FOR $2;
        TYPID ALIAS FOR $3;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT PRE_CODE_PK                                            AS CIP13,
                        ''''Eligible NON SUBSTITUABLE (MTE) Arrêté du 12/11/2019'''' AS MTE,
                        SP_NOM                                                 AS LIBELLE,
                        PRE_ETAT_COMMER                                        AS ETAT_COMMERCIAL
        FROM PRE_PRESENTATION pre
                 JOIN SP_SPECIALITE spe
                      ON (spe.SP_CODE_SQ_PK = pre.PRE_SP_CODE_FK AND spe.SP_CDF_SLAB_CODE_FK <> ''''7'''')
                 JOIN COSAC_GSP_COMPO_SUBACT cosac
                      ON cosac.COSAC_GSP_CODE_FK_PK = spe.SP_GSP_CODE_FK
                 JOIN SACCPH_SUBACT_CLASSEPH saccph
                      ON cosac.COSAC_GSP_SAC_CODE_FK = saccph.SACCPH_SAC_CODE_FK_PK
                          AND SACCPH_CPH_CODE_FK_PK = ''''ZZA''''
        ORDER BY LIBELLE
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT DISTINCT PRE_CODE_PK                                            AS CIP13,
                        ''''Eligible NON SUBSTITUABLE (MTE) Arrêté du 12/11/2019'''' AS MTE,
                        SP_NOM                                                 AS LIBELLE,
                        PRE_ETAT_COMMER                                        AS ETAT_COMMERCIAL
        FROM PRE_PRESENTATION pre
                 JOIN SP_SPECIALITE spe
                      ON (spe.SP_CODE_SQ_PK = pre.PRE_SP_CODE_FK AND spe.SP_CDF_SLAB_CODE_FK <> ''''7'''')
                 JOIN COSAC_GSP_COMPO_SUBACT cosac
                      ON cosac.COSAC_GSP_CODE_FK_PK = spe.SP_GSP_CODE_FK
                 JOIN SACCPH_SUBACT_CLASSEPH saccph
                      ON cosac.COSAC_GSP_SAC_CODE_FK = saccph.SACCPH_SAC_CODE_FK_PK
                          AND SACCPH_CPH_CODE_FK_PK = ''''ZZA''''
        WHERE (SP_CODE_SQ_PK IN ('' || LISTID || '') OR cast(SP_CIPUCD as text) = ANY (string_to_array('''''' ||
                                    LISTID ||
                                    '''''','''','''')) OR cast(pre_code_pk as text) = ANY (string_to_array('''''' ||
                                    LISTCIP || '''''','''','''')))
        AND PRE_CODE_PK is not NULL
        ORDER BY LIBELLE
	'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API API GET_THE_ETAT_COMMER_CIP etat commercialisation SPE, CIP et UCD
-- EXEMPLE : SELECT  GET_THE_ETAT_COMMER_CIP ('4561,34306,9182681,3400930121429', 2);
CREATE
OR REPLACE FUNCTION GET_THE_ETAT_COMMER_CIP(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CODE_SQ_PK,
                   SP.SP_NOM,
                   SP.SP_NOMLONG,
                   PRE_CODE_PK,
                   COALESCE(PRE_ETAT_COMMER,
                            CASE
                                WHEN SP_DATE_COMMER < CURRENT_DATE THEN ''''D''''
                                ELSE ETAT_COMMERCIALISATION END) as ETAT_COMMER
            FROM SP_SPECIALITE SP
                     JOIN SP_INFORMATIONS INF ON SP.SP_CODE_SQ_PK = INF.SP_CODE_SQ_PK
                     LEFT JOIN PRE_PRESENTATION PRE ON PRE.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK
            ORDER BY SP_NOM, PRE_CODE_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CODE_SQ_PK,
                   SP.SP_NOM,
                   SP.SP_NOMLONG,
                   PRE_CODE_PK,
                   COALESCE(PRE_ETAT_COMMER,
                            CASE
                                WHEN SP_DATE_COMMER < CURRENT_DATE THEN ''''D''''
                                ELSE ETAT_COMMERCIALISATION END) as ETAT_COMMER
            FROM SP_SPECIALITE SP
                     JOIN SP_INFORMATIONS INF ON SP.SP_CODE_SQ_PK = INF.SP_CODE_SQ_PK
                     LEFT JOIN PRE_PRESENTATION PRE ON PRE.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK
            WHERE cast(pre_code_pk as text) = ANY (string_to_array('''''' || LISTID || '''''','''',''''))
            ORDER BY SP_NOM, PRE_CODE_PK

	'';
        END IF;
        IF TYPID = 2 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CODE_SQ_PK,
                   SP.SP_NOM,
                   SP.SP_NOMLONG,
                   PRE_CODE_PK,
                   COALESCE(PRE_ETAT_COMMER,
                            CASE
                                WHEN SP_DATE_COMMER < CURRENT_DATE THEN ''''D''''
                                ELSE ETAT_COMMERCIALISATION END) as ETAT_COMMER
            FROM SP_SPECIALITE SP
                     JOIN SP_INFORMATIONS INF ON SP.SP_CODE_SQ_PK = INF.SP_CODE_SQ_PK
                     LEFT JOIN PRE_PRESENTATION PRE ON PRE.PRE_SP_CODE_FK = SP.SP_CODE_SQ_PK
            WHERE(SP.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')) )
            ORDER BY SP_NOM, PRE_CODE_PK

	'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- API GET_THE_CIP_NGA_CODE retourne pour tout ou partie des spe un code NGA
-- EXEMPLE : select GET_THE_CIP_NGA_CODE('4561,34306,9182681,3400930121429', 1);
CREATE
OR REPLACE FUNCTION GET_THE_CIP_NGA_CODE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''SELECT PRE.PRE_CODE_PK,
                       SPE.SP_NOM,
                       cdfTx.CDF_NOM,
                       VNGA.NGA_CODE_PK,
                       NGA.NGA_LIBELLE
                FROM PRE_PRESENTATION PRE
                         JOIN SP_SPECIALITE SPE ON PRE.PRE_SP_CODE_FK = SPE.SP_CODE_SQ_PK AND SP_CDF_SLAB_CODE_FK <> ''''7''''
                         LEFT JOIN VPRETSS_DERNIER_TAUX VPRE ON VPRE.PRETSS_PRE_CODE_FK_PK = PRE_CODE_PK
                         LEFT JOIN CDF_CODIF cdfTx ON VPRE.CDF_TAUX = cdfTx.CDF_CODE_PK AND cdfTx.CDF_NUMERO_PK = ''''17''''
                         LEFT JOIN VNGAPRE_NGA_PRESENTATION VNGA ON VNGA.PRE_CODE_PK = PRE.PRE_CODE_PK
                         LEFT JOIN NGA_CODE NGA ON NGA.NGA_CODE_PK = VNGA.NGA_CODE_PK
                ORDER BY SPE.SP_NOM, PRE_CODE_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''SELECT PRE.PRE_CODE_PK,
                       SPE.SP_NOM,
                       cdfTx.CDF_NOM,
                       VNGA.NGA_CODE_PK,
                       NGA.NGA_LIBELLE
                FROM PRE_PRESENTATION PRE
                         JOIN SP_SPECIALITE SPE ON PRE.PRE_SP_CODE_FK = SPE.SP_CODE_SQ_PK AND SP_CDF_SLAB_CODE_FK <> ''''7''''
                         LEFT JOIN VPRETSS_DERNIER_TAUX VPRE ON VPRE.PRETSS_PRE_CODE_FK_PK = PRE_CODE_PK
                         LEFT JOIN CDF_CODIF cdfTx ON VPRE.CDF_TAUX = cdfTx.CDF_CODE_PK AND cdfTx.CDF_NUMERO_PK = ''''17''''
                         LEFT JOIN VNGAPRE_NGA_PRESENTATION VNGA ON VNGA.PRE_CODE_PK = PRE.PRE_CODE_PK
                         LEFT JOIN NGA_CODE NGA ON NGA.NGA_CODE_PK = VNGA.NGA_CODE_PK
        WHERE cast(PRE.pre_code_pk as text) = ANY (string_to_array('''''' || LISTID || '''''','''',''''))
        ORDER BY SPE.SP_NOM, PRE_CODE_PK
	'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- DROP FUNCTION GET_THE_VERSION_PUBLIEE();
-- EXEMPLE : select GET_THE_VERSION_PUBLIEE();
CREATE
OR REPLACE FUNCTION GET_THE_VERSION_PUBLIEE() RETURNS REFCURSOR AS
'
    DECLARE
        curRet REFCURSOR;
    BEGIN
        OPEN curRet FOR select EDITEUR,
                               IV_NUM_VERSION_BASE  as VERSION_BASE,
                               IV_DATE_VERSION_BASE as DATE_VERSION_BASE,
                               iv_num_version_api   AS VERSION_API,
                               iv_date_version_api  as DATE_VERSION_API
                        from information_version;
        RETURN curRet;
    END;

' LANGUAGE plpgsql;

--
-- En entrée : CIS, en sortie : tous les CPD associés au CIS en excluant 'S2' et les liste I, II, ...
-- Exemple : select CIS_CPD('''6 068 855 1''');
--
CREATE
OR REPLACE FUNCTION CIS_CPD(VARCHAR) RETURNS REFCURSOR AS
'
    DECLARE
        CIS ALIAS FOR $1;
        curRet REFCURSOR;
    BEGIN
        OPEN CURRET FOR EXECUTE ''SELECT DISTINCT cpd.CDF_NOM AS CPD
                FROM SP_SPECIALITE spe
                         JOIN VSPCPD_SPE_CDT_PRESCR spcpd
                              ON spe.SP_CODE_SQ_PK = spcpd.SPCPD_SP_CODE_FK_PK
                                  AND spcpd.SPCPD_CDF_STP_CODE_FK_PK NOT IN (''''S2'''', ''''S311'''', ''''S312'''', ''''S313'''', ''''S999'''')
                         JOIN CDF_CODIF cpd
                              ON spcpd.SPCPD_CDF_STP_CODE_FK_PK = cpd.CDF_CODE_PK
                                  AND cpd.CDF_NUMERO_PK = ''''14''''
                WHERE spe.SP_NL = '' || CIS || ''
                ORDER BY 1
                '';
        RETURN curRet;
    END;

' LANGUAGE plpgsql;


--
-- En entrée : CIP, en sortie : Dernier prix TTC, Date application, taux de remboursement
-- Exemple : SELECT CIP_PRIX('3400930111017');
--
CREATE
OR REPLACE FUNCTION CIP_PRIX(VARCHAR) RETURNS REFCURSOR AS
'
    DECLARE
        CIP ALIAS FOR $1;
        curRet REFCURSOR;
    BEGIN
        OPEN CURRET FOR EXECUTE ''SELECT pri.PPTTC                   AS DERNIER_PRIX_TTC,
                                       pri.PPTTC_DATE_EFFET        AS DATE_APPLICATION_PRIX,
                                       pri.PPTTC_DATE_OPPOSABILITE AS DATE_OPPOSABILITE,
                                       taux.CDF_NOM                AS TAUX_DE_REMBOURSEMENT
                                FROM PRE_PRESENTATION pre
                                         JOIN CEPS_PRIX pri
                                                   ON pre.PRE_CODE_PK = pri.CIP_ACTUEL
                                         LEFT JOIN VPRETSS_DERNIER_TAUX pretss
                                                   ON pre.PRE_CODE_PK = pretss.PRETSS_PRE_CODE_FK_PK
                                         LEFT JOIN CDF_CODIF taux
                                                   ON pretss.CDF_TAUX = cast ( taux.CDF_CODE_PK as int8)
                                                       AND taux.CDF_NUMERO_PK = ''''17''''
                                WHERE pre.PRE_CODE_PK = ANY (string_to_array('''''' || CIP || '''''','''',''''))
                '';
        RETURN curRet;
    END;

' LANGUAGE plpgsql;

--
-- En entrée : Code SPE ou CIP, en sortie : Statut BIOSIMILAIRE TYPID = 0 => tous sinon 1 par spé ou UCD
-- Exemple : SELECT GET_THE_BIOSIMILAIRE('18385,22844' , 1);
--
CREATE
OR REPLACE FUNCTION GET_THE_BIOSIMILAIRE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, is_biosim(SP.SP_NL) AS BIOSIMILAIRE
            FROM SP_SPECIALITE SP
            ORDER BY SP.SP_NOM
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT SP.SP_CIPUCD AS SP_CIPUCD, SP.SP_CODE_SQ_PK AS SP_CODE_SQ_PK, SP.SP_NOM AS SP_NOM, is_biosim(SP.SP_NL) AS BIOSIMILAIRE
        FROM SP_SPECIALITE SP
            WHERE(SP.SP_CODE_SQ_PK IN ('' || LISTID ||
                                    '') OR cast(SP.SP_CIPUCD as text) = ANY (string_to_array('''''' || LISTID || '''''','''','''')) )
            ORDER BY SP_NOM

	'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

--
-- TFL-1074
-- API EI - 2023-03-16 - En entrée : Liste SPE en sortie : EI TYPID = 0 => tous sinon 1 pour 1 ou plusieurs spé
-- Exemple : select GET_THE_EFFET_INDE_SPE_V2('15130,621,8243', 1);
--
CREATE
OR REPLACE FUNCTION GET_THE_EFFET_INDE_SPE_V2(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1;
        TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT spe.SP_CODE_SQ_PK,
                       spe.SP_NOM,
                       ei.EI_LIBELLE      AS EFFET_INDE,
                       CASE
                           WHEN fei_tf.FEIFREQ_FREQ_CODE_SQ_PK IS NULL
                               THEN ''''NON''''
                           ELSE ''''OUI'''' END AS TRES_FREQ,
                       CASE
                           WHEN fei_f.FEIFREQ_FREQ_CODE_SQ_PK IS NULL
                               THEN ''''NON''''
                           ELSE ''''OUI'''' END AS FREQ,
                       CASE
                           WHEN fei_pf.FEIFREQ_FREQ_CODE_SQ_PK IS NULL
                               THEN ''''NON''''
                           ELSE ''''OUI'''' END AS PEU_FREQ,
                       CASE
                           WHEN fei_r.FEIFREQ_FREQ_CODE_SQ_PK IS NULL
                               THEN ''''NON''''
                           ELSE ''''OUI'''' END AS RARE_FREQ
                FROM SP_SPECIALITE spe
                         JOIN FEIEI_FEIGSP_EI feiei
                              ON spe.SP_GSP_CODE_FK = feiei.FEIEI_FEIGSP_GSP_CODE_FK_PK
                         LEFT JOIN FEIFREQ_FEI_FREQ fei_tf
                                   ON feiei.FEIEI_EI_CODE_SQ_PK = fei_tf.FEIFREQ_EI_CODE_SQ_PK
                                       AND feiei.FEIEI_FEIGSP_GSP_CODE_FK_PK = fei_tf.FEIFREQ_FEIGSP_GSP_CODE_FK_PK
                                       AND fei_tf.FEIFREQ_FREQ_CODE_SQ_PK = 2
                         LEFT JOIN FEIFREQ_FEI_FREQ fei_f
                                   ON feiei.FEIEI_EI_CODE_SQ_PK = fei_f.FEIFREQ_EI_CODE_SQ_PK
                                       AND feiei.FEIEI_FEIGSP_GSP_CODE_FK_PK = fei_f.FEIFREQ_FEIGSP_GSP_CODE_FK_PK
                                       AND fei_f.FEIFREQ_FREQ_CODE_SQ_PK = 1
                         LEFT JOIN FEIFREQ_FEI_FREQ fei_pf
                                   ON feiei.FEIEI_EI_CODE_SQ_PK = fei_pf.FEIFREQ_EI_CODE_SQ_PK
                                       AND feiei.FEIEI_FEIGSP_GSP_CODE_FK_PK = fei_pf.FEIFREQ_FEIGSP_GSP_CODE_FK_PK
                                       AND fei_pf.FEIFREQ_FREQ_CODE_SQ_PK = 3
                         LEFT JOIN FEIFREQ_FEI_FREQ fei_r
                                   ON feiei.FEIEI_EI_CODE_SQ_PK = fei_r.FEIFREQ_EI_CODE_SQ_PK
                                       AND feiei.FEIEI_FEIGSP_GSP_CODE_FK_PK = fei_r.FEIFREQ_FEIGSP_GSP_CODE_FK_PK
                                       AND fei_r.FEIFREQ_FREQ_CODE_SQ_PK = 4
                         JOIN EI_EFFIN ei
                              ON feiei.FEIEI_EI_CODE_SQ_PK = ei.EI_CODE_SQ_PK
                WHERE fei_tf.FEIFREQ_FREQ_CODE_SQ_PK IS NOT NULL
                   OR fei_f.FEIFREQ_FREQ_CODE_SQ_PK IS NOT NULL
                   OR fei_pf.FEIFREQ_FREQ_CODE_SQ_PK IS NOT NULL
                   OR fei_r.FEIFREQ_FREQ_CODE_SQ_PK IS NOT NULL
                ORDER BY spe.SP_NOM,
                         ei.EI_LIBELLE
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
            SELECT spe.SP_CODE_SQ_PK,
                           spe.SP_NOM,
                           ei.EI_LIBELLE AS EFFET_INDE,
                           CASE
                               WHEN fei_tf.FEIFREQ_FREQ_CODE_SQ_PK IS NULL
                                   THEN ''''NON''''
                               ELSE ''''OUI'''' END AS TRES_FREQ,
                           CASE
                               WHEN fei_f.FEIFREQ_FREQ_CODE_SQ_PK IS NULL
                                   THEN ''''NON''''
                               ELSE ''''OUI'''' END AS FREQ,
                           CASE
                               WHEN fei_pf.FEIFREQ_FREQ_CODE_SQ_PK IS NULL
                                   THEN ''''NON''''
                               ELSE ''''OUI'''' END AS PEU_FREQ,
                           CASE
                               WHEN fei_r.FEIFREQ_FREQ_CODE_SQ_PK IS NULL
                                   THEN ''''NON''''
                               ELSE ''''OUI'''' END AS RARE_FREQ
                    FROM SP_SPECIALITE spe
                             JOIN FEIEI_FEIGSP_EI feiei
                                  ON spe.SP_GSP_CODE_FK = feiei.FEIEI_FEIGSP_GSP_CODE_FK_PK
                             LEFT JOIN FEIFREQ_FEI_FREQ fei_tf
                                       ON feiei.FEIEI_EI_CODE_SQ_PK = fei_tf.FEIFREQ_EI_CODE_SQ_PK
                                           AND feiei.FEIEI_FEIGSP_GSP_CODE_FK_PK = fei_tf.FEIFREQ_FEIGSP_GSP_CODE_FK_PK
                                           AND fei_tf.FEIFREQ_FREQ_CODE_SQ_PK = 2
                             LEFT JOIN FEIFREQ_FEI_FREQ fei_f
                                       ON feiei.FEIEI_EI_CODE_SQ_PK = fei_f.FEIFREQ_EI_CODE_SQ_PK
                                           AND feiei.FEIEI_FEIGSP_GSP_CODE_FK_PK = fei_f.FEIFREQ_FEIGSP_GSP_CODE_FK_PK
                                           AND fei_f.FEIFREQ_FREQ_CODE_SQ_PK = 1
                             LEFT JOIN FEIFREQ_FEI_FREQ fei_pf
                                       ON feiei.FEIEI_EI_CODE_SQ_PK = fei_pf.FEIFREQ_EI_CODE_SQ_PK
                                           AND feiei.FEIEI_FEIGSP_GSP_CODE_FK_PK = fei_pf.FEIFREQ_FEIGSP_GSP_CODE_FK_PK
                                           AND fei_pf.FEIFREQ_FREQ_CODE_SQ_PK = 3
                             LEFT JOIN FEIFREQ_FEI_FREQ fei_r
                                       ON feiei.FEIEI_EI_CODE_SQ_PK = fei_r.FEIFREQ_EI_CODE_SQ_PK
                                           AND feiei.FEIEI_FEIGSP_GSP_CODE_FK_PK = fei_r.FEIFREQ_FEIGSP_GSP_CODE_FK_PK
                                           AND fei_r.FEIFREQ_FREQ_CODE_SQ_PK = 4
                             JOIN EI_EFFIN ei
                                  ON feiei.FEIEI_EI_CODE_SQ_PK = ei.EI_CODE_SQ_PK
                    WHERE (spe.SP_CODE_SQ_PK IN ('' || LISTID || '')
                        OR spe.SP_CIPUCD IN ('' || LISTID || ''))
                    AND (fei_tf.FEIFREQ_FREQ_CODE_SQ_PK IS NOT NULL
                        OR fei_f.FEIFREQ_FREQ_CODE_SQ_PK IS NOT NULL
                        OR fei_pf.FEIFREQ_FREQ_CODE_SQ_PK IS NOT NULL
                        OR fei_r.FEIFREQ_FREQ_CODE_SQ_PK IS NOT NULL)
                ORDER BY spe.SP_NOM,
                         ei.EI_LIBELLE

	'';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- TFL-1306 Création API produits du froid
-- EXEMPLE : select PRODUITS_DU_FROID_PRE('''3400930234433'',''3400939591117'',''3400930083178'',''3400941631825''', 1);
--
CREATE
OR REPLACE FUNCTION PRODUITS_DU_FROID_PRE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
    			SELECT pre.PRE_CODE_PK AS CIP,
                       CASE
                           WHEN preth.PRETH_PRE_CODE_FK_PK IS NOT NULL
                               AND (preth.PRETH_DATEFIN IS NULL OR preth.PRETH_DATEFIN >= now())
                               THEN ''''OUI''''
                           ELSE ''''NON'''' END AS THERMOLABILE
                FROM PRE_PRESENTATION pre
                         LEFT JOIN PRETH_THERMOLABILE preth
                                   ON pre.PRE_CODE_PK = preth.PRETH_PRE_CODE_FK_PK
                ORDER BY pre.PRE_CODE_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
    			SELECT pre.PRE_CODE_PK AS CIP,
                       CASE
                           WHEN preth.PRETH_PRE_CODE_FK_PK IS NOT NULL
                               AND (preth.PRETH_DATEFIN IS NULL OR preth.PRETH_DATEFIN >= now())
                               THEN ''''OUI''''
                           ELSE ''''NON'''' END AS THERMOLABILE
                FROM PRE_PRESENTATION pre
                         LEFT JOIN PRETH_THERMOLABILE preth
                                   ON pre.PRE_CODE_PK = preth.PRETH_PRE_CODE_FK_PK
                WHERE pre.PRE_CODE_PK IN ('' || LISTID || '')
                ORDER BY pre.PRE_CODE_PK
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;
