CREATE
OR REPLACE FUNCTION INTERVAL_PRISE_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; TYPID ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF TYPID = 0 THEN
            OPEN CURRET FOR EXECUTE ''
    			SELECT DISTINCT spe.SP_CODE_SQ_PK,
                                spe.SP_NOM,
                                cbiof.CBIOF_NUMSEQ_PK AS NUM_ORDRE,
                                cbiof.CBIOF_INTER_VAL AS VALEUR,
                                cbioi.CBIOI_LIBELLE   AS UNITE,
                                cbiof.CBIOF_COM       AS COMMENTAIRE
                FROM SP_SPECIALITE spe
                         JOIN CBIOF_CHRONOBIO_FREQ cbiof
                              ON spe.SP_GSP_CODE_FK = cbiof.CBIOF_GSP_CODE_FK_PK
                         JOIN CBIOI_CHRONOBIO_INTERVALLE cbioi
                              ON cbiof.CBIOF_CBIOI_CODE_FK = cbioi.CBIOI_CODE_PK
                ORDER BY spe.SP_NOM,
                         cbiof.CBIOF_NUMSEQ_PK
        '';
        END IF;
        IF TYPID = 1 THEN
            OPEN CURRET FOR EXECUTE ''
    			SELECT DISTINCT spe.SP_CODE_SQ_PK,
                                spe.SP_NOM,
                                cbiof.CBIOF_NUMSEQ_PK AS NUM_ORDRE,
                                cbiof.CBIOF_INTER_VAL AS VALEUR,
                                cbioi.CBIOI_LIBELLE   AS UNITE,
                                cbiof.CBIOF_COM       AS COMMENTAIRE
                FROM SP_SPECIALITE spe
                         JOIN CBIOF_CHRONOBIO_FREQ cbiof
                              ON spe.SP_GSP_CODE_FK = cbiof.CBIOF_GSP_CODE_FK_PK
                         JOIN CBIOI_CHRONOBIO_INTERVALLE cbioi
                              ON cbiof.CBIOF_CBIOI_CODE_FK = cbioi.CBIOI_CODE_PK
                WHERE spe.SP_CODE_SQ_PK IN ('' || LISTID || '')
                   OR spe.SP_CIPUCD IN ('' || LISTID || '')
                ORDER BY spe.SP_NOM,
                         cbiof.CBIOF_NUMSEQ_PK
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

