                       UCDATUC_INDIC_ATUC,
                       UCDATUC_CODE_INDIC,
                       UCDATUC_LIBELLE_UCD,
                       UCDATUC_UCD13,
                       CASE WHEN UCDATUC_RH = 1 THEN ''''OUI''''
                            WHEN UCDATUC_RH = 0 THEN ''''NON'''' END AS UCDATUC_RH,
                       UCDATUC_COM
                FROM UCDATUC_ATU_C ucdatuc
                ORDER BY 1
        '';
        END IF;
        IF VARTYP = 1 THEN
            OPEN CURRET FOR EXECUTE ''
    			SELECT UCDATUC_UCD7,
                       UCDATUC_DATE_MAJ,
                       UCDATUC_NOM,
                       UCDATUC_SUBACT,
                       UCDATUC_LABO,
                       UCDATUC_STATUT_ATU,
                       UCDATUC_DATE_DEB_ATU,
                       UCDATUC_DATE_FIN_ATU,
                       UCDATUC_INDIC_ATUC,
                       UCDATUC_CODE_INDIC,
                       UCDATUC_LIBELLE_UCD,
                       UCDATUC_UCD13,
                       CASE WHEN UCDATUC_RH = 1 THEN ''''OUI''''
                            WHEN UCDATUC_RH = 0 THEN ''''NON'''' END AS UCDATUC_RH,
                       UCDATUC_COM
                FROM UCDATUC_ATU_C ucdatuc
                WHERE UCDATUC_UCD7 IN ('''''' || LISTID || '''''')
                ORDER BY 1
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

