                           UCDAP_NOM,
                           UCDAP_STATUT,
                           UCDAP_STATUT_ANTERIEUR,
                           UCDAP_INDIC_THERA,
                           UCDAP_PEC_PRECOCE,
                           UCDAP_DATE_DEB_AAP,
                           UCDAP_DATE_DEB_ATU,
                           UCDAP_DATE_ECHEANCE_AAP,
                           UCDAP_DATE_AMM,
                           UCDAP_DATE_FIN_AAP,
