                           UCDAP_SUSPENSION_AAP,
                           CASE
                               WHEN UCDAP_INIT_NOUV_TRT = 1 THEN ''''OUI''''
                               WHEN UCDAP_INIT_NOUV_TRT = 0 THEN ''''NON''''
                               ELSE ''''*'''' END                     AS UCDAP_INIT_NOUV_TRT,
