                           UCDAP_DATE_MAJ
                    FROM UCDAP_AP ucdap
                    WHERE UCDAP_UCD7 IN ('''''' || LISTID || '''''')
                ORDER BY 1
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- EXEMPLE : select AAC_SPE ('''9000429''', 1);
CREATE
OR REPLACE FUNCTION AAC_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; VARTYP ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF VARTYP = 0 THEN
            OPEN CURRET FOR EXECUTE ''
    			SELECT UCDAAC_UCD7,
                       UCDAAC_CODE_INDIC,
                       UCDAAC_LABO,
                       UCDAAC_DCI,
                       UCDAAC_NOM,
                       UCDAAC_STATUT,
                       UCDAAC_STATUT_ANTERIEUR,
                       CASE
                           WHEN UCDAAC_PEC_CONT = 1 THEN ''''OUI''''
                           WHEN UCDAAC_PEC_CONT = 0 THEN ''''NON''''
                           WHEN UCDAAC_PEC_CONT = 2 THEN ''''SO''''
                           ELSE ''''*'''' END              AS UCDAAC_PEC_CONT,
                       UCDAAC_DATE_FIN_PEC_CONT,
                       UCDAAC_DATE_PREMIERE_AAC,
                       UCDAAC_INDIC_THERA,
                       UCDAAC_AAP_OCTROYEE,
                       UCDAAC_DATE_PREMIERE_AMM,
                       CASE
                           WHEN UCDAAC_STATUT_AMM = 1 THEN ''''OUI''''
                           WHEN UCDAAC_STATUT_AMM = 0 THEN ''''NON''''
                           WHEN UCDAAC_STATUT_AMM = 2 THEN ''''SO''''
                           ELSE ''''*'''' END              AS UCDAAC_STATUT_AMM,
                       UCDAAC_LIBELLE_INDIC_AMM,
                       UCDAAC_DATE_FIN_AAC,
                       UCDAAC_DATE_FIN_PEC_ASSOC,
                       UCDAAC_MOTIF_ARRET_AAC,
                       CASE
                           WHEN UCDAAC_INIT_NOUV_TRT = 1 THEN ''''OUI''''
                           ELSE ''''NON'''' END            AS UCDAAC_INIT_NOUV_TRT,
                       CASE
                           WHEN UCDAAC_RH = 0 THEN ''''NON''''
                           WHEN UCDAAC_RH = 1 THEN ''''OUI''''
                           ELSE ''''Non disponible'''' END AS UCDAAC_RH,
                       UCDAAC_LIBELLE_UCD,
                       UCDAAC_DATE_MAJ
                FROM UCDAAC_AAC ucdaac
                ORDER BY 1
        '';
        END IF;
        IF VARTYP = 1 THEN
            OPEN CURRET FOR EXECUTE ''
    			SELECT UCDAAC_UCD7,
                           UCDAAC_CODE_INDIC,
                           UCDAAC_LABO,
                           UCDAAC_DCI,
                           UCDAAC_NOM,
                           UCDAAC_STATUT,
                           UCDAAC_STATUT_ANTERIEUR,
                           CASE
                               WHEN UCDAAC_PEC_CONT = 1 THEN ''''OUI''''
                               WHEN UCDAAC_PEC_CONT = 0 THEN ''''NON''''
                               WHEN UCDAAC_PEC_CONT = 2 THEN ''''SO''''
                               ELSE ''''*'''' END              AS UCDAAC_PEC_CONT,
                           UCDAAC_DATE_FIN_PEC_CONT,
                           UCDAAC_DATE_PREMIERE_AAC,
                           UCDAAC_INDIC_THERA,
                           UCDAAC_AAP_OCTROYEE,
                           UCDAAC_DATE_PREMIERE_AMM,
                           CASE
                               WHEN UCDAAC_STATUT_AMM = 1 THEN ''''OUI''''
                               WHEN UCDAAC_STATUT_AMM = 0 THEN ''''NON''''
                               WHEN UCDAAC_STATUT_AMM = 2 THEN ''''SO''''
                               ELSE ''''*'''' END              AS UCDAAC_STATUT_AMM,
                           UCDAAC_LIBELLE_INDIC_AMM,
                           UCDAAC_DATE_FIN_AAC,
                           UCDAAC_DATE_FIN_PEC_ASSOC,
                           UCDAAC_MOTIF_ARRET_AAC,
                           CASE
                               WHEN UCDAAC_INIT_NOUV_TRT = 1 THEN ''''OUI''''
                               ELSE ''''NON'''' END            AS UCDAAC_INIT_NOUV_TRT,
                           CASE
                               WHEN UCDAAC_RH = 0 THEN ''''NON''''
                               WHEN UCDAAC_RH = 1 THEN ''''OUI''''
                               ELSE ''''Non disponible'''' END AS UCDAAC_RH,
                           UCDAAC_LIBELLE_UCD,
                           UCDAAC_DATE_MAJ
                    FROM UCDAAC_AAC ucdaac
                    WHERE UCDAAC_UCD7 IN ('''''' || LISTID || '''''')
                ORDER BY 1
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

