-- EXEMPLE : select CPC_SPE('''9453973''', 1);
--
CREATE
OR REPLACE FUNCTION CPC_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; VARTYP ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
