                       UCDCPC_STATUT,
                       UCDCPC_PEC_CONT_TRT,
                       UCDCPC_DATE_FIN_PEC_CONT_TRT,
                       UCDCPC_DATE_DEB_CPC,
                       UCDCPC_DATE_RENOUVELLEMENT,
                       UCDCPC_DATE_FIN_CPC,
                       UCDCPC_MOTIF_ARRET,
                       CASE
                           WHEN UCDCPC_INIT_NOUV_TRT = 1 THEN ''''OUI''''
                           WHEN UCDCPC_INIT_NOUV_TRT = 0 THEN ''''NON'''' END AS UCDCPC_INIT_NOUV_TRT,
                       CASE
                           WHEN UCDCPC_RH_AMM = 1 THEN ''''OUI''''
                           WHEN UCDCPC_RH_AMM = 0 THEN ''''NON'''' END AS UCDCPC_RH_AMM,
                       CASE
                           WHEN UCDCPC_DISP_VILLE = 1 THEN ''''OUI''''
                           WHEN UCDCPC_DISP_VILLE = 0 THEN ''''NON'''' END AS UCDCPC_DISP_VILLE,
                       UCDCPC_UCD13,
                       UCDCPC_COM,
                       UCDCPC_DATE_MAJ
                FROM UCDCPC_CPC ucdcpc
                ORDER BY 1
        '';
        END IF;
        IF VARTYP = 1 THEN
            OPEN CURRET FOR EXECUTE ''
    			SELECT UCDCPC_UCD7,
                           UCDCPC_CODE_INDIC,
                           UCDCPC_LABO,
                           UCDCPC_DCI,
                           UCDCPC_NOM_SPE,
                           UCDCPC_INDIC_THERA,
                           UCDCPC_STATUT,
                           UCDCPC_PEC_CONT_TRT,
                           UCDCPC_DATE_FIN_PEC_CONT_TRT,
                           UCDCPC_DATE_DEB_CPC,
                           UCDCPC_DATE_RENOUVELLEMENT,
                           UCDCPC_DATE_FIN_CPC,
                           UCDCPC_MOTIF_ARRET,
                           CASE
                               WHEN UCDCPC_INIT_NOUV_TRT = 1 THEN ''''OUI''''
                               WHEN UCDCPC_INIT_NOUV_TRT = 0 THEN ''''NON'''' END AS UCDCPC_INIT_NOUV_TRT,
                           CASE
                               WHEN UCDCPC_RH_AMM = 1 THEN ''''OUI''''
                               WHEN UCDCPC_RH_AMM = 0 THEN ''''NON'''' END AS UCDCPC_RH_AMM,
                           CASE
                               WHEN UCDCPC_DISP_VILLE = 1 THEN ''''OUI''''
                               WHEN UCDCPC_DISP_VILLE = 0 THEN ''''NON'''' END AS UCDCPC_DISP_VILLE,
                           UCDCPC_UCD13,
                           UCDCPC_COM,
                           UCDCPC_DATE_MAJ
                    FROM UCDCPC_CPC ucdcpc
                    WHERE ucdcpc.UCDCPC_UCD7 IN ('''''' || LISTID || '''''')
                ORDER BY 1
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;

-- EXEMPLE : select ATUN_SPE('''9445873''', 1)
--
CREATE
OR REPLACE FUNCTION ATUN_SPE(VARCHAR, NUMERIC) RETURNS REFCURSOR AS
'
    DECLARE
        LISTID ALIAS FOR $1; VARTYP ALIAS FOR $2;
        CURRET REFCURSOR;
    BEGIN
        IF VARTYP = 0 THEN
            OPEN CURRET FOR EXECUTE ''
    			SELECT UCDATUN_UCD7,
                       UCDATUN_DATEMAJ,
                       UCDATUN_NOM,
                       UCDATUN_SUBACT,
                       CASE
                           WHEN UCDATUN_AC_INDIC = 1 THEN ''''OUI''''
                           WHEN UCDATUN_AC_INDIC = 0 THEN ''''NON'''' END AS UCDATUN_AC_INDIC,
                       CASE
                           WHEN UCDATUN_PEC_CONT = 1 THEN ''''OUI''''
                           WHEN UCDATUN_PEC_CONT = 0 THEN ''''NON'''' END AS UCDATUN_PEC_CONT,
                       UCDATUN_LABO,
                       UCDATUN_DATE_DEB,
                       UCDATUN_DATE_FIN,
                       UCDATUN_INDIC,
                       UCDATUN_CODE_INDIC_DGOS,
                       UCDATUN_LIBELLE_UCD,
                       UCDATUN_UCD13,
                       CASE
                           WHEN UCDATUN_RH = 1 THEN ''''OUI''''
                           WHEN UCDATUN_RH = 0 THEN ''''NON'''' END       AS UCDATUN_RH
                FROM UCDATUN_ATU_N ucdatun
                ORDER BY 1
        '';
        END IF;
        IF VARTYP = 1 THEN
            OPEN CURRET FOR EXECUTE ''
    			SELECT UCDATUN_UCD7,
                           UCDATUN_DATEMAJ,
                           UCDATUN_NOM,
                           UCDATUN_SUBACT,
                           CASE
                               WHEN UCDATUN_AC_INDIC = 1 THEN ''''OUI''''
                               WHEN UCDATUN_AC_INDIC = 0 THEN ''''NON'''' END AS UCDATUN_AC_INDIC,
                           CASE
                               WHEN UCDATUN_PEC_CONT = 1 THEN ''''OUI''''
                               WHEN UCDATUN_PEC_CONT = 0 THEN ''''NON'''' END AS UCDATUN_PEC_CONT,
                           UCDATUN_LABO,
                           UCDATUN_DATE_DEB,
                           UCDATUN_DATE_FIN,
                           UCDATUN_INDIC,
                           UCDATUN_CODE_INDIC_DGOS,
                           UCDATUN_LIBELLE_UCD,
                           UCDATUN_UCD13,
                           CASE
                               WHEN UCDATUN_RH = 1 THEN ''''OUI''''
                               WHEN UCDATUN_RH = 0 THEN ''''NON'''' END       AS UCDATUN_RH
                    FROM UCDATUN_ATU_N ucdatun
                    WHERE ucdatun.UCDATUN_UCD7 IN ('''''' || LISTID || '''''')
                ORDER BY 1
        '';
        END IF;
        RETURN CURRET;
    END;

' LANGUAGE PLPGSQL;
-- END TFL-1404

CREATE
OR REPLACE FUNCTION PHARMACODYNAMIQUE(VARCHAR) RETURNS REFCURSOR AS
'
    DECLARE
        CODE ALIAS FOR $1;
        curRet REFCURSOR;
    BEGIN
        OPEN CURRET FOR EXECUTE ''SELECT spe.SP_CODE_SQ_PK         AS SPE_ID,
                                       gsac.GSAC_CODE_SQ_PK      AS GSAC_ID,
                                       gsac.GSAC_NOM,
                                       gsac.GSAC_PHARMACODYNAMIE AS TXT_PHARMACODYNAMIE
                                FROM SP_SPECIALITE spe
                                         JOIN COSAC_GSP_COMPO_SUBACT cosac
                                              ON spe.SP_GSP_CODE_FK = cosac.COSAC_GSP_CODE_FK_PK
                                         JOIN SAC_SUBACTIVE sac
                                              ON cosac.COSAC_GSP_SAC_CODE_FK = sac.SAC_CODE_SQ_PK
                                         JOIN GSAC_PERE_SUBACT gsac
                                              ON sac.SAC_GSAC_CODE_FK = gsac.GSAC_CODE_SQ_PK
                                WHERE CONCAT(spe.SP_CODE_SQ_PK, '''''''') = '''''' || CODE || ''''''
                                   OR spe.SP_CIPUCD = '''''' || CODE || ''''''
                                '';
                        RETURN curRet;
                    END;

' LANGUAGE plpgsql;
